              points.Add(point3D4);
            }
          }
        }
      }
    }
    if (points.Count > 1)
    {
      LinearPath linearPath = new LinearPath((ICollection<Point3D>) points);
      Entities.Add((Entity) linearPath);
    }
    points.Clear();
