  public void GetPostParameter(ref string AddtionalString, TpPnt9D CamPoint)
  {
    if (AddtionalString.IndexOf("{") < 0)
      return;
    string stringBetweenTwoChar = buFile5.FindStringBetweenTwoChar(AddtionalString, "{", "}");
    if (stringBetweenTwoChar.IndexOf("$") < 0)
      return;
    AddtionalString = AddtionalString.Replace("{", "");
    AddtionalString = AddtionalString.Replace("}", "");
    switch (stringBetweenTwoChar.Trim())
    {
      case "$XPos":
        AddtionalString = AddtionalString.Replace("$XPos", ((TpArcData) CamPoint).P9.X.ToString("f3"));
        break;
      case "$YPos":
        AddtionalString = AddtionalString.Replace("$YPos", ((TpArcData) CamPoint).P9.Y.ToString("f3"));
        break;
      case "$ZPos":
        AddtionalString = AddtionalString.Replace("$ZPos", ((TpArcData) CamPoint).P9.Z.ToString("f3"));
        break;
      case "$APos":
        AddtionalString = AddtionalString.Replace("$APos", ((TpArcData) CamPoint).P9.A.ToString("f3"));
        break;
      case "$BPos":
        AddtionalString = AddtionalString.Replace("$BPos", ((TpArcData) CamPoint).P9.B.ToString("f3"));
        break;
      case "$CPos":
        AddtionalString = AddtionalString.Replace("$CPos", ((TpArcData) CamPoint).P9.C.ToString("f3"));
        break;
    }
  }

