  public void GetEntitiesFronEntityStrings(List<string> SL, ref List<Entity> refEntities)
  {
    bool flag1 = false;
    bool flag2 = false;
    List<Point3D> points = new List<Point3D>();
    refEntities = new List<Entity>();
    for (int index = 0; index <= SL.Count - 1; ++index)
    {
      if (SL[index].Trim() == "</Arc>")
      {
        if (points.Count == 3)
        {
          Arc arc = new Arc(points[0], points[1], points[2], false);
          refEntities.Add((Entity) arc);
        }
        points.Clear();
        flag1 = false;
      }
      if (SL[index].Trim() == "</Line>")
      {
        if (points.Count == 2)
        {
          Line line = new Line(points[0], points[1]);
          refEntities.Add((Entity) line);
        }
        else if (points.Count >= 3)
        {
          LinearPath linearPath = new LinearPath((ICollection<Point3D>) points);
          refEntities.Add((Entity) linearPath);
        }
        points = new List<Point3D>();
        flag2 = false;
      }
      if (flag1 | flag2)
      {
        string[] strArray = SL[index].Trim().Split(';');
        if ((strArray == null ? 0 : (strArray.Length != 0 ? 1 : 0)) != 0)
        {
          if (strArray.Length == 2)
          {
            Point3D point3D = new Point3D();
            if (double.TryParse(strArray[0], out point3D.X) & double.TryParse(strArray[1], out point3D.Y))
              points.Add(point3D);
          }
          else if (strArray.Length >= 3)
          {
            Point3D point3D = new Point3D();
            if (double.TryParse(strArray[0], out point3D.X) & double.TryParse(strArray[1], out point3D.Y) & double.TryParse(strArray[2], out point3D.Z))
              points.Add(point3D);
          }
        }
      }
      if (SL[index].Trim() == "<Arc>")
      {
        points.Clear();
        points = new List<Point3D>();
        flag1 = true;
      }
      if (SL[index].Trim() == "<Line>")
      {
        points.Clear();
        points = new List<Point3D>();
        flag2 = true;
      }
    }
  }

  public void CurveCornerFromBoxSize(
    Point3D StartPoint,
    Point3D EndPoint,
    Point3D BoxMin,
    Point3D BoxMax,
    int Degree,
    double Deviation,
    ClockDirectionType ClockDir,
    ref List<Point3D> calcPoints)
  {
    List<Point3D> point3DList = new List<Point3D>();
    if (ClockDir == ClockDirectionType.CCW)
    {
      if (buConversion5.EQ(StartPoint.X, BoxMax.X) & buConversion5.EQ(EndPoint.Y, BoxMax.Y))
      {
        point3DList.Add(F_NotchEdit.ToPoint3D(StartPoint));
        point3DList.Add(new Point3D(BoxMax.X, BoxMax.Y, StartPoint.Z));
        point3DList.Add(F_NotchEdit.ToPoint3D(EndPoint));
      }
      if (buConversion5.EQ(EndPoint.X, BoxMin.X) & buConversion5.EQ(StartPoint.Y, BoxMax.Y))
      {
        point3DList.Add(F_NotchEdit.ToPoint3D(StartPoint));
        point3DList.Add(new Point3D(BoxMin.X, BoxMax.Y, StartPoint.Z));
        point3DList.Add(F_NotchEdit.ToPoint3D(EndPoint));
      }
      if (buConversion5.EQ(StartPoint.X, BoxMin.X) & buConversion5.EQ(EndPoint.Y, BoxMin.Y))
      {
        point3DList.Add(F_NotchEdit.ToPoint3D(StartPoint));
        point3DList.Add(new Point3D(BoxMin.X, BoxMin.Y, StartPoint.Z));
        point3DList.Add(F_NotchEdit.ToPoint3D(EndPoint));
      }
      if (buConversion5.EQ(EndPoint.X, BoxMax.X) & buConversion5.EQ(StartPoint.Y, BoxMin.Y))
      {
        point3DList.Add(F_NotchEdit.ToPoint3D(StartPoint));
        point3DList.Add(new Point3D(BoxMax.X, BoxMin.Y, StartPoint.Z));
        point3DList.Add(F_NotchEdit.ToPoint3D(EndPoint));
      }
    }
    if (calcPoints == null)
      calcPoints = new List<Point3D>();
    calcPoints.Clear();
    if (point3DList.Count < 3)
      return;
    if (Degree == 0 | Degree == 1)
      calcPoints.AddRange((IEnumerable<Point3D>) point3DList);
    if (Degree < 2)
      return;
    Curve curve = new Curve(Degree, (IList<Point3D>) point3DList);
    curve.Regen(Deviation);
    buVector5.Copy(curve.Vertices, ref calcPoints, 4);
  }

  public void LineaPathToLine(
    List<Entity> refEntities,
    double MinLen,
    HorizontalVertical Direction,
    ref List<Entity> LineEntities)
  {
    if (LineEntities == null)
      LineEntities = new List<Entity>();
    LineEntities.Clear();
    if (Direction == HorizontalVertical.Horizontal)
    {
      for (int index1 = 0; index1 <= refEntities.Count - 1; ++index1)
      {
        if (refEntities[index1] is LinearPath)
        {
          for (int index2 = 1; index2 <= refEntities[index1].Vertices.Length - 1; ++index2)
          {
            if (buConversion5.EQ(refEntities[index1].Vertices[index2 - 1].Y, refEntities[index1].Vertices[index2].Y))
            {
              Point3D point3D1 = F_NotchEdit.ToPoint3D(refEntities[index1].Vertices[index2 - 1]);
              Point3D point3D2 = F_NotchEdit.ToPoint3D(refEntities[index1].Vertices[index2]);
              if (Point3D.Distance(point3D1, point3D2) >= MinLen)
              {
                if (point3D1.X > point3D2.X)
                {
                  Line line = new Line(point3D2, point3D1);
                  LineEntities.Add((Entity) line);
                }
                else
                {
                  Line line = new Line(point3D1, point3D2);
                  LineEntities.Add((Entity) line);
                }
              }
            }
          }
        }
      }
    }
    if (Direction != HorizontalVertical.Vertical)
      return;
    for (int index3 = 0; index3 <= refEntities.Count - 1; ++index3)
    {
      if (refEntities[index3] is LinearPath)
      {
        for (int index4 = 1; index4 <= refEntities[index3].Vertices.Length - 1; ++index4)
        {
          if (buConversion5.EQ(refEntities[index3].Vertices[index4 - 1].X, refEntities[index3].Vertices[index4].X))
          {
            Point3D point3D3 = F_NotchEdit.ToPoint3D(refEntities[index3].Vertices[index4 - 1]);
            Point3D point3D4 = F_NotchEdit.ToPoint3D(refEntities[index3].Vertices[index4]);
            if (Point3D.Distance(point3D3, point3D4) >= MinLen)
            {
              if (point3D3.Y > point3D4.Y)
              {
                Line line = new Line(point3D4, point3D3);
                LineEntities.Add((Entity) line);
              }
              else
              {
                Line line = new Line(point3D3, point3D4);
                LineEntities.Add((Entity) line);
              }
            }
          }
        }
      }
    }
  }

  public void CopyEntitiesToEntities(
    List<buEntity> refEntities,
    ref List<buEntity> copyEntities,
    EntitiesCopySettings Settings)
  {
    if (copyEntities == null)
      copyEntities = new List<buEntity>();
    copyEntities.Clear();
    for (int index1 = 0; index1 <= refEntities.Count - 1; ++index1)
    {
      bool flag1 = true;
      buEntity buEntity = (buEntity) null;
      if (refEntities[index1] is buPoint)
      {
        if (!((KinematicBase5) Settings).AddPoint)
          flag1 = false;
      }
      else if (refEntities[index1] is buAngularDim | refEntities[index1] is buDiametricDim | refEntities[index1] is buLinearDim | refEntities[index1] is buOrdinateDim | refEntities[index1] is buRadialDim)
      {
        if (!((KinematicBase5) Settings).AddDimension)
          flag1 = false;
      }
      else if (refEntities[index1] is buCurve)
      {
        if (!((KinematicBase5) Settings).AddCurve)
        {
          flag1 = false;
        }
        else
        {
          if (((Clamper) Settings).RegenDev > 0.0)
            ((buUpperLine) refEntities[index1]).Regen(((Clamper) Settings).RegenDev);
          if (((Clamper) Settings).CurveToPolyLine)
            buEntity = (buEntity) new buShape(((CustomDataSurrogate) refEntities[index1]).Vertices);
        }
      }
      else if (refEntities[index1] is buArc)
      {
        if (!((KinematicBase5) Settings).AddCircular)
        {
          flag1 = false;
        }
        else
        {
          if (((Clamper) Settings).RegenDev > 0.0)
          {
            if (((PlaneAngle) Settings).ForcePlaneXY)
              ((CustomDataSurrogate) refEntities[index1]).Plane = Plane.XY;
            ((buUpperLine) refEntities[index1]).Regen(((Clamper) Settings).RegenDev);
          }
          if (((Clamper) Settings).ArcToPoyline)
            buEntity = (buEntity) new buShape(((CustomDataSurrogate) refEntities[index1]).Vertices);
        }
      }
      else if (refEntities[index1] is buCircle)
      {
        if (!((KinematicBase5) Settings).AddCircular)
        {
          flag1 = false;
        }
        else
        {
          if (((Clamper) Settings).RegenDev > 0.0)
          {
            if (((PlaneAngle) Settings).ForcePlaneXY)
              ((CustomDataSurrogate) refEntities[index1]).Plane = Plane.XY;
            ((buUpperLine) refEntities[index1]).Regen(((Clamper) Settings).RegenDev);
          }
          if (((Clamper) Settings).CircleToPoyline)
            buEntity = (buEntity) new buShape(((CustomDataSurrogate) refEntities[index1]).Vertices);
          else if (((Clamper) Settings).CircleTo4Arc)
          {
            buArc Arc1 = (buArc) null;
            buArc Arc2 = (buArc) null;
            buArc Arc3 = (buArc) null;
            buArc Arc4 = (buArc) null;
            this.CircletoFourArc((buCircle) refEntities[index1], ref Arc1, ref Arc2, ref Arc3, ref Arc4);
            copyEntities.Add((buEntity) Arc1);
            copyEntities.Add((buEntity) Arc2);
            copyEntities.Add((buEntity) Arc3);
            copyEntities.Add((buEntity) Arc4);
            flag1 = false;
          }
        }
      }
      else if (refEntities[index1] is buEllipse)
      {
        if (!((KinematicBase5) Settings).AddEllipse)
        {
          flag1 = false;
        }
        else
        {
          if (((Clamper) Settings).RegenDev > 0.0)
          {
            if (((PlaneAngle) Settings).ForcePlaneXY)
              ((CustomDataSurrogate) refEntities[index1]).Plane = Plane.XY;
            ((buUpperLine) refEntities[index1]).Regen(((Clamper) Settings).RegenDev);
          }
          if (((Clamper) Settings).EllipseToPoyline)
            buEntity = (buEntity) new buShape(((CustomDataSurrogate) refEntities[index1]).Vertices);
        }
      }
      else if (refEntities[index1] is buCompositeCurve)
      {
        if (!((KinematicBase5) Settings).AddCompositeCurve)
        {
          flag1 = false;
        }
        else
        {
          if (((Clamper) Settings).RegenDev > 0.0)
            ((buUpperLine) refEntities[index1]).Regen(((Clamper) Settings).RegenDev);
          if (((Clamper) Settings).CompositeCurveToEntities)
          {
            List<buEntity> copyEntities1 = new List<buEntity>();
            this.CopyEntitiesToEntities(((CustomDataSurrogate) refEntities[index1]).CurveList, ref copyEntities1, Settings);
            copyEntities.AddRange((IEnumerable<buEntity>) copyEntities1);
            flag1 = false;
          }
        }
      }
      else if (refEntities[index1] is buLinearPath && ((Clamper) Settings).PolylineToLine)
      {
        bool flag2 = true;
        for (int index2 = 1; index2 <= ((CustomDataSurrogate) refEntities[index1]).Vertices.Count - 1; ++index2)
        {
          if (Point3D.Distance(((CustomDataSurrogate) refEntities[index1]).Vertices[index2 - 1], ((CustomDataSurrogate) refEntities[index1]).Vertices[index2]) < ((Clamper) Settings).PolylineToLineMinLength)
          {
            flag2 = false;
            index2 = ((CustomDataSurrogate) refEntities[index1]).Vertices.Count;
          }
        }
        if (flag2)
        {
          List<buEntity> collection = new List<buEntity>();
          for (int index3 = 1; index3 <= ((CustomDataSurrogate) refEntities[index1]).Vertices.Count - 1; ++index3)
          {
            buLine buLine = (buLine) new buMultilineText(((CustomDataSurrogate) refEntities[index1]).Vertices[index3 - 1], ((CustomDataSurrogate) refEntities[index1]).Vertices[index3]);
            collection.Add((buEntity) buLine);
          }
          copyEntities.AddRange((IEnumerable<buEntity>) collection);
          flag1 = false;
        }
        else
          flag1 = true;
      }
      if (flag1 & ((Clamper) Settings).MinLength > 0.0 && ((buUpperLine) refEntities[index1]).Length() < ((Clamper) Settings).MinLength)
        flag1 = false;
      if (flag1)
      {
        if (buEntity == null)
          copyEntities.Add(refEntities[index1]);
        else
          copyEntities.Add(buEntity);
      }
    }
  }

  public void GetSelectedEntitiesInfo(
    Design Viewport,
    ref int SelectedCount,
    ref Point3D pntMin,
