    this.BoxSizeCalculate(refEntities, ref pntMin, ref pntMid, ref pntMax);
  }

  public void MakeIsClosedEntityWithTrim(
    int GoBackCount,
    ref buEntity refLinearPath,
    ref buEntity trimedEntity)
  {
    if (!(GoBackCount >= 2 & GoBackCount <= 4))
      return;
    List<Point3D> copiedPoint = new List<Point3D>();
    buVector5.Copy(((CustomDataSurrogate) refLinearPath).Vertices, ref copiedPoint);
    List<Point3D> points = new List<Point3D>();
    if (GoBackCount == 2)
    {
      points.Add(F_NotchEdit.ToPoint3D(copiedPoint[copiedPoint.Count - 2]));
      points.Add(F_NotchEdit.ToPoint3D(copiedPoint[copiedPoint.Count - 1]));
    }
    if (GoBackCount == 3)
    {
      points.Add(F_NotchEdit.ToPoint3D(copiedPoint[copiedPoint.Count - 3]));
      points.Add(F_NotchEdit.ToPoint3D(copiedPoint[copiedPoint.Count - 2]));
      points.Add(F_NotchEdit.ToPoint3D(copiedPoint[copiedPoint.Count - 1]));
    }
    if (GoBackCount == 4)
    {
      points.Add(F_NotchEdit.ToPoint3D(copiedPoint[copiedPoint.Count - 4]));
      points.Add(F_NotchEdit.ToPoint3D(copiedPoint[copiedPoint.Count - 3]));
      points.Add(F_NotchEdit.ToPoint3D(copiedPoint[copiedPoint.Count - 2]));
      points.Add(F_NotchEdit.ToPoint3D(copiedPoint[copiedPoint.Count - 1]));
    }
    trimedEntity = (buEntity) new buShape(points);
    buText.CopyProperties(refLinearPath, ref trimedEntity);
    if (GoBackCount == 2)
      copiedPoint.RemoveAt(copiedPoint.Count - 1);
    if (GoBackCount == 3)
    {
      copiedPoint.RemoveAt(copiedPoint.Count - 1);
      copiedPoint.RemoveAt(copiedPoint.Count - 1);
    }
    if (GoBackCount == 4)
    {
      copiedPoint.RemoveAt(copiedPoint.Count - 1);
      copiedPoint.RemoveAt(copiedPoint.Count - 1);
      copiedPoint.RemoveAt(copiedPoint.Count - 1);
    }
    refLinearPath = (buEntity) new buShape(copiedPoint);
    buText.CopyProperties(trimedEntity, ref refLinearPath);
  }

  public void EntitiesToEntitiesGroup(
    ref SelectionEntityTypes Entities,
    List<Entity> refEntities,
    bool CompositeCurveToEntity = false)
  {
    Entities = (SelectionEntityTypes) new hmiUIBasicSettings();
    for (int index1 = 0; index1 <= refEntities.Count - 1; ++index1)
    {
      Entity refEntity1 = refEntities[index1];
      if (refEntity1.Selected)
      {
        bool flag = true;
        if (refEntity1 is ICurve && ((ICurve) refEntity1).Length() <= 0.0)
          flag = false;
        if (flag)
        {
          Entity refEntity2 = buVector5.CopyEntities(refEntity1);
          if (refEntity2 is CompositeCurve)
          {
            if (CompositeCurveToEntity)
            {
              CompositeCurve compositeCurve = refEntity2 as CompositeCurve;
              for (int index2 = 0; index2 <= compositeCurve.CurveList.Count - 1; ++index2)
              {
                Entity copiedEntity1 = (Entity) null;
                buRadialDim.Copy((Entity) compositeCurve.CurveList[index2], ref copiedEntity1);
                copiedEntity1.EntityData = (object) new ClipperOffset((CustomData) refEntity2.EntityData);
                if (copiedEntity1.Vertices == null)
                  copiedEntity1.Regen(new RegenParams(buSystem.RegenDeviation));
