  public void EntityToOriginalType(
    buEntity refEntity,
    ref entityOriginalType OriginalType,
    ref double Radius)
  {
    OriginalType = entityOriginalType.None;
    Radius = 0.0;
    if (refEntity.GetType() == typeof (buLine))
      OriginalType = entityOriginalType.Line;
    if (refEntity.GetType() == typeof (buArc))
    {
      OriginalType = entityOriginalType.Arc;
      Radius = ((CustomDataSurrogate) refEntity).Radius;
    }
    if (refEntity.GetType() == typeof (buLinearPath))
      OriginalType = entityOriginalType.LinearPath;
    if (refEntity.GetType() == typeof (buCircle))
    {
      OriginalType = entityOriginalType.Circle;
      Radius = ((CustomDataSurrogate) refEntity).Radius;
    }
    if (refEntity.GetType() == typeof (buEllipse))
      OriginalType = entityOriginalType.Ellipse;
    if (refEntity.GetType() == typeof (buCurve))
      OriginalType = entityOriginalType.Curve;
    if (refEntity.GetType() == typeof (buText))
      OriginalType = entityOriginalType.Text;
    if (refEntity.GetType() == typeof (buPoint))
      OriginalType = entityOriginalType.Point;
    if (refEntity.GetType() == typeof (buRegion))
      OriginalType = entityOriginalType.Region;
    if (refEntity.GetType() == typeof (buMesh))
      OriginalType = entityOriginalType.Mesh;
    if (refEntity.GetType() == typeof (buLinearDim))
      OriginalType = entityOriginalType.Dimenstion;
    if (refEntity.GetType() == typeof (buAngularDim))
      OriginalType = entityOriginalType.Dimenstion;
    if (refEntity.GetType() == typeof (buDiametricDim))
      OriginalType = entityOriginalType.Dimenstion;
    if (refEntity.GetType() == typeof (buRadialDim))
      OriginalType = entityOriginalType.Dimenstion;
    if (refEntity.GetType() == typeof (buOrdinateDim))
      OriginalType = entityOriginalType.Dimenstion;
    if (!(refEntity.GetType() == typeof (buCompositeCurve)))
      return;
    OriginalType = entityOriginalType.CompositeCurve;
  }

  public void CheckEntities(CheckEntitesOption Option, ref List<Entity> Entities)
  {
    for (int index1 = 0; index1 <= Entities.Count - 1; ++index1)
    {
      if (Entities[index1] is ICurve && ((ICurve) Entities[index1]).Length() <= 0.01)
        Entities[index1].Selected = true;
      if (Entities[index1] is LinearPath && ((ICurve) Entities[index1]).Length() <= 0.001)
        Entities[index1].Selected = true;
      if (Entities[index1].Vertices != null)
      {
        if (Entities[index1].Vertices.Length == 0)
          Entities[index1].Selected = true;
        if (Entities[index1].Vertices.Length == 1)
          Entities[index1].Selected = true;
      }
      for (int index2 = index1 + 1; index2 <= Entities.Count - 1; ++index2)
      {
        if (!Entities[index2].Selected && this.isEntitySame(Entities[index1], Entities[index2]) && Option.RemoveSameEntities)
          Entities[index2].Selected = true;
      }
      if (!Entities[index1].Selected & Option.ConvertCircleToArc && Entities[index1].GetType() == typeof (Circle))
      {
        Entities[index1].Selected = true;
        Entity Arc1 = (Entity) null;
        Entity Arc2 = (Entity) null;
        Entity Arc3 = (Entity) null;
        Entity Arc4 = (Entity) null;
        this.CircletoFourArc((Circle) Entities[index1], ref Arc1, ref Arc2, ref Arc3, ref Arc4);
        Entities.Add(Arc1);
        Entities.Add(Arc2);
        Entities.Add(Arc3);
        Entities.Add(Arc4);
      }
      if (!Entities[index1].Selected & Option.DevideArcIfGreater180 && Entities[index1].GetType() == typeof (Arc) && ((Arc) Entities[index1]).AngleInDegrees > 170.0)
      {
        Entity Arc1 = (Entity) null;
        Entity Arc2 = (Entity) null;
        this.ArcToTwoArc((Arc) Entities[index1], ref Arc1, ref Arc2);
        Entities.Add(Arc1);
        Entities.Add(Arc2);
        Entities[index1].Selected = true;
      }
      if (Entities[index1].GetType() == typeof (devDept.Eyeshot.Entities.Point) & Option.RemovePoints)
        Entities[index1].Selected = true;
      if (Entities[index1].GetType() == typeof (CompositeCurve) & Option.CompositeCurveToEntities)
      {
        Entities[index1].Selected = true;
        for (int index3 = 0; index3 <= ((CompositeCurve) Entities[index1]).CurveList.Count - 1; ++index3)
        {
          Entity copiedEntity = (Entity) null;
          buRadialDim.Copy((Entity) ((CompositeCurve) Entities[index1]).CurveList[index3], ref copiedEntity);
          if (copiedEntity != null)
          {
            this.CopyEntityProperties(Entities[index1], ref copiedEntity);
            Entities.Add(copiedEntity);
          }
        }
      }
      if (Entities[index1].GetType() == typeof (Curve) & Option.CurveToLinearPath)
      {
        if (Entities[index1].Vertices == null)
          Entities[index1].Regen(0.02);
        List<Point3D> points = new List<Point3D>();
        for (int index4 = 0; index4 <= Entities[index1].Vertices.Length - 1; ++index4)
          points.Add(F_NotchEdit.ToPoint3D(Entities[index1].Vertices[index4]));
        if (points.Count >= 2)
        {
          Entities[index1].Selected = true;
          Entity copiedEntity = (Entity) new LinearPath((ICollection<Point3D>) points);
          this.CopyEntityProperties(Entities[index1], ref copiedEntity);
          Entities.Add(copiedEntity);
        }
      }
    }
    int num = 0;
    for (int index = Entities.Count - 1; index >= 0; --index)
    {
      if (Entities[index].Selected)
      {
        Entities.RemoveAt(index);
        ++num;
      }
    }
    for (int index = 0; index <= Entities.Count - 1; ++index)
    {
      if (index == 706)
      {
        Entity entity = Entities[index];
      }
      if (Option.ForceDefaultLayer)
        Entities[index].LayerName = "Default";
      if (Option.ColorFromEntity)
      {
        Entities[index].Color = Option.EntityColor;
        Entities[index].ColorMethod = colorMethodType.byEntity;
      }
      if (Option.ThicknessFromEntity)
      {
        Entities[index].LineWeight = (float) Option.EntityThickness;
        Entities[index].LineWeightMethod = colorMethodType.byEntity;
      }
    }
  }

  public void ExtendEntitiesIfOpenContour(
    ref buEntity refEntity,
    Plane refPlane,
    double LeadInDistance,
    double LeadOutDistance)
  {
    if (refEntity.GetType() == typeof (buLine))
    {
      if (LeadInDistance > 0.0)
      {
        double Angle = this.PointAngle(((CustomData) refEntity).StartPoint, ((CustomData) refEntity).EndPoint, refPlane);
        Point3D EndPnt = new Point3D();
        this.LineWithLengthAndAngle(((CustomData) refEntity).StartPoint, LeadInDistance, Angle, refPlane, ref EndPnt);
        buLine buLine = refEntity as buLine;
        ((CustomData) buLine).StartPoint = EndPnt;
        ((buUpperLine) buLine).Update((buEntityUpdateType) 2);
      }
      if (LeadOutDistance <= 0.0)
        return;
      double Angle1 = this.PointAngle(((CustomData) refEntity).EndPoint, ((CustomData) refEntity).StartPoint, refPlane);
      Point3D EndPnt1 = new Point3D();
      this.LineWithLengthAndAngle(((CustomData) refEntity).EndPoint, LeadOutDistance, Angle1, refPlane, ref EndPnt1);
      buLine buLine1 = refEntity as buLine;
      ((CustomData) buLine1).EndPoint = EndPnt1;
      ((buUpperLine) buLine1).Update((buEntityUpdateType) 2);
    }
    else
    {
      if (!(refEntity.GetType() == typeof (buCompositeCurve)))
        return;
      buCompositeCurve buCompositeCurve = refEntity as buCompositeCurve;
      if (((CustomDataSurrogate) buCompositeCurve).CurveList.Count <= 0)
        return;
      List<buEntity> curveList = new List<buEntity>();
      for (int index = 0; index <= ((CustomDataSurrogate) buCompositeCurve).CurveList.Count - 1; ++index)
      {
        bool flag = false;
        if (LeadInDistance > 0.0 & index == 0 && ((CustomDataSurrogate) buCompositeCurve).CurveList[index] is buLine)
        {
          buLine curve = ((CustomDataSurrogate) buCompositeCurve).CurveList[index] as buLine;
          double Angle = this.PointAngle(((CustomData) curve).StartPoint, ((CustomData) curve).EndPoint, refPlane);
          Point3D EndPnt = new Point3D();
          this.LineWithLengthAndAngle(((CustomData) curve).StartPoint, LeadInDistance, Angle, refPlane, ref EndPnt);
          ((CustomData) curve).StartPoint = EndPnt;
          ((buUpperLine) curve).Update((buEntityUpdateType) 2);
          curveList.Add((buEntity) curve);
          flag = true;
        }
        if (LeadOutDistance > 0.0 & index == ((CustomDataSurrogate) buCompositeCurve).CurveList.Count - 1 && ((CustomDataSurrogate) buCompositeCurve).CurveList[index] is buLine)
        {
          buLine curve = ((CustomDataSurrogate) buCompositeCurve).CurveList[index] as buLine;
          double Angle = this.PointAngle(((CustomData) curve).EndPoint, ((CustomData) curve).StartPoint, refPlane);
          Point3D EndPnt = new Point3D();
          this.LineWithLengthAndAngle(((CustomData) curve).EndPoint, LeadOutDistance, Angle, refPlane, ref EndPnt);
          ((CustomData) curve).EndPoint = EndPnt;
          ((buUpperLine) curve).Update((buEntityUpdateType) 2);
        }
        if (!flag)
          curveList.Add(buAngularDim.Copy(((CustomDataSurrogate) buCompositeCurve).CurveList[index]));
      }
      if (curveList.Count <= 0 || curveList.Count != ((CustomDataSurrogate) buCompositeCurve).CurveList.Count)
        return;
      refEntity = (buEntity) new buShapeCircle(curveList);
    }
  }

