  public void GetTangentAngleOfEntity(
    buEntity RefEntity,
    Plane Plane,
    ref double StartAngle,
    ref double EndAngle)
  {
    if (RefEntity.GetType() == typeof (buArc))
    {
      StartAngle = ((CustomDataSurrogate) RefEntity).StartAngle + 90.0;
      EndAngle = ((CustomDataSurrogate) RefEntity).EndAngle + 90.0;
    }
    else if (RefEntity.GetType() == typeof (buLine))
    {
      StartAngle = this.PointAngle(((CustomDataSurrogate) RefEntity).Vertices[((CustomDataSurrogate) RefEntity).Vertices.Count - 1], ((CustomDataSurrogate) RefEntity).Vertices[((CustomDataSurrogate) RefEntity).Vertices.Count - 2], Plane);
      EndAngle = StartAngle;
    }
    else if (RefEntity.GetType() == typeof (buLinearPath))
    {
      StartAngle = this.PointAngle(((CustomDataSurrogate) RefEntity).Vertices[1], ((CustomDataSurrogate) RefEntity).Vertices[0], Plane);
      EndAngle = this.PointAngle(((CustomDataSurrogate) RefEntity).Vertices[((CustomDataSurrogate) RefEntity).Vertices.Count - 1], ((CustomDataSurrogate) RefEntity).Vertices[((CustomDataSurrogate) RefEntity).Vertices.Count - 2], Plane);
    }
    else
    {
      StartAngle = this.PointAngle(((CustomDataSurrogate) RefEntity).Vertices[1], ((CustomDataSurrogate) RefEntity).Vertices[0], Plane);
      EndAngle = this.PointAngle(((CustomDataSurrogate) RefEntity).Vertices[((CustomDataSurrogate) RefEntity).Vertices.Count - 1], ((CustomDataSurrogate) RefEntity).Vertices[((CustomDataSurrogate) RefEntity).Vertices.Count - 2], Plane);
    }
  }

  public void GetClosestEntityToRefPoint(
    List<Entity> refEntities,
    Point3D refPoint,
    ref Entity foundEntity,
    double LimitDistance = 0.0)
  {
    double num1 = double.MaxValue;
    int index1 = -1;
    if (refPoint == (Point3D) null)
      return;
    for (int index2 = 0; index2 <= refEntities.Count - 1; ++index2)
    {
      if (refEntities[index2] is ICurve)
      {
        ICurve refEntity = refEntities[index2] as ICurve;
        double t = 0.0;
        refEntity.ClosestPointTo(refPoint, out t);
        double num2 = Point3D.Distance(refEntity.PointAt(t), refPoint);
        if (LimitDistance == 0.0)
        {
          if (num2 < num1)
          {
            num1 = num2;
            index1 = index2;
          }
        }
        else if (num2 < num1 & num2 <= LimitDistance)
        {
          num1 = num2;
          index1 = index2;
        }
      }
    }
    if (index1 < 0)
      return;
    buRadialDim.Copy(refEntities[index1], ref foundEntity);
  }

