        Properties.Add($"{AppLanguage.CadCamDynamic[68]} = {buString5.ToString(refEntity.BoxMax)}");
        Properties.Add($"{AppLanguage.CadCamDynamic[48 /*0x30*/]} {AppLanguage.CadCamDynamic[53]} = {refEntity.Vertices.Length.ToString()}");
        Properties.Add($"{AppLanguage.CadCamDynamic[0]} = {((ICurve) refEntity).Length().ToString("f3")}");
        if (((ICurve) refEntity).IsClosed)
        {
          List<Point3D> polygon = new List<Point3D>();
          polygon.AddRange((IEnumerable<Point3D>) refEntity.Vertices);
          double num = Utility.PolygonArea<Point3D>((IList<Point3D>) polygon);
          Properties.Add($"{AppLanguage.CadCamDynamic[98]} = {num.ToString("f3")}");
          break;
        }
        List<Point3D> polygon1 = new List<Point3D>();
        polygon1.AddRange((IEnumerable<Point3D>) refEntity.Vertices);
        polygon1.Add(F_NotchEdit.ToPoint3D(polygon1[0]));
        double num1 = Utility.PolygonArea<Point3D>((IList<Point3D>) polygon1);
        Properties.Add($"{AppLanguage.CadCamDynamic[98]} = {num1.ToString("f3")}");
        break;
      case IFace _:
        if (refEntity.BoxMax == (Point3D) null)
          refEntity.Regen(new RegenParams(buSystem.RegenDeviation));
        Properties.Add($"{AppLanguage.CadCamDynamic[67]} = {buString5.ToString(refEntity.BoxMin)}");
        Properties.Add($"{AppLanguage.CadCamDynamic[68]} = {buString5.ToString(refEntity.BoxMax)}");
        Properties.Add($"{AppLanguage.CadCamDynamic[48 /*0x30*/]} {AppLanguage.CadCamDynamic[53]} = {refEntity.Vertices.Length.ToString()}");
        break;
      case devDept.Eyeshot.Entities.Text _:
        if (refEntity.BoxMax == (Point3D) null & DrawingFinisedEventArgs.baseModel != null)
          refEntity.Regen(new RegenParams(buSystem.RegenDeviation, (IWorkspace) DrawingFinisedEventArgs.baseModel));
        Properties.Add($"{AppLanguage.CadCamDynamic[67]} = {((devDept.Eyeshot.Entities.Text) refEntity).TextString}");
        Properties.Add($"{AppLanguage.CadCamDynamic[67]} = {buString5.ToString(refEntity.BoxMin)}");
        Properties.Add($"{AppLanguage.CadCamDynamic[68]} = {buString5.ToString(refEntity.BoxMax)}");
        Properties.Add($"{AppLanguage.CadCamDynamic[48 /*0x30*/]} {AppLanguage.CadCamDynamic[53]} = {refEntity.Vertices.Length.ToString()}");
        break;
      default:
        if (refEntity.BoxMin != (Point3D) null)
          Properties.Add($"{AppLanguage.CadCamDynamic[67]} = {buString5.ToString(refEntity.BoxMin)}");
        if (refEntity.BoxMax != (Point3D) null)
          Properties.Add($"{AppLanguage.CadCamDynamic[68]} = {buString5.ToString(refEntity.BoxMax)}");
        Properties.Add($"{AppLanguage.CadCamDynamic[48 /*0x30*/]} {AppLanguage.CadCamDynamic[53]} = {refEntity.Vertices.Length.ToString()}");
        break;
    }
    Properties.Add($"{AppLanguage.CadCamDynamic[24]} = {refEntity.LayerName}");
  }

  public void EntityCutFromStartAndEndByLength(
    ICurve refCurve,
    double StartDistance,
    double EndDistance,
    ref ICurve cuttedCurve)
  {
    ICurve curve;
    if (StartDistance > 0.0)
    {
      ICurve lower = (ICurve) null;
      ICurve upper = (ICurve) null;
      refCurve.SplitAt(StartDistance, out lower, out upper);
      curve = !(lower != null & upper != null) ? (ICurve) refCurve.Clone() : (!buConversion5.EQ(lower.Length(), StartDistance, 0.1) ? (!buConversion5.EQ(upper.Length(), StartDistance, 0.1) ? (ICurve) refCurve.Clone() : (ICurve) lower.Clone()) : (ICurve) upper.Clone());
    }
    else
      curve = (ICurve) refCurve.Clone();
    if (EndDistance > 0.0)
    {
      ICurve lower = (ICurve) null;
      ICurve upper = (ICurve) null;
      curve.SplitAt(curve.Length() - EndDistance, out lower, out upper);
      curve = !(lower != null & upper != null) ? (ICurve) curve.Clone() : (!buConversion5.EQ(lower.Length(), EndDistance, 0.1) ? (!buConversion5.EQ(upper.Length(), EndDistance, 0.1) ? (ICurve) curve.Clone() : (ICurve) lower.Clone()) : (ICurve) upper.Clone());
    }
    if (curve != null)
      cuttedCurve = curve;
    else
      cuttedCurve = refCurve;
  }

