  public void BreakEntitiesByRefLine(
    List<Entity> refEntities,
    BreakEntitiesByRefLineEventVar Settings,
    ref List<Entity> calcEntities)
  {
    Point3D MinPoint = new Point3D();
    Point3D MidPoint = new Point3D();
    Point3D MaxPoint = new Point3D();
    ICurve curve = (ICurve) null;
    this.BoxSizeCalculate(refEntities, ref MinPoint, ref MidPoint, ref MaxPoint);
    double y = 0.0;
    if (Settings.RefDirection == TopBottomType.Bottom)
    {
      y = MinPoint.Y + (MaxPoint.Y - MinPoint.Y) * Settings.PersentageOfBoxSize / 100.0;
      curve = (ICurve) new Line(new Point3D(MinPoint.X - 10.0, y), new Point3D(MaxPoint.X + 10.0, y));
    }
    List<Entity> BaseRefEntities = new List<Entity>();
    for (int index = 0; index <= refEntities.Count - 1; ++index)
    {
      refEntities[index].Regen(0.01);
      bool flag = false;
      Point3D[] point3DArray = curve.IntersectWith((ICurve) refEntities[index]);
      if (point3DArray != null && point3DArray.Length != 0)
      {
        double t = 0.0;
        ICurve lower = (ICurve) null;
        ICurve upper = (ICurve) null;
        ((ICurve) refEntities[index]).ClosestPointTo(point3DArray[0], out t);
        ((ICurve) refEntities[index]).SplitAt(t, out lower, out upper);
        if (lower != null & upper != null)
        {
          ((Entity) lower).Regen(0.01);
          ((Entity) upper).Regen(0.01);
          if (Settings.RefDirection == TopBottomType.Bottom)
          {
            if (((Entity) lower).BoxMax.Y <= y | buConversion5.EQ(((Entity) lower).BoxMax.Y, y))
              BaseRefEntities.Add((Entity) lower);
            if (((Entity) upper).BoxMax.Y <= y | buConversion5.EQ(((Entity) upper).BoxMax.Y, y))
              BaseRefEntities.Add((Entity) upper);
          }
          flag = true;
        }
      }
      if (!flag && Settings.RefDirection == TopBottomType.Bottom && refEntities[index].BoxMax.Y <= y | buConversion5.EQ(refEntities[index].BoxMax.Y, y))
        BaseRefEntities.Add((Entity) refEntities[index].Clone());
    }
    if (BaseRefEntities.Count <= 0)
      return;
    SortResult Result = (SortResult) new CurveToSurfaceSettingsType();
    SortSettings Settings1 = (SortSettings) new ShapeRuntimeData();
    ((SortbuOptions) ((SortbuFilter) Settings1).Option).Resolution = Settings.SortResolution;
    this.SortEntitiesByRefPoint(new Point3D(MinPoint.X, MaxPoint.Y), ref BaseRefEntities, Settings1, ref calcEntities, ref Result);
  }

