  public void RemoveSmallLengthFromEntityPoints(ref Entity refEntity, double FilterLen)
  {
    if (!(refEntity is ICurve) || !(refEntity is LinearPath))
      return;
    List<Point3D> Vertice = new List<Point3D>();
    CustomData customData = (CustomData) null;
    if (refEntity.EntityData is CustomData)
      customData = (CustomData) new ClipperOffset((CustomData) refEntity.EntityData);
    Vertice.AddRange((IEnumerable<Point3D>) refEntity.Vertices);
    this.RemoveSmallLengthFromPoints(FilterLen, ref Vertice);
    if (Vertice.Count <= 1)
      return;
    refEntity = (Entity) new LinearPath((ICollection<Point3D>) Vertice);
    refEntity.EntityData = (object) customData;
  }

