    for (int index1 = 0; index1 <= Entities.Count - 1; ++index1)
    {
      ICurve entity1 = Entities[index1] as ICurve;
      List<Point3D> points = new List<Point3D>();
      for (int index2 = 0; index2 <= Entities.Count - 1; ++index2)
      {
        if (index1 != index2 & Entities[index1] is ICurve & Entities[index2] is ICurve)
        {
          ICurve entity2 = Entities[index2] as ICurve;
          Point3D[] point3DArray = entity1.IntersectWith(entity2);
          if (point3DArray != null)
          {
            for (int index3 = 0; index3 <= point3DArray.Length - 1; ++index3)
            {
              double t = 0.0;
              entity1.ClosestPointTo(point3DArray[index3], out t);
              if (t > entity1.Domain.t0 & t < entity1.Domain.t1)
                points.Add(F_NotchEdit.ToPoint3D(point3DArray[index3]));
            }
          }
        }
      }
      if (points.Count > 0)
      {
        ICurve[] segments = (ICurve[]) null;
