          {
            Entity entity3 = (Entity) segments[index4];
            entity3.EntityData = (object) new ClipperOffset((CustomData) Entities[index1].EntityData);
            entity3.CopyAttributes(Entities[index1]);
            BrokeEntities.Add(entity3);
          }
        }
      }
      else
      {
        Entity entity4 = (Entity) Entities[index1].Clone();
        entity4.EntityData = (object) new ClipperOffset((CustomData) Entities[index1].EntityData);
        BrokeEntities.Add(entity4);
      }
    }
  }

