  public void EntityDevide(
    Entity refEntity,
    double DevideLength,
    bool DevideAsPolyline,
    ref List<Entity> entitiesDevided)
  {
    entitiesDevided.Clear();
    entitiesDevided = new List<Entity>();
    if (!(refEntity is ICurve))
      return;
    CustomData customData = (CustomData) new ClipperOffset();
    if (refEntity.EntityData != null && refEntity.EntityData is CustomData)
      customData = (CustomData) new ClipperOffset((CustomData) refEntity.EntityData);
    ICurve curve1 = refEntity as ICurve;
    double num1 = (double) Convert.ToInt32(curve1.Length() / DevideLength);
    if (num1 < 1.0)
      num1 = 1.0;
    List<Point3D> points = new List<Point3D>();
    for (double num2 = 0.0; num2 <= num1; ++num2)
    {
      ICurve curve2 = curve1;
      Interval domain = curve1.Domain;
      double min1 = domain.Min;
      double num3 = num2;
      domain = curve1.Domain;
      double max = domain.Max;
      domain = curve1.Domain;
      double min2 = domain.Min;
      double num4 = max - min2;
      double num5 = num3 * num4 / num1;
      double t = min1 + num5;
      Point3D point3D = curve2.PointAt(t);
      if (point3D != (Point3D) null)
      {
        if (num2 < num1)
          points.Add(point3D);
        else if (DevideAsPolyline)
          points.Add(point3D);
      }
    }
    if (points.Count <= 0)
      return;
    if (!DevideAsPolyline)
    {
      ICurve[] segments = (ICurve[]) null;
      curve1.SplitBy((IList<Point3D>) points, out segments);
      if (segments == null)
        return;
      for (int index = 0; index <= segments.Length - 1; ++index)
      {
        Entity entity = (Entity) segments[index];
        entity.EntityData = (object) customData;
        entitiesDevided.Add(entity);
      }
    }
    else
    {
      LinearPath linearPath = new LinearPath((ICollection<Point3D>) points);
      linearPath.EntityData = (object) customData;
      entitiesDevided.Add((Entity) linearPath);
    }
  }

