    this.BoxSizeCalculate(ChekcedEntities, ref MinPoint2, ref MaxPoint2);
    List<Point3D> Points = new List<Point3D>();
    this.EntitiesToPointsWithCamDirection(BaseEntities, buSystem.RegenDeviation, ref Points);
    bool flag1;
    if (this.isBoxSizeInsideBoxSize(MinPoint1, MaxPoint1, MinPoint2, MaxPoint2, refPlane))
    {
      bool flag2 = true;
      for (int index1 = 0; index1 <= ChekcedEntities.Count - 1; ++index1)
      {
        Entity chekcedEntity = ChekcedEntities[index1];
        if (chekcedEntity.Vertices == null)
          chekcedEntity.Regen(new RegenParams(buSystem.RegenDeviation));
        for (int index2 = 0; index2 <= chekcedEntity.Vertices.Length - 1; ++index2)
        {
          if (!((F_EntitiesProps) this).IsPointInsidePolygon(Points, chekcedEntity.Vertices[index2]))
          {
            flag2 = false;
            index2 = chekcedEntity.Vertices.Length;
          }
        }
      }
      flag1 = flag2;
    }
    else
      flag1 = false;
    return flag1;
  }

