  public void Arc3Point(
    Point3D FirstPoint,
    Point3D SecondPoint,
    Point3D ThirdPoint,
    Plane Plane,
    EntityResolution EntResolution,
    ref List<Point3D> Vertices)
  {
    Point3D Center = new Point3D();
    double Radius = 0.0;
    double StartAngle = 0.0;
    double EndAngle = 0.0;
    Vertices.Clear();
    this.Arc3Point(FirstPoint, SecondPoint, ThirdPoint, Plane, EntResolution, ref Center, ref Radius, ref StartAngle, ref EndAngle, ref Vertices);
  }

  public void Arc3Point(
    Point3D FirstPoint,
    Point3D SecondPoint,
    Point3D ThirdPoint,
    Plane Plane,
    ref Point3D Center,
    ref double Radius,
    ref double StartAngle,
    ref double EndAngle)
  {
    List<Point3D> Vertices = new List<Point3D>();
    this.Arc3Point(FirstPoint, SecondPoint, ThirdPoint, Plane, new EntityResolution(), ref Center, ref Radius, ref StartAngle, ref EndAngle, ref Vertices);
  }

  public void Arc3Point(
    Point3D FirstPoint,
    Point3D SecondPoint,
    Point3D ThirdPoint,
    Plane Plane,
    ref buEntity entityArc)
  {
    ClockDirectionType clockDirection = this.GetClockDirection(new List<Point3D>()
    {
      FirstPoint,
      SecondPoint,
      ThirdPoint,
      FirstPoint
    }, Plane);
    bool flip = false;
    if (clockDirection == ClockDirectionType.CW)
      flip = true;
    entityArc = (buEntity) new buEntityList(FirstPoint, SecondPoint, ThirdPoint, flip);
  }

  public int ArcVerticeCountByResolution(
    double Radius,
    double StartAngle,
    double EndAngle,
    EntityResolution EntResolution)
  {
    try
    {
      int num = 10;
      if (EntResolution.ResolutionTypes == EntityResolutionType.ByNumber)
      {
        num = EntResolution.GeometricCount;
        if (num < EntResolution.MinPointCount)
          num = EntResolution.MinPointCount;
      }
      if (EntResolution.ResolutionTypes == EntityResolutionType.ByLength)
      {
        if (buFile5.IsNumeric(Radius.ToString()))
          num = Convert.ToInt32(2.0 * Math.PI * Radius * ((EndAngle - StartAngle) / 360.0) / EntResolution.GeometricLength);
        if (num < EntResolution.MinPointCount)
          num = EntResolution.MinPointCount;
      }
      if (EntResolution.ResolutionTypes == EntityResolutionType.ByLnRadius)
      {
        if (buFile5.IsNumeric(Radius.ToString()) && Radius > 0.0)
          num = Convert.ToInt32(Math.Log(Radius, Math.E) * EntResolution.LnRatio);
        if (num < EntResolution.MinPointCount)
          num = EntResolution.MinPointCount;
      }
      return num;
    }
    catch (Exception ex)
    {
      string str = $"R: {Radius.ToString()} - SA: {StartAngle.ToString()} - EA: {EndAngle.ToString()} - Ent Res:{EntResolution.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return -1;
    }
  }

  public void AnalyseEntities(
