              ((MachineDefPart) entitiesResultError).IndexEntity = ((buDiamakerCalc) refEntities[index1].EntityData).get_OriginalEntityIndex();
            ((MachineDefPart) entitiesResultError).Action = AnalyseEntitiesActionType.Delete;
            ((MachineDefPart) entitiesResultError).pntError = F_NotchEdit.ToPoint3D(this.MiddlePointOfLine(((ICurve) refEntities[index1]).StartPoint, ((ICurve) refEntities[index1]).EndPoint));
