            {
              ((MachineDef) Result).ErrorList.Add(entitiesResultError);
            }
            else
            {
              bool flag = true;
              for (int index3 = 0; index3 <= ((MachineDef) Result).ErrorList.Count - 1; ++index3)
              {
                if (((MachineDefPart) entitiesResultError).IndexEntity == ((MachineDefPart) ((MachineDef) Result).ErrorList[index3]).IndexEntity & ((MachineDefPart) entitiesResultError).ErrorType == ((MachineDefPart) ((MachineDef) Result).ErrorList[index3]).ErrorType)
                {
                  flag = false;
