                ((MachineDefPart) entitiesResultError).IndexEntity = ((buDiamakerCalc) refEntities[index1].EntityData).get_OriginalEntityIndex();
              ((MachineDefPart) entitiesResultError).pntError = F_NotchEdit.ToPoint3D(pntFound);
              ((MachineDefPart) entitiesResultError).Action = AnalyseEntitiesActionType.Fix;
              refEntities[index1].Selected = true;
              ((MachineDef) Result).isError = true;
              if (((MachineDef) Result).ErrorList.Count == 0)
              {
                ((MachineDef) Result).ErrorList.Add(entitiesResultError);
              }
              else
              {
                bool flag = true;
