  public void DirectionWireArrowHeadFromEntities(
    buEntity refEntity,
    Plane refPlane,
    double ArrowHeadLenght,
    double ArrowHeadAngle,
    ref buEntity arrowEntity)
  {
    if (!(refEntity is ICurve))
      return;
    Entity copiedEntity = (Entity) null;
    buAngularDim.Copy(refEntity, ref copiedEntity);
    ICurve curve1 = copiedEntity as ICurve;
    ICurve curve2 = curve1;
    Interval domain = curve1.Domain;
    double mid = domain.Mid;
    Point3D point3D = curve2.PointAt(mid);
    ICurve curve3 = curve1;
    domain = curve1.Domain;
    double t = domain.Mid + 0.1;
    Point3D BasePoint = curve3.PointAt(t);
    new List<Point3D>().Clear();
    List<Point3D> points = new List<Point3D>();
    double num = this.PointAngle(point3D, BasePoint, refPlane);
    Point3D EndPnt1 = new Point3D();
    Point3D EndPnt2 = new Point3D();
    this.LineWithLengthAndAngle(point3D, ArrowHeadLenght, num + ArrowHeadAngle, refPlane, ref EndPnt1);
    this.LineWithLengthAndAngle(point3D, ArrowHeadLenght, num - ArrowHeadAngle, refPlane, ref EndPnt2);
    points.Add(EndPnt1);
    points.Add(point3D);
    points.Add(EndPnt2);
    arrowEntity = (buEntity) new buShape(points);
  }

  public void DirectionWireArrowHeadFromEntities(
    buEntity refEntity,
    Plane refPlane,
    double ArrowHeadLenght,
    double ArrowHeadAngle,
    ref List<Entity> arrowEntities)
  {
    Entity copiedEntity = (Entity) null;
    if (refEntity is buLinearPath)
    {
      if (((CustomData) refEntity).sortDirection == entitySortDirection.Normal)
      {
        for (int index = 1; index <= ((CustomDataSurrogate) refEntity).Vertices.Count - 1; ++index)
        {
          buLine refEntity1 = (buLine) new buMultilineText(((CustomDataSurrogate) refEntity).Vertices[index - 1], ((CustomDataSurrogate) refEntity).Vertices[index]);
          List<Entity> arrowEntities1 = new List<Entity>();
          this.DirectionWireArrowHeadFromEntities((buEntity) refEntity1, refPlane, ArrowHeadLenght, ArrowHeadAngle, ref arrowEntities1);
          arrowEntities.AddRange((IEnumerable<Entity>) arrowEntities1);
        }
      }
      else
      {
        for (int index = ((CustomDataSurrogate) refEntity).Vertices.Count - 2; index >= 0; --index)
        {
          buLine refEntity2 = (buLine) new buMultilineText(((CustomDataSurrogate) refEntity).Vertices[index + 1], ((CustomDataSurrogate) refEntity).Vertices[index]);
          List<Entity> arrowEntities2 = new List<Entity>();
          this.DirectionWireArrowHeadFromEntities((buEntity) refEntity2, refPlane, ArrowHeadLenght, ArrowHeadAngle, ref arrowEntities2);
          arrowEntities.AddRange((IEnumerable<Entity>) arrowEntities2);
        }
      }
    }
    else
    {
      buAngularDim.Copy(refEntity, ref copiedEntity);
      ICurve curve = copiedEntity as ICurve;
      Point3D point3D = curve.PointAt(curve.Domain.Mid);
      Point3D BasePoint = curve.PointAt(curve.Domain.Mid + 0.1);
      new List<Point3D>().Clear();
      List<Point3D> points = new List<Point3D>();
      double num = this.PointAngle(point3D, BasePoint, refPlane);
      if (((CustomData) refEntity).sortDirection == entitySortDirection.Reverse)
        num += 180.0;
      Point3D EndPnt1 = new Point3D();
      Point3D EndPnt2 = new Point3D();
      this.LineWithLengthAndAngle(point3D, ArrowHeadLenght, num + ArrowHeadAngle, refPlane, ref EndPnt1);
      this.LineWithLengthAndAngle(point3D, ArrowHeadLenght, num - ArrowHeadAngle, refPlane, ref EndPnt2);
      points.Add(EndPnt1);
      points.Add(point3D);
      points.Add(EndPnt2);
      LinearPath linearPath = new LinearPath((ICollection<Point3D>) points);
      arrowEntities.Add((Entity) linearPath);
    }
  }

  public void GetArrowPointAndAngleFromEntities(
    Entity refEntity,
    ref Point3D arrowPoint,
    ref double Angle)
  {
    if (!(refEntity is ICurve))
      return;
    ICurve curve = refEntity as ICurve;
    if (refEntity.Vertices == null)
      return;
    if (refEntity.Vertices.Length == 2)
    {
      arrowPoint = this.MiddlePointOfLine(refEntity.Vertices[0], refEntity.Vertices[1]);
      Angle = this.PointAngle(refEntity.Vertices[1], refEntity.Vertices[0]);
    }
    else
    {
      arrowPoint = curve.PointAt(curve.Domain.Mid);
      Point3D BasePoint = curve.PointAt(curve.Domain.Mid - 0.05);
      Angle = this.PointAngle(arrowPoint, BasePoint);
    }
  }

  public void GetArrowPointAndAngleFromEntities(
    buEntity refEntity,
    bool Reverse,
    ref Point3D arrowPoint,
    ref double Angle)
  {
    if (((CustomDataSurrogate) refEntity).Vertices == null)
      return;
    if (((CustomDataSurrogate) refEntity).Vertices.Count == 2)
    {
      arrowPoint = this.MiddlePointOfLine(((CustomDataSurrogate) refEntity).Vertices[0], ((CustomDataSurrogate) refEntity).Vertices[1]);
      Angle = this.PointAngle(((CustomDataSurrogate) refEntity).Vertices[1], ((CustomDataSurrogate) refEntity).Vertices[0]);
    }
    else
    {
      double num1 = 1.0;
      if (Reverse)
        num1 = -1.0;
      ClockDirectionType clockDirection = this.GetClockDirection(((CustomDataSurrogate) refEntity).Vertices);
      double num2 = 0.0;
      int index = ((CustomDataSurrogate) refEntity).Vertices.Count / 2;
      if (index > 0)
      {
        arrowPoint = F_NotchEdit.ToPoint3D(((CustomDataSurrogate) refEntity).Vertices[index]);
        Angle = this.PointAngle(((CustomDataSurrogate) refEntity).Vertices[index], ((CustomDataSurrogate) refEntity).Vertices[index - 1]);
        double num3;
        if (clockDirection == ClockDirectionType.CW)
        {
          num3 = 10.0;
          if (refEntity is buArc | refEntity is buCircle | refEntity is buEllipse)
          {
            double num4 = this.PointAngle(((CustomDataSurrogate) refEntity).Vertices[index - 1], ((CustomDataSurrogate) refEntity).Vertices[index - 2]) + num3;
            num3 = Math.Abs(Angle - num4) * 1.2;
          }
        }
        else
        {
          num3 = -10.0;
          if (refEntity is buArc | refEntity is buCircle | refEntity is buEllipse)
          {
            double num5 = this.PointAngle(((CustomDataSurrogate) refEntity).Vertices[index - 1], ((CustomDataSurrogate) refEntity).Vertices[index - 2]) + num3;
            double num6 = Angle - num5;
            num3 = -Math.Abs(num6 * num6) / 10.0;
          }
        }
        Angle += num1 * num3;
      }
      else
      {
        arrowPoint = this.MiddlePointOfLine(((CustomDataSurrogate) refEntity).Vertices[0], ((CustomDataSurrogate) refEntity).Vertices[1]);
        Angle = this.PointAngle(((CustomDataSurrogate) refEntity).Vertices[1], ((CustomDataSurrogate) refEntity).Vertices[0]) + num2;
      }
    }
  }

