  public void SetSelectedToSortedEntities(List<Entity> SortedEntities, ref Design Viewport)
  {
    for (int index = 0; index <= SortedEntities.Count - 1; ++index)
    {
      if (SortedEntities[index].EntityData != null)
      {
        CustomData entityData = SortedEntities[index].EntityData as CustomData;
        if (((buDiamakerCalc) entityData).get_OriginalEntityIndex() >= 0 & ((buDiamakerCalc) entityData).get_OriginalEntityIndex() <= Viewport.Entities.Count - 1)
          Viewport.Entities[((buDiamakerCalc) entityData).get_OriginalEntityIndex()].Selected = true;
      }
    }
    Viewport.Invalidate();
  }

