  public void ArcWithTwoPointAndRadius(
    Point3D ArcStartPoint,
    Point3D ArcEndPoint,
    double Radius,
    bool CW,
    Plane refPlane,
    ref Point3D ArcCenter,
    ref double ArcSA,
    ref double ArcEA)
  {
    try
    {
      Point3D point3D1 = new Point3D();
      Point3D point3D2 = new Point3D();
      Point3D point3D3 = new Point3D();
      bool flag = false;
      if (Radius < 0.0)
        flag = true;
      Point3D point3D4 = this.MiddlePointOfLine(ArcStartPoint, ArcEndPoint);
      Radius = Math.Abs(Radius);
      if (!buConversion5.EQ(ArcStartPoint.Y, ArcEndPoint.Y))
      {
        double x1 = (ArcStartPoint.X - ArcEndPoint.X) / (ArcEndPoint.Y - ArcStartPoint.Y);
        double x2 = Math.Sqrt(Math.Pow(ArcEndPoint.Y - point3D4.Y, 2.0) + Math.Pow(ArcEndPoint.X - point3D4.X, 2.0));
        double num = Math.Sqrt(Math.Abs(Math.Pow(Radius, 2.0) - Math.Pow(x2, 2.0))) / Math.Sqrt(Math.Pow(x1, 2.0) + 1.0);
        point3D2.Y = point3D4.Y + x1 * num;
        point3D3.Y = point3D4.Y - x1 * num;
        point3D2.X = point3D4.X + num;
        point3D3.X = point3D4.X - num;
        point3D2.Z = ArcStartPoint.Z;
        point3D3.Z = ArcStartPoint.Z;
      }
      else
      {
        double x = Math.Sqrt(Math.Pow(ArcEndPoint.Y - point3D4.Y, 2.0) + Math.Pow(ArcEndPoint.X - point3D4.X, 2.0));
        double d = Math.Pow(Radius, 2.0) - Math.Pow(x, 2.0);
        if (d < 0.0)
          d = 0.0;
        double num = Math.Sqrt(d);
        point3D2.Y = point3D4.Y + num;
        point3D3.Y = point3D4.Y - num;
        point3D2.X = point3D4.X;
        point3D3.X = point3D4.X;
        point3D2.Z = ArcStartPoint.Z;
        point3D3.Z = ArcStartPoint.Z;
      }
      if (CW)
      {
        double num1 = this.PointAngle(ArcStartPoint, point3D2, refPlane);
        double num2 = this.PointAngle(ArcEndPoint, point3D2, refPlane);
        double num3 = this.PointAngle(ArcStartPoint, point3D3, refPlane);
        double num4 = this.PointAngle(ArcEndPoint, point3D3, refPlane);
        if (!flag)
        {
          if (Math.Abs(num1 - num2) <= 180.0 && num1 > num2)
          {
            ArcCenter = F_NotchEdit.ToPoint3D(point3D2);
            ArcSA = num2;
            ArcEA = num1;
            return;
          }
          if (Math.Abs(num3 - num4) <= 180.0 && num3 > num4)
          {
            ArcCenter = F_NotchEdit.ToPoint3D(point3D3);
            ArcSA = num4;
            ArcEA = num3;
            return;
          }
          num1 += 360.0;
          if (Math.Abs(num1 - num2) <= 180.0 && num1 > num2)
          {
            ArcCenter = F_NotchEdit.ToPoint3D(point3D2);
            ArcSA = num2;
            ArcEA = num1;
            return;
          }
          num3 += 360.0;
          if (Math.Abs(num3 - num4) <= 180.0 && num3 > num4)
          {
            ArcCenter = F_NotchEdit.ToPoint3D(point3D3);
            ArcSA = num4;
            ArcEA = num3;
            return;
          }
        }
        if (flag)
        {
          if (Math.Abs(num1 - num2) > 180.0 && num1 > num2)
          {
            ArcCenter = F_NotchEdit.ToPoint3D(point3D2);
            ArcSA = num2;
            ArcEA = num1;
            return;
          }
          if (Math.Abs(num3 - num4) > 180.0 && num3 > num4)
          {
            ArcCenter = F_NotchEdit.ToPoint3D(point3D3);
            ArcSA = num4;
            ArcEA = num3;
            return;
          }
          double num5 = num1 + 360.0;
          if (Math.Abs(num5 - num2) > 180.0 && num5 > num2)
          {
            ArcCenter = F_NotchEdit.ToPoint3D(point3D2);
            ArcSA = num2;
            ArcEA = num5;
            return;
          }
          double num6 = num3 + 360.0;
          if (Math.Abs(num6 - num4) > 180.0 && num6 > num4)
          {
            ArcCenter = F_NotchEdit.ToPoint3D(point3D3);
            ArcSA = num4;
            ArcEA = num6;
            return;
          }
        }
      }
      if (CW)
        return;
      double num7 = this.PointAngle(ArcStartPoint, point3D2, refPlane);
      double num8 = this.PointAngle(ArcEndPoint, point3D2, refPlane);
      double num9 = this.PointAngle(ArcStartPoint, point3D3, refPlane);
      double num10 = this.PointAngle(ArcEndPoint, point3D3, refPlane);
      if (buConversion5.EQ(num7, 360.0, 0.001))
        num7 = 0.0;
      if (buConversion5.EQ(num9, 360.0, 0.001))
        num9 = 0.0;
      if (!flag)
      {
        Math.Abs(num8 - num7);
        if (Math.Abs(num8 - num7) <= 180.0 && num8 > num7)
        {
          ArcCenter = F_NotchEdit.ToPoint3D(point3D2);
          ArcSA = num7;
          ArcEA = num8;
          return;
        }
        if (Math.Abs(num10 - num9) <= 180.0 && num10 > num9)
        {
          ArcCenter = F_NotchEdit.ToPoint3D(point3D3);
          ArcSA = num9;
          ArcEA = num10;
          return;
        }
        num8 += 360.0;
        if (Math.Abs(num8 - num7) <= 180.0 && num8 > num7)
        {
          ArcCenter = F_NotchEdit.ToPoint3D(point3D2);
          ArcSA = num7;
          ArcEA = num8;
          return;
        }
        num10 += 360.0;
        if (Math.Abs(num10 - num9) <= 180.0 && num10 > num9)
        {
          ArcCenter = F_NotchEdit.ToPoint3D(point3D3);
          ArcSA = num9;
          ArcEA = num10;
          return;
        }
      }
      if (!flag)
        return;
      if (Math.Abs(num8 - num7) > 180.0 && num8 > num7)
      {
        ArcCenter = F_NotchEdit.ToPoint3D(point3D2);
        ArcSA = num7;
        ArcEA = num8;
      }
      else if (Math.Abs(num10 - num9) > 180.0 && num10 > num9)
      {
        ArcCenter = F_NotchEdit.ToPoint3D(point3D3);
        ArcSA = num9;
        ArcEA = num10;
      }
      else
      {
        double num11 = num8 + 360.0;
        if (Math.Abs(num11 - num7) > 180.0 && num11 > num7)
        {
          ArcCenter = F_NotchEdit.ToPoint3D(point3D2);
          ArcSA = num7;
          ArcEA = num11;
        }
        else
        {
          double num12 = num10 + 360.0;
          if (Math.Abs(num12 - num9) <= 180.0 || num12 <= num9)
            return;
          ArcCenter = F_NotchEdit.ToPoint3D(point3D3);
          ArcSA = num9;
          ArcEA = num12;
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"ArcStartPoint: {ArcStartPoint.ToString()} - ArcEndPoint: {ArcEndPoint.ToString()} - Radius: {Radius.ToString()} - CW: {CW.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void ArcWithIJK(
    Point3D PreviousPoint,
    Point3D NextPoint,
    double I,
    double J,
    double K,
    int ArcDir,
    ref Point3D ArcCenter,
    ref double Radius,
    ref double StartAngle,
    ref double EndAngle)
  {
    ArcCenter = new Point3D();
    double num1 = 0.0;
    double num2 = 0.0;
    bool flag = false;
    ArcCenter.X = PreviousPoint.X + I;
    ArcCenter.Y = PreviousPoint.Y + J;
    ArcCenter.Z = PreviousPoint.Z + K;
    if (ArcDir == 2)
    {
      num1 = this.PointAngle(PreviousPoint, ArcCenter);
      num2 = this.PointAngle(NextPoint, ArcCenter);
      if (!flag)
      {
        if (num2 > 180.0 & buConversion5.EQ(num1, 0.0, 0.01))
          num1 = 360.0;
        if (num1 < 180.0 & buConversion5.EQ(num2, 0.0, 0.01))
          num2 = 0.0;
      }
      if (num2 > num1)
        num1 = 360.0 + num1;
    }
    if (ArcDir == 3)
    {
      num1 = this.PointAngle(PreviousPoint, ArcCenter);
      num2 = this.PointAngle(NextPoint, ArcCenter);
      if (!flag)
      {
        if (num1 > 180.0 & buConversion5.EQ(num2, 0.0, 0.01))
          num2 = 360.0;
        if (num2 < 180.0 & buConversion5.EQ(num1, 0.0, 0.01))
          num1 = 0.0;
      }
      if (num1 > num2)
        num2 = 360.0 + num2;
    }
    if (num1 > num2)
    {
      StartAngle = num2;
      EndAngle = num1;
    }
    else
    {
      StartAngle = num1;
      EndAngle = num2;
    }
    if (StartAngle > EndAngle)
      EndAngle = 360.0 + EndAngle;
    Radius = this.Length3D(PreviousPoint, ArcCenter);
  }

  public void BSplineQuadraticUniform(
    List<Point3D> controlPoints,
    double dt,
    bool Closed,
    ref List<Point3D> calculatedPoints)
  {
    try
    {
      List<Pnt3D> CopiedPnt = new List<Pnt3D>();
      List<Pnt3D> RefPnt = new List<Pnt3D>();
      List<Pnt3D> ControlPoints = new List<Pnt3D>();
      List<Pnt3D> CalculatedPoints = new List<Pnt3D>();
      List<Pnt3D> pnt3DList = new List<Pnt3D>();
      Pnt3D pnt3D1 = new Pnt3D();
      Pnt3D pnt3D2 = new Pnt3D();
      buString5.Point3DToPnt3D(controlPoints, ref CopiedPnt);
      double num1 = 1.0;
      double num2 = -2.0;
      double num3 = 1.0;
      double num4 = -2.0;
      double num5 = 2.0;
      double num6 = 0.0;
      double num7 = 1.0;
      double num8 = 1.0;
      double num9 = 0.0;
      if (dt <= 0.0)
        dt = 0.1;
      RefPnt.Clear();
      int int32 = Convert.ToInt32(1.0 / dt);
      if (Closed)
      {
        Pnt3D Pnt1 = new Pnt3D(CopiedPnt[0]);
        Pnt3D Pnt2 = new Pnt3D(CopiedPnt[CopiedPnt.Count - 1]);
        for (int index = 0; index <= CopiedPnt.Count - 1; ++index)
          pnt3DList.Add(new Pnt3D(CopiedPnt[index]));
        pnt3DList.Insert(0, new Pnt3D(Pnt2));
        pnt3DList.Add(new Pnt3D(Pnt1));
      }
      else
      {
        for (int index = 0; index <= CopiedPnt.Count - 1; ++index)
          pnt3DList.Add(new Pnt3D(CopiedPnt[index]));
        if (pnt3DList.Count <= 1)
          return;
        if (pnt3DList.Count == 2)
        {
          pnt3D1 = new Pnt3D();
          Pnt3D Pnt = buCall.\u0001.MiddlePointOfLine(pnt3DList[0], pnt3DList[1]);
          pnt3DList.Insert(1, new Pnt3D(Pnt));
        }
      }
      for (int index1 = 1; index1 <= pnt3DList.Count - 2; ++index1)
      {
        for (int index2 = 0; index2 <= int32; ++index2)
        {
          Pnt3D pnt3D3 = new Pnt3D();
          double x = (double) index2 * dt;
          double num10 = 0.5 * (num1 * Math.Pow(x, 2.0) + num4 * x + num7) * pnt3DList[index1 - 1].X + 0.5 * (num2 * Math.Pow(x, 2.0) + num5 * x + num8) * pnt3DList[index1].X + 0.5 * (num3 * Math.Pow(x, 2.0) + num6 * x + num9) * pnt3DList[index1 + 1].X;
          double num11 = 0.5 * (num1 * Math.Pow(x, 2.0) + num4 * x + num7) * pnt3DList[index1 - 1].Y + 0.5 * (num2 * Math.Pow(x, 2.0) + num5 * x + num8) * pnt3DList[index1].Y + 0.5 * (num3 * Math.Pow(x, 2.0) + num6 * x + num9) * pnt3DList[index1 + 1].Y;
          double num12 = 0.5 * (num1 * Math.Pow(x, 2.0) + num4 * x + num7) * pnt3DList[index1 - 1].Z + 0.5 * (num2 * Math.Pow(x, 2.0) + num5 * x + num8) * pnt3DList[index1].Z + 0.5 * (num3 * Math.Pow(x, 2.0) + num6 * x + num9) * pnt3DList[index1 + 1].Z;
          pnt3D3.X = num10;
          pnt3D3.Y = num11;
          pnt3D3.Z = num12;
          RefPnt.Add(pnt3D3);
        }
      }
      if (Closed)
      {
        buString5.Pnt3DToPoint3D(RefPnt, ref calculatedPoints);
      }
      else
      {
        if (RefPnt.Count <= 0)
          return;
        ControlPoints.Add(new Pnt3D(CopiedPnt[0]));
        ControlPoints.Add(new Pnt3D(RefPnt[0]));
        double x1 = CopiedPnt[1].X - CopiedPnt[0].X;
        double y1 = CopiedPnt[1].Y - CopiedPnt[0].Y;
        double z1 = CopiedPnt[1].Z - CopiedPnt[0].Z;
        double x2 = (RefPnt[1].X - RefPnt[0].X) * (1000.0 / (dt * 1000.0));
        double y2 = (RefPnt[1].Y - RefPnt[0].Y) * (1000.0 / (dt * 1000.0));
        double z2 = (RefPnt[1].Z - RefPnt[0].Z) * (1000.0 / (dt * 1000.0));
        buCall.\u0001.HermiteCubicSplineWithStartEndVector(ControlPoints, dt, 1.0, 0.0, new Vec3D(x1, y1, z1), new Vec3D(x2, y2, z2), ref CalculatedPoints);
        for (int index = CalculatedPoints.Count - 1; index >= 0; --index)
          RefPnt.Insert(0, new Pnt3D(CalculatedPoints[index]));
        ControlPoints.Clear();
        CalculatedPoints.Clear();
        ControlPoints.Add(new Pnt3D(RefPnt[RefPnt.Count - 1]));
        ControlPoints.Add(new Pnt3D(CopiedPnt[CopiedPnt.Count - 1]));
        double x3 = (RefPnt[RefPnt.Count - 1].X - RefPnt[RefPnt.Count - 2].X) * (1000.0 / (dt * 1000.0));
        double y3 = (RefPnt[RefPnt.Count - 1].Y - RefPnt[RefPnt.Count - 2].Y) * (1000.0 / (dt * 1000.0));
        double z3 = (RefPnt[RefPnt.Count - 1].Z - RefPnt[RefPnt.Count - 2].Z) * (1000.0 / (dt * 1000.0));
        double x4 = CopiedPnt[CopiedPnt.Count - 1].X - CopiedPnt[CopiedPnt.Count - 2].X;
        double y4 = CopiedPnt[CopiedPnt.Count - 1].Y - CopiedPnt[CopiedPnt.Count - 2].Y;
        double z4 = CopiedPnt[CopiedPnt.Count - 1].Z - CopiedPnt[CopiedPnt.Count - 2].Z;
        buCall.\u0001.HermiteCubicSplineWithStartEndVector(ControlPoints, dt, 1.0, 0.0, new Vec3D(x3, y3, z3), new Vec3D(x4, y4, z4), ref CalculatedPoints);
        for (int index = 0; index <= CalculatedPoints.Count - 1; ++index)
          RefPnt.Add(new Pnt3D(CalculatedPoints[index]));
