  public void BezeirCurve(
    List<Point3D> controlPoints,
    double dt,
    ref List<Point3D> calculatedPoints)
  {
    List<Pnt3D> CopiedPnt = new List<Pnt3D>();
    List<Pnt3D> RefPnt = new List<Pnt3D>();
    try
    {
      buString5.Point3DToPnt3D(controlPoints, ref CopiedPnt);
      Pnt3D pnt3D1 = new Pnt3D();
      if (CopiedPnt.Count <= 1)
        return;
      if (dt <= 0.0)
        dt = 0.1;
      dt /= (double) CopiedPnt.Count;
      RefPnt.Clear();
      int int32 = Convert.ToInt32(1.0 / dt);
      int n = CopiedPnt.Count - 1;
      for (int index1 = 0; index1 <= int32; ++index1)
      {
        Pnt3D pnt3D2 = new Pnt3D();
        double t = (double) index1 * dt;
        double num1 = 0.0;
        double num2 = 0.0;
        double num3 = 0.0;
        for (int index2 = 0; index2 <= CopiedPnt.Count - 1; ++index2)
        {
          buVector.BezeirBlend(n, index2, t);
          num1 += CopiedPnt[index2].X * buVector.BezeirBlend(n, index2, t);
          num2 += CopiedPnt[index2].Y * buVector.BezeirBlend(n, index2, t);
          num3 += CopiedPnt[index2].Z * buVector.BezeirBlend(n, index2, t);
