  public void BSplineAtSharpCorner(
    List<Point3D> refPoints,
    double dt,
    double SharpAngle,
    bool isQuadratic,
    ref List<Point3D> calculatedPoints)
  {
    if (calculatedPoints == null)
      calculatedPoints = new List<Point3D>();
    calculatedPoints.Clear();
    if (refPoints.Count <= 1)
      return;
    calculatedPoints.Add(F_NotchEdit.ToPoint3D(refPoints[0]));
    List<Point3D> controlPoints = new List<Point3D>();
    for (int index = 1; index < refPoints.Count - 1; ++index)
    {
      if (Math.Abs(180.0 - this.AngleOfTwoLines(refPoints[index - 1], refPoints[index], refPoints[index], refPoints[index + 1], Plane.XY)) > SharpAngle)
      {
        if (controlPoints.Count == 0)
        {
          controlPoints.Add(F_NotchEdit.ToPoint3D(refPoints[index - 1]));
          controlPoints.Add(F_NotchEdit.ToPoint3D(refPoints[index]));
          controlPoints.Add(F_NotchEdit.ToPoint3D(refPoints[index + 1]));
        }
        else
          controlPoints.Add(F_NotchEdit.ToPoint3D(refPoints[index + 1]));
      }
      else
      {
        if (controlPoints.Count > 0)
        {
          List<Point3D> calculatedPoints1 = new List<Point3D>();
          if (isQuadratic)
            this.BSplineQuadraticUniform(controlPoints, 0.1, false, ref calculatedPoints1);
          else
            this.BezeirCurve(controlPoints, 0.1, ref calculatedPoints1);
          calculatedPoints1.RemoveAt(0);
          calculatedPoints1.RemoveAt(calculatedPoints1.Count - 1);
          calculatedPoints.AddRange((IEnumerable<Point3D>) calculatedPoints1);
          controlPoints.Clear();
          controlPoints = new List<Point3D>();
        }
        calculatedPoints.Add(F_NotchEdit.ToPoint3D(refPoints[index]));
      }
    }
    calculatedPoints.Add(F_NotchEdit.ToPoint3D(refPoints[refPoints.Count - 1]));
    ((F_CutterMachineSettings) this).CheckDuplicatedPointsWithPrevious(ref calculatedPoints);
  }

  public void MiddleTextPoint(
    Point3D P0,
    Point3D P1,
    double Distance,
    ref Point3D refPoint,
    ClockDirectionType Clock = ClockDirectionType.CCW)
  {
    double num = this.PointAngle(P1, P0);
    Point3D CenterPnt = this.MiddlePointOfLine(P0, P1);
    if (Clock == ClockDirectionType.CCW)
      this.LineWithLengthAndAngle(CenterPnt, Distance, num - 90.0, ref refPoint);
    else
      this.LineWithLengthAndAngle(CenterPnt, Distance, num + 90.0, ref refPoint);
  }

  public void AlignedDimCalculate(
    Point3D pntStart,
    Point3D pntEnd,
    Point3D pntLine,
    double dimtextH,
    Plane currentPlane,
    ref Plane drawingPlane)
  {
    try
    {
      if ((pntEnd.X < pntStart.X ? 1 : (pntEnd.Y < pntStart.Y ? 1 : 0)) != 0)
      {
        Point3D first = pntStart;
        Point3D second = pntEnd;
        Utility.Swap<Point3D>(ref first, ref second);
        pntStart = first;
        pntEnd = second;
      }
      Vector3D vector3D = new Vector3D(pntStart, pntEnd);
      Vector3D Y = Vector3D.Cross(currentPlane.AxisZ, vector3D);
      drawingPlane = new Plane(pntStart, vector3D, Y);
      double num1 = (double) Math.Sign(Vector2D.SignedAngleBetween(new Vector2D((Point2D) pntStart, (Point2D) pntEnd), new Vector2D((Point2D) pntStart, (Point2D) pntLine)));
      Segment2D seg = new Segment2D((Point2D) pntStart, (Point2D) pntEnd);
      double num2 = pntLine.DistanceTo(seg);
      Point3D point3D1 = pntStart + num1 * drawingPlane.AxisY * (num2 + dimtextH / 2.0);
      Point3D point3D2 = pntEnd + num1 * drawingPlane.AxisY * (num2 + dimtextH / 2.0);
      Point3D point3D3 = pntStart + num1 * drawingPlane.AxisY * num2;
      Point3D point3D4 = pntEnd + num1 * drawingPlane.AxisY * num2;
    }
    catch (Exception ex)
    {
    }
  }

  public void LinearDimCalculate(
    Point3D pntStart,
    Point3D pntEnd,
    Point3D pntLine,
    double dimtextH,
    Plane currentPlane,
    ref Plane drawingPlane)
  {
    Vector3D vector3D;
    Point3D p1_1;
    Point3D p1_2;
    if ((pntLine.X <= pntStart.X || pntLine.X <= pntEnd.X ? (pntLine.X >= pntStart.X ? 0 : (pntLine.X < pntEnd.X ? 1 : 0)) : 1) != 0)
    {
      vector3D = currentPlane.AxisY;
      p1_1 = new Point3D(pntLine.X, pntStart.Y);
      p1_2 = new Point3D(pntLine.X, pntEnd.Y);
      if ((pntLine.X <= pntStart.X ? 0 : (pntLine.X > pntEnd.X ? 1 : 0)) != 0)
      {
        p1_1.X += dimtextH / 2.0;
        p1_2.X += dimtextH / 2.0;
      }
      else
      {
        p1_1.X -= dimtextH / 2.0;
        p1_2.X -= dimtextH / 2.0;
      }
    }
    else
    {
      vector3D = currentPlane.AxisX;
      p1_1 = new Point3D(pntStart.X, pntLine.Y);
      p1_2 = new Point3D(pntEnd.X, pntLine.Y);
      if ((pntLine.Y <= pntStart.Y ? 0 : (pntLine.Y > pntEnd.Y ? 1 : 0)) != 0)
      {
        p1_1.Y += dimtextH / 2.0;
        p1_2.Y += dimtextH / 2.0;
      }
      else
      {
        p1_1.Y -= dimtextH / 2.0;
        p1_2.Y -= dimtextH / 2.0;
      }
    }
    Vector3D Y = Vector3D.Cross(currentPlane.AxisZ, vector3D);
    Segment3D seg1 = new Segment3D(pntStart, p1_1);
    Segment3D seg2 = new Segment3D(pntEnd, p1_2);
    pntLine.ProjectTo(seg1);
    pntLine.ProjectTo(seg2);
    drawingPlane = new Plane(pntStart, vector3D, Y);
  }

  public BlockKeyedCollection CopyEyeBlockToEyeBlock(
    BlockKeyedCollection ExistingBlocks,
    BlockKeyedCollection BaseBlocks)
  {
    BlockKeyedCollection eyeBlock = new BlockKeyedCollection();
    for (int index1 = 0; index1 <= BaseBlocks.Count - 1; ++index1)
    {
      bool flag = true;
      for (int index2 = 0; index2 <= ExistingBlocks.Count - 1; ++index2)
      {
        if (BaseBlocks[index1].Name == ExistingBlocks[index2].Name)
          flag = false;
      }
      if (flag)
      {
        Block block1 = new Block(BaseBlocks[index1].Name);
        Block block2 = (Block) BaseBlocks[index1].Clone();
        eyeBlock.Add(block2);
      }
    }
    return eyeBlock;
  }

