  public static Entity CopyEntities(Entity refEnt, bool CheckDuplicated = false, double Resolution = 0.001)
  {
    Entity entity;
    if (refEnt != null)
    {
      Entity Entity;
      if (refEnt.GetType() == typeof (buUpperLineEnt))
      {
        Entity = (Entity) new MyFileSerializer(((Line) refEnt).StartPoint, ((Line) refEnt).EndPoint);
        if (refEnt.EntityData != null)
        {
          if (refEnt.EntityData is CustomData)
            Entity.EntityData = (object) new ClipperOffset((CustomData) refEnt.EntityData);
        }
        else
          Entity.EntityData = (object) new ClipperOffset();
      }
      else
      {
        Entity = (Entity) refEnt.Clone();
        if (CheckDuplicated && Entity is LinearPath)
          buText.FixVerticeDublicated(ref Entity, Resolution);
        if (refEnt.EntityData != null)
        {
          if (refEnt.EntityData is CustomData)
            Entity.EntityData = (object) new ClipperOffset((CustomData) refEnt.EntityData);
        }
        else
          Entity.EntityData = (object) new ClipperOffset();
        if (Entity.Vertices == null)
        {
          switch (refEnt)
          {
            case devDept.Eyeshot.Entities.Text _:
              Entity.Regen(new RegenParams(buSystem.RegenDeviation, (IWorkspace) DrawingFinisedEventArgs.baseModel));
              break;
            case BlockReference _:
              break;
            default:
              Entity.Regen(new RegenParams(buSystem.RegenDeviation, (IWorkspace) DrawingFinisedEventArgs.baseModel));
              break;
          }
        }
      }
      entity = Entity;
    }
    else
      entity = (Entity) null;
    return entity;
  }

