  public void GetEdgesOfBrep(
    devDept.Eyeshot.Entities.Brep refEntity,
    devDept.Eyeshot.Entities.Brep.Edge refEdge,
    int SelectedIndex,
    ref List<Entity> Curves,
    ref List<int> EdgeIndex)
  {
    EdgeIndex.Clear();
    ICurve curve1 = refEntity.Edges[SelectedIndex].Curve;
    Curves.Add((Entity) curve1);
    int num = refEdge.StartPointIndex;
    EdgeIndex.Add(SelectedIndex);
    for (int index1 = 0; index1 <= refEntity.Edges.Length - 1; ++index1)
    {
      for (int index2 = 0; index2 <= refEntity.Edges.Length - 1; ++index2)
      {
        if (index2 != SelectedIndex)
        {
          if (num == refEntity.Edges[index2].StartPointIndex)
          {
            ICurve curve2 = refEntity.Edges[index2].Curve;
            if (buConversion5.EQ(((Entity) curve1).BoxMin.Z, ((Entity) curve2).BoxMin.Z, buSystem.resolutionSorting))
            {
              bool flag = true;
              if (EdgeIndex.Count > 0)
              {
                for (int index3 = 0; index3 <= EdgeIndex.Count - 1; ++index3)
                {
                  if (index2 == EdgeIndex[index3])
                  {
                    flag = false;
                    index3 = EdgeIndex.Count;
                  }
                }
              }
              if (flag)
              {
                Curves.Add((Entity) curve2);
                num = refEntity.Edges[index2].EndPointIndex;
                EdgeIndex.Add(index2);
              }
            }
          }
          else if (num == refEntity.Edges[index2].EndPointIndex)
          {
            ICurve curve3 = refEntity.Edges[index2].Curve;
            if (buConversion5.EQ(((Entity) curve1).BoxMin.Z, ((Entity) curve3).BoxMin.Z, buSystem.resolutionSorting))
            {
              bool flag = true;
              if (EdgeIndex.Count > 0)
              {
                for (int index4 = 0; index4 <= EdgeIndex.Count - 1; ++index4)
                {
                  if (index2 == EdgeIndex[index4])
                  {
                    flag = false;
                    index4 = EdgeIndex.Count;
                  }
                }
              }
              if (flag)
              {
                Curves.Add((Entity) curve3);
                num = refEntity.Edges[index2].StartPointIndex;
                EdgeIndex.Add(index2);
              }
            }
          }
        }
      }
    }
  }

