  public void GetOsnapPoints(
    List<Entity> Entities,
    OsnapProps OsnapProperties,
    ref List<OsnapPoint> OsnapPoints)
  {
    OsnapPoints.Clear();
    for (int index1 = 0; index1 <= Entities.Count - 1; ++index1)
    {
      if (Entities[index1] != null)
      {
        if (Entities[index1] is devDept.Eyeshot.Entities.Point)
        {
          if (OsnapProperties.OsnapPoint)
          {
            Point3D vertex = Entities[index1].Vertices[0];
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(vertex, osnapType.Point));
          }
        }
        else if (Entities[index1] is Line)
        {
          Line entity = (Line) Entities[index1];
          if (OsnapProperties.OsnapPoint)
          {
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.StartPoint, osnapType.Point));
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.EndPoint, osnapType.Point));
          }
          if (OsnapProperties.OsnapMiddle)
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.MidPoint, osnapType.Middle));
          if (!OsnapProperties.OsnapIntersection)
            ;
        }
        else if (Entities[index1] is LinearPath)
        {
          LinearPath entity = (LinearPath) Entities[index1];
          if (OsnapProperties.OsnapPoint)
          {
            for (int index2 = 0; index2 <= entity.Vertices.Length - 1; ++index2)
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.Vertices[index2], osnapType.Point));
          }
          if (OsnapProperties.OsnapMiddle)
          {
            for (int index3 = 1; index3 <= entity.Vertices.Length - 1; ++index3)
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(Point3D.MidPoint(entity.Vertices[index3 - 1], entity.Vertices[index3]), osnapType.Middle));
          }
          if (!OsnapProperties.OsnapIntersection)
            ;
        }
        else if (Entities[index1] is CompositeCurve)
        {
          CompositeCurve entity = (CompositeCurve) Entities[index1];
          if (OsnapProperties.OsnapPoint)
          {
            foreach (ICurve curve in entity.CurveList)
            {
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(curve.EndPoint, osnapType.Point));
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.CurveList[0].StartPoint, osnapType.Point));
            }
          }
          if (OsnapProperties.OsnapMiddle)
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.PointAt(0.5), osnapType.Middle));
        }
        else if (Entities[index1] is Arc)
        {
          Arc entity = (Arc) Entities[index1];
          if (OsnapProperties.OsnapPoint)
          {
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.StartPoint, osnapType.Point));
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.EndPoint, osnapType.Point));
          }
          if (OsnapProperties.OsnapMiddle)
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.MidPoint, osnapType.Middle));
          if (OsnapProperties.OsnapCenter)
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.Center, osnapType.Center));
          if (!OsnapProperties.OsnapIntersection)
            ;
        }
        else if (Entities[index1] is Circle)
        {
          Circle entity = (Circle) Entities[index1];
          if (OsnapProperties.OsnapPoint)
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.EndPoint, osnapType.Point));
          if (OsnapProperties.OsnapMiddle)
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.PointAt(entity.Domain.Mid), osnapType.Middle));
          if (OsnapProperties.OsnapCenter)
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.Center, osnapType.Center));
          if (OsnapProperties.OsnapOutside)
          {
            if (buVector5.isPlaneXZorZX(entity.Plane))
            {
              Point3D point3D1 = new Point3D(entity.Center.X + entity.Radius, entity.Center.Z);
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(point3D1, osnapType.Outer));
              Point3D point3D2 = new Point3D(entity.Center.X, entity.Center.Z + entity.Radius);
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(point3D2, osnapType.Outer));
              Point3D point3D3 = new Point3D(entity.Center.X - entity.Radius, entity.Center.Z);
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(point3D3, osnapType.Outer));
              Point3D point3D4 = new Point3D(entity.Center.X, entity.Center.Z - entity.Radius);
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(point3D4, osnapType.Outer));
            }
            else if (buVector5.isPlaneYZorZY(entity.Plane))
            {
              Point3D point3D5 = new Point3D(entity.Center.Y + entity.Radius, entity.Center.Z);
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(point3D5, osnapType.Outer));
              Point3D point3D6 = new Point3D(entity.Center.Y, entity.Center.Z + entity.Radius);
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(point3D6, osnapType.Outer));
              Point3D point3D7 = new Point3D(entity.Center.Y - entity.Radius, entity.Center.Z);
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(point3D7, osnapType.Outer));
              Point3D point3D8 = new Point3D(entity.Center.Y, entity.Center.Z - entity.Radius);
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(point3D8, osnapType.Outer));
            }
            else
            {
              Point3D point3D9 = new Point3D(entity.Center.X + entity.Radius, entity.Center.Y);
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(point3D9, osnapType.Outer));
              Point3D point3D10 = new Point3D(entity.Center.X, entity.Center.Y + entity.Radius);
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(point3D10, osnapType.Outer));
              Point3D point3D11 = new Point3D(entity.Center.X - entity.Radius, entity.Center.Y);
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(point3D11, osnapType.Outer));
              Point3D point3D12 = new Point3D(entity.Center.X, entity.Center.Y - entity.Radius);
              OsnapPoints.Add((OsnapPoint) new ObjectSize3D(point3D12, osnapType.Outer));
            }
          }
          if (!OsnapProperties.OsnapIntersection)
            ;
        }
        else if (Entities[index1] is Curve)
        {
          Curve entity = (Curve) Entities[index1];
          if (OsnapProperties.OsnapPoint)
          {
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.StartPoint, osnapType.Point));
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.EndPoint, osnapType.Point));
          }
          if (OsnapProperties.OsnapMiddle)
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(entity.PointAt(0.5), osnapType.Middle));
        }
        else if (!(Entities[index1] is EllipticalArc) && !(Entities[index1] is Ellipse) && !(Entities[index1] is devDept.Eyeshot.Entities.Mesh) && Entities[index1] is devDept.Eyeshot.Entities.Brep && OsnapProperties.OsnapPoint)
        {
          devDept.Eyeshot.Entities.Brep entity = (devDept.Eyeshot.Entities.Brep) Entities[index1];
          for (int index4 = 0; index4 <= entity.Vertices.Length - 1; ++index4)
          {
            Point3D vertex = entity.Vertices[index4];
            OsnapPoints.Add((OsnapPoint) new ObjectSize3D(vertex, osnapType.Point));
          }
        }
      }
    }
  }

  public bool GetPointOnEntity(Point3D refPoint, object Entity, ref Point3D overPoint)
  {
    try
    {
      if (Entity.GetType() == typeof (Line))
      {
        double t = 0.0;
        ((Line) Entity).ClosestPointTo(refPoint, out t);
        overPoint = ((Line) Entity).PointAt(t);
        return true;
      }
      if (Entity.GetType() == typeof (LinearPath))
      {
        double t = 0.0;
        ((LinearPath) Entity).ClosestPointTo(refPoint, out t);
        overPoint = ((LinearPath) Entity).PointAt(t);
        return true;
      }
      if (Entity.GetType() == typeof (Circle))
      {
        double t = 0.0;
        ((Circle) Entity).ClosestPointTo(refPoint, out t);
        overPoint = ((Circle) Entity).PointAt(t);
        return true;
      }
      if (Entity.GetType() == typeof (Arc))
      {
        double t = 0.0;
        ((Circle) Entity).ClosestPointTo(refPoint, out t);
        overPoint = ((Circle) Entity).PointAt(t);
        return true;
      }
      if (Entity.GetType() == typeof (Ellipse))
      {
        double t = 0.0;
        ((Ellipse) Entity).ClosestPointTo(refPoint, out t);
        overPoint = ((Ellipse) Entity).PointAt(t);
        return true;
      }
      if (Entity.GetType() == typeof (EllipticalArc))
      {
        double t = 0.0;
        ((Ellipse) Entity).ClosestPointTo(refPoint, out t);
        overPoint = ((Ellipse) Entity).PointAt(t);
        return true;
      }
      if (Entity.GetType() == typeof (CompositeCurve))
      {
        double t = 0.0;
        ((CompositeCurve) Entity).ClosestPointTo(refPoint, out t);
        overPoint = ((CompositeCurve) Entity).PointAt(t);
        return true;
      }
      if (!(Entity.GetType() == typeof (Curve)))
        return false;
      double t1 = 0.0;
      ((Curve) Entity).ClosestPointTo(refPoint, out t1);
      overPoint = ((Curve) Entity).PointAt(t1);
      return true;
    }
    catch (Exception ex)
    {
      return false;
    }
  }

