  public void GetAvailableGroupIndex(EntityList Entities, ref int GroupIndex)
  {
    List<int> UsedGroupList = new List<int>();
    this.GetAvailableGroupIndex(Entities, new List<int>(), ref GroupIndex, ref UsedGroupList);
  }

  public void GetAvailableGroupIndex(
    EntityList Entities,
    List<int> AlreadyUsedGroupIndex,
    ref int GroupIndex)
  {
    List<int> UsedGroupList = new List<int>();
    this.GetAvailableGroupIndex(Entities, AlreadyUsedGroupIndex, ref GroupIndex, ref UsedGroupList);
  }

  public void GetAvailableGroupIndex(
    EntityList Entities,
    List<int> AlreadyUsedGroupIndex,
    ref int GroupIndex,
    ref List<int> UsedGroupList)
  {
    try
    {
      UsedGroupList = new List<int>();
      for (int index = 0; index <= AlreadyUsedGroupIndex.Count - 1; ++index)
        UsedGroupList.Add(AlreadyUsedGroupIndex[index]);
      for (int index1 = 0; index1 <= Entities.Count - 1; ++index1)
      {
        int groupIdIndex = this.GetGroupIdIndex(Entities[index1]);
        if (groupIdIndex > 0)
        {
          if (UsedGroupList.Count == 0)
          {
            UsedGroupList.Add(groupIdIndex);
          }
          else
          {
            bool flag = false;
            for (int index2 = 0; index2 <= UsedGroupList.Count - 1; ++index2)
            {
              if (groupIdIndex == UsedGroupList[index2])
                flag = true;
            }
            if (!flag)
              UsedGroupList.Add(groupIdIndex);
          }
        }
      }
      if (UsedGroupList.Count == 0)
        GroupIndex = 1;
      if (UsedGroupList.Count == 1)
        GroupIndex = UsedGroupList[0] + 1;
      if (UsedGroupList.Count <= 1)
        return;
      this.SortList(SortDirectionType.Lower, ref UsedGroupList);
      bool flag1 = false;
      for (int index = 1; index <= UsedGroupList.Count - 1; ++index)
      {
        if (UsedGroupList[index] - UsedGroupList[index - 1] >= 2)
        {
          GroupIndex = UsedGroupList[index - 1] + 1;
          flag1 = true;
        }
      }
      if (flag1)
        return;
      GroupIndex = UsedGroupList[UsedGroupList.Count - 1] + 1;
    }
    catch (Exception ex)
    {
      string str = "Entities: " + Entities.Count.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void GetBoxSizeOFViewport(
    Design Viewport,
    Plane refPlane,
    ref Pnt3D MinPoint,
    ref Pnt3D MaxPoint)
  {
    try
    {
      Point3D point3D1 = new Point3D();
      Point3D point3D2 = new Point3D();
      Point3D point3D3 = buString5.Screen2DTo3D(Viewport, refPlane, new System.Drawing.Point(0, Viewport.Height));
      Point3D point3D4 = buString5.Screen2DTo3D(Viewport, refPlane, new System.Drawing.Point(Viewport.Width, 0));
      MinPoint.X = point3D3.X;
      MinPoint.Y = point3D3.Y;
      MinPoint.Z = point3D3.Z;
      MaxPoint.X = point3D4.X;
      MaxPoint.Y = point3D4.Y;
      MaxPoint.Z = point3D4.Z;
      if (MinPoint.X > MaxPoint.X)
        buCompare5.ExchangeDatas(ref MinPoint.X, ref MaxPoint.X);
      if (MinPoint.Y > MaxPoint.Y)
        buCompare5.ExchangeDatas(ref MinPoint.Y, ref MaxPoint.Y);
      if (MinPoint.Z <= MaxPoint.Z)
        return;
      buCompare5.ExchangeDatas(ref MinPoint.Z, ref MaxPoint.Z);
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, "");
    }
  }

  public Plane GetPlane(Point3D first, Point3D next)
  {
    Vector3D vector3D = new Vector3D(first, next);
    vector3D.Normalize();
    Vector3D Y = Vector3D.Cross(Vector3D.AxisX, vector3D);
    Y.Normalize();
    return new Plane(first, vector3D, Y);
  }

  public void GetClosestPointsOfTwoEntity(
    Entity FirstEntity,
    Entity SecondEntity,
    ref Point3D FirstFoundPoints,
    ref Point3D SecondFoundPoints)
  {
    double num1 = double.MaxValue;
    FirstFoundPoints = new Point3D();
    SecondFoundPoints = new Point3D();
    if (!(FirstEntity.Vertices != null & SecondEntity.Vertices != null))
      return;
    for (int index1 = 0; index1 <= FirstEntity.Vertices.Length - 1; ++index1)
    {
      for (int index2 = 0; index2 <= SecondEntity.Vertices.Length - 1; ++index2)
      {
        double num2 = Point3D.Distance(FirstEntity.Vertices[index1], SecondEntity.Vertices[index2]);
        if (num2 < num1)
        {
          FirstFoundPoints = F_NotchEdit.ToPoint3D(FirstEntity.Vertices[index1]);
          SecondFoundPoints = F_NotchEdit.ToPoint3D(SecondEntity.Vertices[index2]);
          num1 = num2;
        }
      }
    }
  }

  public void GetLongestPointsOfTwoEntity(
    Entity FirstEntity,
    Entity SecondEntity,
    ref Point3D FirstFoundPoints,
    ref Point3D SecondFoundPoints)
  {
    double num1 = double.MinValue;
    FirstFoundPoints = new Point3D();
    SecondFoundPoints = new Point3D();
    if (!(FirstEntity.Vertices != null & SecondEntity.Vertices != null))
      return;
    for (int index1 = 0; index1 <= FirstEntity.Vertices.Length - 1; ++index1)
    {
      for (int index2 = 0; index2 <= SecondEntity.Vertices.Length - 1; ++index2)
      {
        double num2 = Point3D.Distance(FirstEntity.Vertices[index1], SecondEntity.Vertices[index2]);
        if (num2 > num1 & Math.Abs(num2 - num1) > 0.001)
        {
          FirstFoundPoints = F_NotchEdit.ToPoint3D(FirstEntity.Vertices[index1]);
          SecondFoundPoints = F_NotchEdit.ToPoint3D(SecondEntity.Vertices[index2]);
          num1 = num2;
        }
      }
    }
  }

  public void GetInformationBetweenTwoPoints(
    Point3D FirstPoint,
    Point3D SecondPoint,
    ref DistanceData Distance)
  {
    Distance.Length = Point3D.Distance(FirstPoint, SecondPoint);
    Distance.dX = SecondPoint.X - FirstPoint.X;
    Distance.dY = SecondPoint.Y - FirstPoint.Y;
    Distance.dZ = SecondPoint.Z - FirstPoint.Z;
  }

  public void GetPointsEntityFromCount(Entity refEntity, int Count, List<Point3D> Points)
  {
    List<Point3D> PrePoints = new List<Point3D>();
    this.GetPointsEntityFromCount(refEntity, Count, ref PrePoints, ref Points);
  }

  public void GetPointsEntityFromCount(
    Entity refEntity,
    int Count,
    ref List<Point3D> PrePoints,
    ref List<Point3D> Points)
  {
    if (refEntity is ICurve)
    {
      ICurve curve = refEntity as ICurve;
      if (Count > 0)
      {
        double num = curve.Length() / Convert.ToDouble(Count);
        for (int index = 1; index <= Count - 1; ++index)
        {
          Points.Add(curve.PointAt(num * (double) index));
          PrePoints.Add(curve.PointAt(num * (double) index - 0.05));
        }
      }
      else
        Points = new List<Point3D>();
    }
    else
      Points = new List<Point3D>();
  }

