      if (((ICurve) RefEntity).StartPoint == RefPoint && RefEntity.EntityData != null && RefEntity.EntityData.GetType() == typeof (CustomData))
        ((CutterRuntimeSettings) RefEntity.EntityData).set_sortDirection(entitySortDirection.Normal);
      if (!(((ICurve) RefEntity).EndPoint == RefPoint) || RefEntity.EntityData == null || !(RefEntity.EntityData.GetType() == typeof (CustomData)))
