      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void DrawCurveOrBlockRef(
    Entity tempEntity,
    BlockKeyedCollection Blocks,
    ref List<List<Point3D>> refPoints)
  {
    refPoints.Clear();
    switch (tempEntity)
    {
      case ICurve _:
        List<Point3D> refPoints1 = new List<Point3D>();
        this.Draw(tempEntity as ICurve, ref refPoints1);
        refPoints.Add(refPoints1);
        break;
      case LinearDim _:
        LinearDim linearDim = (LinearDim) tempEntity;
        refPoints.Add(new List<Point3D>()
        {
          F_NotchEdit.ToPoint3D(linearDim.Vertices[6]),
          F_NotchEdit.ToPoint3D(linearDim.Vertices[7]),
          F_NotchEdit.ToPoint3D(linearDim.Vertices[8]),
          F_NotchEdit.ToPoint3D(linearDim.Vertices[9]),
          F_NotchEdit.ToPoint3D(linearDim.Vertices[6])
        });
        refPoints.Add(new List<Point3D>()
        {
          F_NotchEdit.ToPoint3D(linearDim.Vertices[0]),
          F_NotchEdit.ToPoint3D(linearDim.Vertices[1])
        });
        refPoints.Add(new List<Point3D>()
        {
          F_NotchEdit.ToPoint3D(linearDim.Vertices[2]),
          F_NotchEdit.ToPoint3D(linearDim.Vertices[3])
        });
        refPoints.Add(new List<Point3D>()
        {
          F_NotchEdit.ToPoint3D(linearDim.Vertices[4]),
          F_NotchEdit.ToPoint3D(linearDim.Vertices[5])
        });
        break;
      case RadialDim _:
        RadialDim radialDim = (RadialDim) tempEntity;
        refPoints.Add(new List<Point3D>()
        {
          F_NotchEdit.ToPoint3D(radialDim.Vertices[6]),
          F_NotchEdit.ToPoint3D(radialDim.Vertices[7]),
          F_NotchEdit.ToPoint3D(radialDim.Vertices[8]),
          F_NotchEdit.ToPoint3D(radialDim.Vertices[9]),
          F_NotchEdit.ToPoint3D(radialDim.Vertices[6])
        });
        refPoints.Add(new List<Point3D>()
        {
          F_NotchEdit.ToPoint3D(radialDim.Vertices[0]),
          F_NotchEdit.ToPoint3D(radialDim.Vertices[5])
        });
        break;
      case AngularDim _:
        AngularDim angularDim = (AngularDim) tempEntity;
        refPoints.Add(new List<Point3D>()
        {
          F_NotchEdit.ToPoint3D(angularDim.Vertices[4]),
          F_NotchEdit.ToPoint3D(angularDim.Vertices[5]),
          F_NotchEdit.ToPoint3D(angularDim.Vertices[6]),
          F_NotchEdit.ToPoint3D(angularDim.Vertices[7]),
          F_NotchEdit.ToPoint3D(angularDim.Vertices[4])
        });
        refPoints.Add(new List<Point3D>()
        {
          F_NotchEdit.ToPoint3D(angularDim.Vertices[0]),
          F_NotchEdit.ToPoint3D(angularDim.Vertices[1])
        });
        refPoints.Add(new List<Point3D>()
        {
          F_NotchEdit.ToPoint3D(angularDim.Vertices[2]),
          F_NotchEdit.ToPoint3D(angularDim.Vertices[3])
        });
        List<Point3D> point3DList = new List<Point3D>();
        for (int index = 0; index <= angularDim.UnderlyingArc.Vertices.Length - 1; ++index)
          point3DList.Add(F_NotchEdit.ToPoint3D(angularDim.UnderlyingArc.Vertices[index]));
        refPoints.Add(point3DList);
        break;
      case OrdinateDim _:
        OrdinateDim ordinateDim = (OrdinateDim) tempEntity;
        refPoints.Add(new List<Point3D>()
        {
          F_NotchEdit.ToPoint3D(ordinateDim.Vertices[4]),
          F_NotchEdit.ToPoint3D(ordinateDim.Vertices[5]),
          F_NotchEdit.ToPoint3D(ordinateDim.Vertices[6]),
          F_NotchEdit.ToPoint3D(ordinateDim.Vertices[7]),
          F_NotchEdit.ToPoint3D(ordinateDim.Vertices[4])
        });
        refPoints.Add(new List<Point3D>()
        {
          F_NotchEdit.ToPoint3D(ordinateDim.Vertices[0]),
          F_NotchEdit.ToPoint3D(ordinateDim.Vertices[1]),
          F_NotchEdit.ToPoint3D(ordinateDim.Vertices[2]),
          F_NotchEdit.ToPoint3D(ordinateDim.Vertices[3])
        });
        break;
      default:
        if (tempEntity.GetType() == typeof (devDept.Eyeshot.Entities.Text))
        {
          devDept.Eyeshot.Entities.Text text = (devDept.Eyeshot.Entities.Text) tempEntity;
          refPoints.Add(new List<Point3D>()
          {
            F_NotchEdit.ToPoint3D(text.Vertices[0]),
            F_NotchEdit.ToPoint3D(text.Vertices[1]),
            F_NotchEdit.ToPoint3D(text.Vertices[2]),
            F_NotchEdit.ToPoint3D(text.Vertices[3]),
            F_NotchEdit.ToPoint3D(text.Vertices[0])
          });
          break;
        }
        switch (tempEntity)
        {
          case Picture _:
            Picture picture = (Picture) tempEntity;
            refPoints.Add(new List<Point3D>()
            {
              F_NotchEdit.ToPoint3D(picture.Vertices[0]),
              F_NotchEdit.ToPoint3D(picture.Vertices[1]),
              F_NotchEdit.ToPoint3D(picture.Vertices[2]),
              F_NotchEdit.ToPoint3D(picture.Vertices[3]),
              F_NotchEdit.ToPoint3D(picture.Vertices[0])
            });
            return;
          case BlockReference _:
            if (Blocks == null)
              return;
            foreach (Entity tempEntity1 in ((BlockReference) tempEntity).Explode(Blocks))
            {
              List<List<Point3D>> refPoints2 = new List<List<Point3D>>();
              this.DrawCurveOrBlockRef(tempEntity1, Blocks, ref refPoints2);
              for (int index = 0; index <= refPoints2.Count - 1; ++index)
                refPoints.Add(refPoints2[index]);
            }
            return;
          case Leader _:
            Leader leader = (Leader) tempEntity;
            refPoints.Add(new List<Point3D>()
            {
              F_NotchEdit.ToPoint3D(leader.Vertices[0]),
              F_NotchEdit.ToPoint3D(leader.Vertices[1]),
              F_NotchEdit.ToPoint3D(leader.Vertices[2])
            });
            return;
          case devDept.Eyeshot.Entities.Mesh _:
            devDept.Eyeshot.Entities.Mesh mesh = (devDept.Eyeshot.Entities.Mesh) tempEntity;
            if (mesh.BoxMin == (Point3D) null)
              mesh.Regen(0.01);
            this.CreateBoxOrRectangleFromBoxSize(mesh.BoxMin, mesh.BoxMax, ref refPoints);
            return;
          case devDept.Eyeshot.Entities.Brep _:
            devDept.Eyeshot.Entities.Brep brep = (devDept.Eyeshot.Entities.Brep) tempEntity;
            if (brep.BoxMin == (Point3D) null)
              brep.Regen(0.01);
            this.CreateBoxOrRectangleFromBoxSize(brep.BoxMin, brep.BoxMax, ref refPoints);
            return;
          case devDept.Eyeshot.Entities.Surface _:
            devDept.Eyeshot.Entities.Surface surface = (devDept.Eyeshot.Entities.Surface) tempEntity;
            if (surface.BoxMin == (Point3D) null)
              surface.Regen(0.01);
            this.CreateBoxOrRectangleFromBoxSize(surface.BoxMin, surface.BoxMax, ref refPoints);
            return;
          default:
            return;
        }
    }
  }

  public void Draw(ICurve theCurve, ref List<Point3D> refPoints)
  {
    if (theCurve is CompositeCurve)
    {
      foreach (Entity entity in (theCurve as CompositeCurve).Explode())
      {
        List<Point3D> refPoints1 = new List<Point3D>();
        this.DrawToVertices((ICurve) entity, ref refPoints1);
        if (refPoints.Count > 0 & refPoints1.Count > 0 && refPoints[refPoints.Count - 1] == refPoints1[0])
          refPoints1.RemoveAt(0);
        refPoints.AddRange((IEnumerable<Point3D>) refPoints1);
      }
    }
    else
      this.DrawToVertices(theCurve, ref refPoints);
  }

  public void DrawToVertices(ICurve curve, ref List<Point3D> refPoints)
  {
    refPoints.Clear();
    switch (curve)
    {
      case Line _:
        for (int index = 0; index <= ((Entity) curve).Vertices.Length - 1; ++index)
          refPoints.Add(F_NotchEdit.ToPoint3D(((Entity) curve).Vertices[index]));
        break;
      case LinearPath _:
        for (int index = 0; index <= ((Entity) curve).Vertices.Length - 1; ++index)
          refPoints.Add(F_NotchEdit.ToPoint3D(((Entity) curve).Vertices[index]));
        break;
      case devDept.Eyeshot.Entities.Point _:
        refPoints.Add(F_NotchEdit.ToPoint3D(((Entity) curve).Vertices[0]));
        break;
      default:
        for (int index = 0; index <= 100; ++index)
          refPoints.Add(curve.PointAt(curve.Domain.ParameterAt((double) index / 100.0)));
        break;
    }
  }

  public void DrawEntitiesToImage(
    int Width,
    int Height,
    List<Entity> EntityList,
    Color BackgroundColor,
    ref Image image)
  {
    Design design = new Design();
    design.InitializeViewports();
    design.CreateControl();
    design.Width = Width;
    design.Height = Height;
    design.Viewports[0].Grid.Visible = false;
    design.Viewports[0].OriginSymbol.Visible = false;
    design.Viewports[0].CoordinateSystemIcon.Visible = false;
    BackgroundSettings backgroundSettings = new BackgroundSettings(backgroundStyleType.LinearGradient, BackgroundColor, BackgroundColor, BackgroundColor, 0.75, (Image) null, colorThemeType.Auto, 0.3);
    design.Viewports[0].Background = backgroundSettings;
    for (int index = 0; index <= EntityList.Count - 1; ++index)
      design.Entities.Add(EntityList[index]);
    design.SetView(viewType.Top);
    design.ZoomFit();
    design.Invalidate();
    design.CopyToClipboardRaster(new Size(Width, Height), true);
    Image image1 = Clipboard.GetImage();
    image = image1;
  }

  public void DrawLineAsRectangle(
    Point3D FirstPoint,
    Point3D SecondPoints,
    double Width,
    Plane refPlane,
    ref List<Point3D> calcPoints)
  {
    try
    {
      calcPoints.Clear();
      Point3D EndPnt1 = new Point3D();
      Point3D EndPnt2 = new Point3D();
      Point3D EndPnt3 = new Point3D();
      Point3D EndPnt4 = new Point3D();
      double num = this.PointAngle(SecondPoints, FirstPoint, refPlane);
      this.LineWithLengthAndAngle(FirstPoint, Width / 2.0, num + 90.0, ref EndPnt1);
      this.LineWithLengthAndAngle(FirstPoint, Width / 2.0, num - 90.0, ref EndPnt2);
      this.LineWithLengthAndAngle(SecondPoints, Width / 2.0, num - 90.0, ref EndPnt3);
      this.LineWithLengthAndAngle(SecondPoints, Width / 2.0, num + 90.0, ref EndPnt4);
      calcPoints.Add(EndPnt1);
      calcPoints.Add(EndPnt2);
      calcPoints.Add(EndPnt3);
      calcPoints.Add(EndPnt4);
      calcPoints.Add(EndPnt1);
    }
    catch (Exception ex)
    {
      string str = nameof (DrawLineAsRectangle);
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void CreateEntitiesGroupFromEntities(
    List<buEntity> OutsideEntities,
    List<List<buEntity>> InsideEntities,
    List<List<buEntity>> OpenEntities,
    ref buEntitiesGroup EntGroup)
  {
    try
    {
      EntGroup = (buEntitiesGroup) null;
      EntGroup = new buEntitiesGroup();
      if ((OutsideEntities == null ? 0 : (OutsideEntities.Count > 0 ? 1 : 0)) != 0)
      {
        buRadialDim.Copy(OutsideEntities, ref ((\u0084.\u0001) EntGroup.Outside).Entities);
        ((\u0084.\u0001) EntGroup.Outside).Points = new List<Point3D>();
        this.EntitiesToPointsWithCamDirection(((\u0084.\u0001) EntGroup.Outside).Entities, ref ((\u0084.\u0001) EntGroup.Outside).Points);
        if (((\u0084.\u0001) EntGroup.Outside).Points.Count > 0)
          ((IntersectNode) EntGroup.Outside).pntMassCenter = this.CalculateCentroid(((\u0084.\u0001) EntGroup.Outside).Points);
      }
      if ((InsideEntities == null ? 0 : (InsideEntities.Count > 0 ? 1 : 0)) != 0)
      {
        for (int index = 0; index <= InsideEntities.Count - 1; ++index)
        {
          if (InsideEntities[index].Count > 0)
          {
            buEntityList buEntityList = (buEntityList) new buArcCam();
            buRadialDim.Copy(InsideEntities[index], ref ((\u0084.\u0001) buEntityList).Entities);
            ((\u0084.\u0001) buEntityList).Points = new List<Point3D>();
            this.EntitiesToPointsWithCamDirection(((\u0084.\u0001) buEntityList).Entities, ref ((\u0084.\u0001) buEntityList).Points);
            if (((\u0084.\u0001) buEntityList).Points.Count > 0)
              ((IntersectNode) buEntityList).pntMassCenter = this.CalculateCentroid(((\u0084.\u0001) buEntityList).Points);
            if (((\u0084.\u0001) buEntityList).Entities.Count > 0)
            {
              if (EntGroup.Inside == null)
                EntGroup.Inside = new List<buEntityList>();
              EntGroup.Inside.Add(buEntityList);
            }
          }
        }
      }
      if ((OpenEntities == null ? 0 : (OpenEntities.Count > 0 ? 1 : 0)) == 0)
        return;
      for (int index = 0; index <= OpenEntities.Count - 1; ++index)
      {
        if (OpenEntities[index].Count > 0)
        {
          buEntityList buEntityList = (buEntityList) new buArcCam();
          buRadialDim.Copy(OpenEntities[index], ref ((\u0084.\u0001) buEntityList).Entities);
          ((\u0084.\u0001) buEntityList).Points = new List<Point3D>();
          this.EntitiesToPointsWithCamDirection(((\u0084.\u0001) buEntityList).Entities, ref ((\u0084.\u0001) buEntityList).Points);
          if (((\u0084.\u0001) buEntityList).Points.Count > 0)
            ((IntersectNode) buEntityList).pntMassCenter = this.CalculateCentroid(((\u0084.\u0001) buEntityList).Points);
          if (((\u0084.\u0001) buEntityList).Entities.Count > 0)
          {
            if (EntGroup.OpenEntities == null)
              EntGroup.OpenEntities = new List<buEntityList>();
            EntGroup.OpenEntities.Add(buEntityList);
          }
        }
      }
    }
    catch (Exception ex)
    {
    }
  }

  public void CurvePoints(
    List<Point3D> refPoints,
    double LimitMinAngle,
    double LimitMaxAngle,
    ref List<Point3D> filletedPoints)
  {
    List<Point3D> ctrlPoints = new List<Point3D>();
    filletedPoints.Add(F_NotchEdit.ToPoint3D(refPoints[0]));
    ctrlPoints.Add(F_NotchEdit.ToPoint3D(refPoints[0]));
    for (int index = 1; index <= refPoints.Count - 1; ++index)
    {
      if (index <= refPoints.Count - 2)
      {
        Line line1 = new Line(refPoints[index - 1], refPoints[index]);
        Line line2 = new Line(refPoints[index], refPoints[index + 1]);
        double num = this.AngleOfTwoLines(line1.StartPoint, line1.EndPoint, line2.StartPoint, line2.EndPoint, Plane.XY);
        if (num < LimitMaxAngle & num > LimitMinAngle)
          ctrlPoints.Add(F_NotchEdit.ToPoint3D(refPoints[index]));
        else
          filletedPoints.Add(F_NotchEdit.ToPoint3D(refPoints[index]));
      }
      else
        ctrlPoints.Add(F_NotchEdit.ToPoint3D(refPoints[index]));
    }
    if (ctrlPoints.Count <= 0)
      return;
    Curve curve = new Curve(2, (IList<Point3D>) ctrlPoints);
    curve.Regen(0.1);
    filletedPoints.Clear();
    filletedPoints.AddRange((IEnumerable<Point3D>) curve.Vertices);
  }

  public void FilletPoints(
    List<Point3D> refPoints,
    double FilletRadius,
    double LimitMinAngle,
    double LimitMaxAngle,
    ref List<Point3D> filletedPoints)
  {
    filletedPoints.Add(F_NotchEdit.ToPoint3D(refPoints[0]));
    for (int index1 = 1; index1 <= refPoints.Count - 2; ++index1)
    {
      Line C1 = new Line(refPoints[index1 - 1], refPoints[index1]);
      Line C2 = new Line(refPoints[index1], refPoints[index1 + 1]);
      Arc fillet = (Arc) null;
      C1.Length();
      C2.Length();
      double num = this.AngleOfTwoLines(C1.StartPoint, C1.EndPoint, C2.StartPoint, C2.EndPoint, Plane.XY);
      bool flag = Curve.Fillet((ICurve) C1, (ICurve) C2, FilletRadius, false, false, true, true, out fillet);
      if (fillet != null & flag & num < LimitMaxAngle & num > LimitMinAngle)
      {
        fillet.Regen(0.001);
        if (fillet.Vertices.Length <= 4)
          fillet.Regen(0.0001);
        if (fillet.Vertices.Length > 2)
        {
          for (int index2 = 0; index2 <= fillet.Vertices.Length - 1; ++index2)
            filletedPoints.Add(F_NotchEdit.ToPoint3D(fillet.Vertices[index2]));
        }
        else
          filletedPoints.Add(F_NotchEdit.ToPoint3D(refPoints[index1]));
      }
      else
        filletedPoints.Add(F_NotchEdit.ToPoint3D(refPoints[index1]));
    }
    filletedPoints.Add(F_NotchEdit.ToPoint3D(refPoints[refPoints.Count - 1]));
  }

  public void getPointAtEntitiesBetweenStartPointAndLength(
    Point3D pntStart,
    double Length,
    double Resolution,
    List<Entity> baseEntities,
    ref Point3D calcPoint)
  {
    Point3D point3D1 = F_NotchEdit.ToPoint3D(pntStart);
    double num1 = 0.0;
    bool flag = false;
    for (int index = 0; index <= baseEntities.Count - 1; ++index)
    {
      ICurve baseEntity = (ICurve) baseEntities[index];
      double t;
      baseEntity.ClosestPointTo(point3D1, out t);
      if (((F_AnalyseSettings) this).isPointInsideEntity(baseEntity, point3D1, Resolution) & t >= baseEntity.Domain.t0 & t <= baseEntity.Domain.t1)
      {
        flag = true;
        double num2 = (baseEntity.Domain.t1 - baseEntity.Domain.t0) / baseEntity.Length();
        double num3 = Length - num1;
        Point3D point3D2 = new Point3D();
        ICurve sub = (ICurve) null;
        if (((CutterIsoFileItems) baseEntities[index].EntityData).get_sortDirection() == entitySortDirection.Normal)
        {
          double num4 = t + num3 * num2;
          if (num4 > baseEntity.Domain.t1)
            num4 = baseEntity.Domain.t1;
          if (num4 - t > Resolution)
          {
            Point3D point3D3 = new Point3D();
            baseEntity.SubCurve(t, num4, out sub);
            double num5 = sub.Length();
            point3D1 = F_NotchEdit.ToPoint3D(F_NotchEdit.ToPoint3D(baseEntity.PointAt(num4)));
            double num6 = (num4 - t) / num2;
            if (!(buConversion5.EQ(num6 + num1, Length, Resolution) | num6 + num1 > Length))
            {
              num1 += num5;
            }
            else
            {
              calcPoint = F_NotchEdit.ToPoint3D(point3D1);
              break;
            }
          }
        }
        else
        {
          double num7 = t - num3 * num2;
          if (num7 < baseEntity.Domain.t0)
            num7 = baseEntity.Domain.t0;
          if (t - num7 > 0.001)
          {
            Point3D point3D4 = new Point3D();
            baseEntity.SubCurve(num7, t, out sub);
            double num8 = sub.Length();
            point3D1 = F_NotchEdit.ToPoint3D(F_NotchEdit.ToPoint3D(baseEntity.PointAt(num7)));
            double num9 = (t - num7) / num2;
            if (!(buConversion5.EQ(num9 + num1, Length, Resolution) | num9 + num1 > Length))
            {
              num1 += num8;
            }
            else
            {
              calcPoint = F_NotchEdit.ToPoint3D(point3D1);
              break;
            }
          }
        }
      }
      else if (flag)
        num1 += baseEntity.Length();
    }
  }

  public void CreateBoxOrRectangleFromBoxSize(
    Point3D pntMin,
    Point3D pntMax,
    ref List<List<Point3D>> refPoints)
  {
    double width = pntMax.X - pntMin.X;
    double num = pntMax.Y - pntMin.Y;
    double height = pntMax.Z - pntMin.Z;
    if (!buConversion5.EQ(width, 0.0) & !buConversion5.EQ(num, 0.0) & !buConversion5.EQ(height, 0.0))
    {
      devDept.Eyeshot.Entities.Mesh box = devDept.Eyeshot.Entities.Mesh.CreateBox(width, num, height);
      box.Translate(pntMin.X, pntMin.Y, pntMin.Z);
      List<Point3D> PointList = new List<Point3D>();
      F_CutterOffsetEntities.VerticeToPointsList(box.Vertices, ref PointList);
      refPoints.Add(PointList);
    }
    else if (!buConversion5.EQ(width, 0.0) & !buConversion5.EQ(num, 0.0) & buConversion5.EQ(height, 0.0))
    {
      CompositeCurve rectangle = CompositeCurve.CreateRectangle(Plane.XY, width, num);
      rectangle.Regen(0.01);
      rectangle.Translate(pntMin.X, pntMin.Y, pntMin.Z);
      List<Point3D> PointList = new List<Point3D>();
      F_CutterOffsetEntities.VerticeToPointsList(rectangle.Vertices, ref PointList);
      refPoints.Add(PointList);
    }
    else if (!buConversion5.EQ(width, 0.0) & buConversion5.EQ(num, 0.0) & !buConversion5.EQ(height, 0.0))
    {
      CompositeCurve rectangle = CompositeCurve.CreateRectangle(Plane.XZ, width, height);
      rectangle.Regen(0.01);
      rectangle.Translate(pntMin.X, pntMin.Y, pntMin.Z);
      List<Point3D> PointList = new List<Point3D>();
      F_CutterOffsetEntities.VerticeToPointsList(rectangle.Vertices, ref PointList);
      refPoints.Add(PointList);
    }
    else
    {
      if (!(buConversion5.EQ(width, 0.0) & !buConversion5.EQ(num, 0.0) & !buConversion5.EQ(height, 0.0)))
        return;
      CompositeCurve rectangle = CompositeCurve.CreateRectangle(Plane.YZ, width, height);
      rectangle.Regen(0.01);
      rectangle.Translate(pntMin.X, pntMin.Y, pntMin.Z);
      List<Point3D> PointList = new List<Point3D>();
      F_CutterOffsetEntities.VerticeToPointsList(rectangle.Vertices, ref PointList);
      refPoints.Add(PointList);
    }
  }

  public void LineWithLengthAndAngle(
    Point3D CenterPnt,
    double Length,
    double Angle,
    Plane refPlane,
    ref Point3D StartPnt,
    ref Point3D EndPnt)
  {
    this.LineWithLengthAndAngle(CenterPnt, Length, Angle, refPlane, ref EndPnt);
