  }

  public static void LineWithLengthAndAngleByPlane(
    Point3D CenterPnt,
    double Length,
    double Angle,
    Plane refPlane,
    ref Point3D EndPnt)
  {
    try
    {
      EndPnt = new Point3D();
      double s;
      double t;
      refPlane.Project(CenterPnt, out s, out t);
      double x = s + Length * Math.Cos(buString5.DegreeToRadian(Angle));
      double y = t + Length * Math.Sin(buString5.DegreeToRadian(Angle));
      List<Point3D> points = new List<Point3D>();
      points.Add(new Point3D(s, t));
      points.Add(new Point3D(x, y));
      DrawingFinisedEventArgs.baseModel.MoveToPlane((IList<Point3D>) points, refPlane);
      EndPnt.X = points[1].X;
      EndPnt.Y = points[1].Y;
      EndPnt.Z = points[1].Z;
      if (buVector5.isPlaneXYorYX(refPlane))
        EndPnt.Z = CenterPnt.Z;
      if (buVector5.isPlaneXZorZX(refPlane))
        EndPnt.Y = CenterPnt.Y;
      if (!buVector5.isPlaneYZorZY(refPlane))
        return;
      EndPnt.X = CenterPnt.X;
    }
    catch (Exception ex)
    {
      string str = $"Center: {CenterPnt.ToString()} - Len: {Length.ToString()} - Angle: {Angle.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

