  public void LengthFromZLengthAndAngle(double ZLength, double Angle, ref double XLength)
  {
    try
    {
      if (Angle % 90.0 == 0.0)
        XLength = 0.0;
      else
        XLength = ZLength * Math.Tan(buString5.DegreeToRadian(Angle));
    }
    catch (Exception ex)
    {
      string str = $"ZLength: {ZLength.ToString()} - Angle: {Angle.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void LineWithOrientationAngle(
    Point3D BasePoint,
    OrientationAngle Angles,
    double Length,
    ref Point3D calcPoint)
  {
    try
    {
      calcPoint.X = BasePoint.X + Length * Math.Sin(buString5.DegreeToRadian(Angles.A)) * Math.Cos(buString5.DegreeToRadian(Angles.C + 90.0));
      calcPoint.Y = BasePoint.Y + Length * Math.Sin(buString5.DegreeToRadian(Angles.A)) * Math.Sin(buString5.DegreeToRadian(Angles.C + 90.0));
      calcPoint.Z = BasePoint.Z + Length * Math.Cos(buString5.DegreeToRadian(Angles.A));
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - Angles: {Angles.ToString()} - Length: {Length.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void DiagonalLengthByAnglePerpendicularDistance(
    Point3D BasePoint,
    double Angle,
    double PerpendicularDistance,
    Plane Plane,
    ref Point3D CalcPoint)
  {
    try
    {
      if (!(Math.Abs(Angle) >= -90.0 & Math.Abs(Angle) <= 180.0))
        return;
      double num1 = PerpendicularDistance / Math.Cos(buString5.DegreeToRadian(Angle));
      if (buVector5.isPlaneXYorYX(Plane))
      {
        Point3D point3D = F_NotchEdit.ToPoint3D(BasePoint);
        point3D.Y += PerpendicularDistance;
        double num2 = this.PointAngle(point3D, BasePoint, Plane);
        CalcPoint = F_NotchEdit.ToPoint3D(BasePoint);
        this.LineWithLengthAndAngle(BasePoint, Math.Abs(num1), num2 + Angle, Plane, ref CalcPoint);
      }
      if (buVector5.isPlaneXZorZX(Plane))
      {
        Point3D point3D = F_NotchEdit.ToPoint3D(BasePoint);
        point3D.Z += PerpendicularDistance;
        double num3 = this.PointAngle(point3D, BasePoint, Plane);
        CalcPoint = F_NotchEdit.ToPoint3D(BasePoint);
        this.LineWithLengthAndAngle(BasePoint, Math.Abs(num1), num3 + Angle, Plane, ref CalcPoint);
      }
      if (!buVector5.isPlaneYZorZY(Plane))
        return;
      Point3D point3D1 = F_NotchEdit.ToPoint3D(BasePoint);
      point3D1.Z += PerpendicularDistance;
      double num4 = this.PointAngle(point3D1, BasePoint, Plane);
      CalcPoint = F_NotchEdit.ToPoint3D(BasePoint);
      this.LineWithLengthAndAngle(BasePoint, Math.Abs(num1), num4 + Angle, Plane, ref CalcPoint);
    }
    catch (Exception ex)
    {
      string str = $"BasePoint: {BasePoint.ToString()} - Angle: {Angle.ToString()} - PerpendicularDistance: {PerpendicularDistance.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void RectangleWithDxDy(
    Point3D pntBase,
