    refPlane.Project(pntBase, out s, out t);
    point3D.X = s + dX;
    point3D.Y = t + dY;
    List<Point3D> points = new List<Point3D>();
    points.Add(point3D);
    DrawingFinisedEventArgs.baseModel.MoveToPlane((IList<Point3D>) points, refPlane);
    pntCalc = points[0];
  }

  public bool LineLineIntersection(
    Point3D FirstLineStart,
    Point3D FirstLineEnd,
    Point3D SecondLineStart,
    Point3D SecondLineEnd,
    Plane Plane,
    ref Point3D pntIntersect)
  {
    Point3D EndPnt1 = new Point3D();
    Point3D EndPnt2 = new Point3D();
    Point3D EndPnt3 = new Point3D();
    Point3D EndPnt4 = new Point3D();
    bool flag;
    if (buConversion5.EQ(FirstLineStart, SecondLineStart))
    {
      pntIntersect = F_NotchEdit.ToPoint3D(FirstLineStart);
      flag = true;
    }
    else if (buConversion5.EQ(FirstLineStart, SecondLineEnd))
    {
      pntIntersect = F_NotchEdit.ToPoint3D(FirstLineStart);
      flag = true;
    }
    else if (buConversion5.EQ(FirstLineEnd, SecondLineStart))
    {
      pntIntersect = F_NotchEdit.ToPoint3D(FirstLineEnd);
      flag = true;
    }
    else if (buConversion5.EQ(FirstLineEnd, SecondLineEnd))
    {
      pntIntersect = F_NotchEdit.ToPoint3D(FirstLineEnd);
      flag = true;
    }
    else
    {
      double Angle1 = this.PointAngle(FirstLineStart, FirstLineEnd, Plane);
      double Angle2 = this.PointAngle(SecondLineStart, SecondLineEnd, Plane);
      this.LineWithLengthAndAngle(FirstLineEnd, 1000000.0, Angle1, ref EndPnt1);
      this.LineWithLengthAndAngle(FirstLineStart, 1000000.0, Angle1 + 180.0, ref EndPnt2);
      this.LineWithLengthAndAngle(SecondLineEnd, 1000000.0, Angle2, ref EndPnt3);
