          ((buClipper) buShapeCut).CalculatedPoint.Y = ((buClipper) buShapeCut).CornerPoint.Y + ((buClipper) buShapeCut).CornerDirection.Y * ((DiemakerGrindingShapeSettings) buShapeCut).StartDistance;
        }
        if (num > 0.0)
          ((DiemakerGrindingShapeSettings) buShapeCut).Length = num;
      }
      if (((DiemakerGrindingShapeSettings) buShapeCut).CutType == CutTypes.CutVertical | ((DiemakerGrindingShapeSettings) buShapeCut).CutType == CutTypes.CutVerticalLine && ((DiemakerGrindingShapeSettings) buShapeCut).CutType == CutTypes.CutVerticalLine && ((DiemakerGrindingShapeSettings) buShapeCut).Length > 0.0)
      {
        double num = ((SortbuFilter) Pars).Size.Depth - ((DiemakerGrindingShapeSettings) buShapeCut).StartDistance - ((DiemakerGrindingShapeSettings) buShapeCut).EndDistance;
        if (((buClipperBase) buShapeCut).planeName == planeBoxNames.Top | ((buClipperBase) buShapeCut).planeName == planeBoxNames.Bottom)
        {
          ((buClipper) buShapeCut).CalculatedPoint.Y = ((buClipper) buShapeCut).CornerPoint.Y + ((buClipper) buShapeCut).CornerDirection.Y * ((DiemakerGrindingShapeSettings) buShapeCut).StartDistance;
          num = ((SortbuFilter) Pars).Size.Height - ((DiemakerGrindingShapeSettings) buShapeCut).StartDistance - ((DiemakerGrindingShapeSettings) buShapeCut).EndDistance;
