  public void calcBuShapeHole3Point(
    Point3D pntCenter,
    planeBoxNames PlaneName,
    double DistanceX,
    double DistanceY,
    double Diameter,
    double Angle,
    ref Point3D calcCenter1,
    ref Point3D calcCenter2)
  {
    if (PlaneName == planeBoxNames.Top | PlaneName == planeBoxNames.Bottom)
    {
      Circle circle1 = new Circle(Plane.XY, pntCenter, Diameter / 2.0);
      Circle circle2 = new Circle(Plane.XY, pntCenter, Diameter / 2.0);
      circle1.Translate(DistanceX / 2.0, DistanceY);
      circle2.Translate(-DistanceX / 2.0, DistanceY);
      if (Angle != 0.0)
      {
        circle1.Rotate(buString5.DegreeToRadian(Angle), Vector3D.AxisZ, pntCenter);
        circle2.Rotate(buString5.DegreeToRadian(Angle), Vector3D.AxisZ, pntCenter);
      }
      circle1.Regen(0.01);
      circle2.Regen(0.01);
      calcCenter1 = F_NotchEdit.ToPoint3D(circle1.Center);
      calcCenter2 = F_NotchEdit.ToPoint3D(circle2.Center);
    }
    if (PlaneName == planeBoxNames.Front | PlaneName == planeBoxNames.Back)
    {
      Circle circle3 = new Circle(Plane.XZ, pntCenter, Diameter / 2.0);
      Circle circle4 = new Circle(Plane.XZ, pntCenter, Diameter / 2.0);
      circle3.Translate(DistanceX / 2.0, 0.0, DistanceY);
      circle4.Translate(-DistanceX / 2.0, 0.0, DistanceY);
      if (Angle != 0.0)
      {
        circle3.Rotate(buString5.DegreeToRadian(Angle), Vector3D.AxisY, pntCenter);
        circle4.Rotate(buString5.DegreeToRadian(Angle), Vector3D.AxisY, pntCenter);
      }
      circle3.Regen(0.01);
      circle4.Regen(0.01);
      calcCenter1 = F_NotchEdit.ToPoint3D(circle3.Center);
      calcCenter2 = F_NotchEdit.ToPoint3D(circle4.Center);
    }
    if (!(PlaneName == planeBoxNames.Right | PlaneName == planeBoxNames.Left))
      return;
    Circle circle5 = new Circle(Plane.YZ, pntCenter, Diameter / 2.0);
    Circle circle6 = new Circle(Plane.YZ, pntCenter, Diameter / 2.0);
    circle5.Translate(0.0, DistanceX / 2.0, DistanceY);
    circle6.Translate(0.0, -DistanceX / 2.0, DistanceY);
