  public void calcBuShapeProfilingArcStartEndAngles(
    buShapeProfiling S,
    ref double SA,
    ref double EA)
  {
    if (((buClipperBase) S).Corner == CornerLocation.LeftBottom)
    {
      SA = 180.0;
      EA = 270.0;
    }
    if (((buClipperBase) S).Corner == CornerLocation.LeftTop)
    {
      SA = 90.0;
      EA = 180.0;
    }
    if (((buClipperBase) S).Corner == CornerLocation.RightTop)
    {
      SA = 0.0;
      EA = 90.0;
    }
    if (((buClipperBase) S).Corner != CornerLocation.RightBottom)
      return;
    SA = 270.0;
    EA = 360.0;
  }

  public void calcBuShapeProfilingRoundConcaveArcStartEndAngles(
    buShapeProfiling S,
    ref double SA,
    ref double EA)
  {
    if (((buClipperBase) S).Corner == CornerLocation.LeftBottom)
    {
      SA = 0.0;
      EA = 90.0;
    }
    if (((buClipperBase) S).Corner == CornerLocation.LeftTop)
    {
      SA = 270.0;
      EA = 360.0;
    }
    if (((buClipperBase) S).Corner == CornerLocation.RightTop)
    {
      SA = 180.0;
      EA = 270.0;
    }
    if (((buClipperBase) S).Corner != CornerLocation.RightBottom)
      return;
    SA = 90.0;
    EA = 180.0;
  }

