    double TriangleLength,
    Plane Plane,
    bool Reverse,
    bool FromBaseLine,
    ref Point3D FirstPoint,
    ref Point3D SecondPoint,
    ref Point3D ThirdPoint)
  {
    try
    {
      Point3D EndPnt1 = new Point3D();
