  public void ArcWithCenter(
    Point3D Center,
    double Radius,
    double StartAngle,
    double EndAngle,
    Plane refPlane,
    EntityResolution EntResolution,
    ref List<Point3D> Vertices)
  {
    try
    {
      Point3D point3D1 = new Point3D();
      Vertices.Clear();
      int num = this.ArcVerticeCountByResolution(Radius, StartAngle, EndAngle, EntResolution);
      for (int index = 0; index <= num; ++index)
      {
        Point3D point3D2 = new Point3D();
        if (buVector5.isPlaneXYorYX(refPlane))
        {
          point3D2.X = Center.X + Radius * Math.Cos(buString5.DegreeToRadianGreat360(StartAngle + (double) index * (EndAngle - StartAngle) / (double) num));
          point3D2.Y = Center.Y + Radius * Math.Sin(buString5.DegreeToRadianGreat360(StartAngle + (double) index * (EndAngle - StartAngle) / (double) num));
          point3D2.Z = Center.Z;
          Vertices.Add(point3D2);
        }
        if (buVector5.isPlaneXZorZX(refPlane))
        {
          point3D2.X = Center.X + Radius * Math.Cos(buString5.DegreeToRadianGreat360(StartAngle + (double) index * (EndAngle - StartAngle) / (double) num));
          point3D2.Y = Center.Y;
          point3D2.Z = Center.Z + Radius * Math.Sin(buString5.DegreeToRadianGreat360(StartAngle + (double) index * (EndAngle - StartAngle) / (double) num));
          Vertices.Add(point3D2);
        }
        if (buVector5.isPlaneYZorZY(refPlane))
        {
          point3D2.X = Center.X;
          point3D2.Y = Center.Y + Radius * Math.Cos(buString5.DegreeToRadianGreat360(StartAngle + (double) index * (EndAngle - StartAngle) / (double) num));
          point3D2.Z = Center.Z + Radius * Math.Sin(buString5.DegreeToRadianGreat360(StartAngle + (double) index * (EndAngle - StartAngle) / (double) num));
          Vertices.Add(point3D2);
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - Rad: {Radius.ToString()} - SA: {StartAngle.ToString()} - EA: {EndAngle.ToString()} - Plane: {refPlane.ToString()} - EntResolution: {EntResolution.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public double ArcCircumference(double Radius, double StartAngle, double EndAngle)
  {
    try
    {
      return Radius * Math.PI * 2.0 * (EndAngle - StartAngle) / 360.0;
    }
    catch (Exception ex)
    {
      string str = $"R: {Radius.ToString()} - SA: {StartAngle.ToString()} - EA: {EndAngle.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

