        Points.Add(F_NotchEdit.ToPoint3D(((CustomDataSurrogate) RefArc).Vertices[((CustomDataSurrogate) RefArc).Vertices.Count - 1]));
      }
      if (((CustomData) RefArc).sortDirection != entitySortDirection.Reverse)
        return;
      int int32_1 = Convert.ToInt32(((CustomDataSurrogate) RefArc).Vertices.Count / 2);
      Points.Add(F_NotchEdit.ToPoint3D(((CustomDataSurrogate) RefArc).Vertices[((CustomDataSurrogate) RefArc).Vertices.Count - 1]));
      Points.Add(F_NotchEdit.ToPoint3D(((CustomDataSurrogate) RefArc).Vertices[int32_1]));
      Points.Add(F_NotchEdit.ToPoint3D(((CustomDataSurrogate) RefArc).Vertices[0]));
    }
    catch (Exception ex)
    {
