  public void ArcToTwoArc(buArc refArc, ref buEntity Arc1, ref buEntity Arc2)
  {
    Entity copiedEntity = (Entity) null;
    buAngularDim.Copy((buEntity) refArc, ref copiedEntity);
    if (((CustomDataSurrogate) refArc).EndAngle - ((CustomDataSurrogate) refArc).StartAngle <= 1.0)
      return;
    ICurve lower = (ICurve) null;
    ICurve upper = (ICurve) null;
    ((Circle) copiedEntity).SplitAt(((Circle) copiedEntity).Domain.Mid, out lower, out upper);
    buAngularDim.Copy((Entity) lower, ref Arc1);
    buAngularDim.Copy((Entity) upper, ref Arc2);
  }

  public void ArcToTwoArc(Arc refArc, ref Entity Arc1, ref Entity Arc2)
  {
    if (refArc.AngleInDegrees <= 0.1)
      return;
    ICurve lower = (ICurve) null;
    ICurve upper = (ICurve) null;
    refArc.SplitAt(refArc.Domain.Mid, out lower, out upper);
    buRadialDim.Copy((Entity) lower, ref Arc1);
    buRadialDim.Copy((Entity) upper, ref Arc2);
    this.CopyEntityProperties((Entity) refArc, ref Arc1);
    this.CopyEntityProperties((Entity) refArc, ref Arc1);
  }

  public void CircleQuadrantPoints(
    Point3D Center,
    double Radius,
    Plane refPlane,
    ref Point3D Q1,
    ref Point3D Q2,
    ref Point3D Q3,
    ref Point3D Q4)
  {
    if (buVector5.isPlaneXYorYX(refPlane))
    {
      Q1 = new Point3D(Center.X + Radius, Center.Y, Center.Z);
      Q2 = new Point3D(Center.X, Center.Y + Radius, Center.Z);
      Q3 = new Point3D(Center.X - Radius, Center.Y, Center.Z);
      Q4 = new Point3D(Center.X, Center.Y - Radius, Center.Z);
    }
    if (buVector5.isPlaneXZorZX(refPlane))
    {
      Q1 = new Point3D(Center.X + Radius, Center.Y, Center.Z);
      Q2 = new Point3D(Center.X, Center.Y, Center.Z + Radius);
      Q3 = new Point3D(Center.X - Radius, Center.Y, Center.Z);
      Q4 = new Point3D(Center.X, Center.Y, Center.Z - Radius);
    }
    if (!buVector5.isPlaneYZorZY(refPlane))
      return;
    Q1 = new Point3D(Center.X, Center.Y + Radius, Center.Z);
    Q2 = new Point3D(Center.X, Center.Y, Center.Z + Radius);
    Q3 = new Point3D(Center.X, Center.Y - Radius, Center.Z);
    Q4 = new Point3D(Center.X, Center.Y, Center.Z - Radius);
  }

