  public void ArcEllipseToLineer(
    Point3D Center,
    double Major,
    double Minor,
    double StartAngle,
    double EndAngle,
    double Angle,
    double Length,
    Plane refPlane,
    ref List<Point3D> Vertices)
  {
    try
    {
      double num1 = 0.0;
      Point3D point3D1 = new Point3D();
      Vertices.Clear();
      if (Length <= 0.0)
        return;
      double num2 = EndAngle - StartAngle;
      int int32 = Convert.ToInt32(2.0 * Math.PI * Math.Sqrt(0.5 * (Math.Pow(Major, 2.0) + Math.Pow(Minor, 2.0))) / Length);
      if (int32 <= 0)
        return;
      if (int32 > 0)
        num1 = num2 / (double) int32;
      double num3 = (360.0 - Angle) * Math.PI / 180.0;
      double num4 = Math.Sin(num3);
      double num5 = Math.Cos(num3);
      for (int index = 0; index <= int32; ++index)
      {
        Point3D point3D2 = new Point3D();
        double Degree = StartAngle + (double) index * num1;
        double num6 = Major * Math.Cos(buString5.DegreeToRadianGreat360(Degree));
        double num7 = Minor * Math.Sin(buString5.DegreeToRadianGreat360(Degree));
        if (buVector5.isPlaneXYorYX(refPlane))
        {
          point3D2.X = Center.X + num6 * num5 + num7 * num4;
          point3D2.Y = Center.Y - num6 * num4 + num7 * num5;
          point3D2.Z = Center.Z;
        }
        if (buVector5.isPlaneXZorZX(refPlane))
        {
          point3D2.X = Center.X + num6 * num5 + num7 * num4;
          point3D2.Y = Center.Y;
          point3D2.Z = Center.Z - num6 * num4 + num7 * num5;
        }
        if (buVector5.isPlaneYZorZY(refPlane))
        {
          point3D2.X = Center.X;
          point3D2.Y = Center.Y + num6 * num5 + num7 * num4;
          point3D2.Z = Center.Z - num6 * num4 + num7 * num5;
        }
        Vertices.Add(point3D2);
      }
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - MajRad: {Major.ToString()} - MinRad: {Minor.ToString()} - SA: {StartAngle.ToString()} - EA: {EndAngle.ToString()} - Ang: {Angle.ToString()} - Len: {Length.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void EllipseToLineer(
    Point3D Center,
    double Major,
    double Minor,
    double Angle,
    double Length,
    Plane refPlane,
    ref List<Point3D> Vertices)
  {
    try
    {
      double num1 = 0.0;
      double num2 = 360.0;
      double num3 = 0.0;
      Point3D point3D1 = new Point3D();
      Vertices.Clear();
      if (Length <= 0.0)
        return;
      double num4 = num2 - num1;
      int int32 = Convert.ToInt32(2.0 * Math.PI * Math.Sqrt(0.5 * (Math.Pow(Major, 2.0) + Math.Pow(Minor, 2.0))) / Length);
      if (int32 <= 0)
        return;
      if (int32 > 0)
        num3 = num4 / (double) int32;
      double num5 = (360.0 - Angle) * Math.PI / 180.0;
      double num6 = Math.Sin(num5);
      double num7 = Math.Cos(num5);
      for (int index = 0; index <= int32; ++index)
      {
        Point3D point3D2 = new Point3D();
        double Degree = num1 + (double) index * num3;
        double num8 = Major * Math.Cos(buString5.DegreeToRadianGreat360(Degree));
        double num9 = Minor * Math.Sin(buString5.DegreeToRadianGreat360(Degree));
        if (buVector5.isPlaneXYorYX(refPlane))
        {
          point3D2.X = Center.X + num8 * num7 + num9 * num6;
          point3D2.Y = Center.Y - num8 * num6 + num9 * num7;
          point3D2.Z = Center.Z;
        }
        if (buVector5.isPlaneXZorZX(refPlane))
        {
          point3D2.X = Center.X + num8 * num7 + num9 * num6;
          point3D2.Y = Center.Y;
          point3D2.Z = Center.Z - num8 * num6 + num9 * num7;
        }
        if (buVector5.isPlaneYZorZY(refPlane))
        {
          point3D2.X = Center.X;
          point3D2.Y = Center.Y + num8 * num7 + num9 * num6;
          point3D2.Z = Center.Z - num8 * num6 + num9 * num7;
        }
        Vertices.Add(point3D2);
      }
    }
    catch (Exception ex)
    {
      string str = $"Center: {Center.ToString()} - MajRad: {Major.ToString()} - MinRad: {Minor.ToString()} - Ang: {Angle.ToString()} - Len: {Length.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void Trapezoid3D(
    Point3D TopLeftPoint,
    double TrapezTopWidth,
    double TrapezHeight,
    double TrapezTopLeftAngle,
    double TrapezTopRightAngle,
    Vec3D LengthDirection,
    double DirectionLength,
    double Rotation,
    ref Entity SurfaceEntity)
  {
    buEntity TopFirstLine = (buEntity) null;
    buEntity BottomFirstLine = (buEntity) null;
    buEntity TopLastLine = (buEntity) null;
    buEntity BottomLastLine = (buEntity) null;
    this.Trapezoid3D(TopLeftPoint, TrapezTopWidth, TrapezHeight, TrapezTopLeftAngle, TrapezTopRightAngle, LengthDirection, DirectionLength, Rotation, ref TopFirstLine, ref BottomFirstLine, ref TopLastLine, ref BottomLastLine, ref SurfaceEntity);
  }

  public void Trapezoid3D(
    Point3D TopLeftPoint,
    double TrapezTopWidth,
    double TrapezHeight,
    double TrapezTopLeftAngle,
    double TrapezTopRightAngle,
    Vec3D LengthDirection,
    double DirectionLength,
    double Rotation,
    ref buEntity TopFirstLine,
    ref buEntity BottomFirstLine,
    ref buEntity TopLastLine,
    ref buEntity BottomLastLine,
    ref Entity SurfaceEntity)
  {
    Point3D point3D1 = new Point3D();
    Point3D point3D2 = new Point3D();
    Point3D CalcPoint1 = new Point3D();
    Point3D CalcPoint2 = new Point3D();
    AlingmentPoints3D AlignPoints = (AlingmentPoints3D) new MaterialBase5();
    List<Point3D> point3DList1 = new List<Point3D>();
    List<Point3D> Points = new List<Point3D>();
    List<Point3D> point3DList2 = new List<Point3D>();
    List<Point3D> point3DList3 = new List<Point3D>();
    Quad3D quad3D = new Quad3D();
    Triangle3D triangle3D1 = new Triangle3D();
    Triangle3D triangle3D2 = new Triangle3D();
    Plane pln = Plane.XY;
    if (Vec3D.isVectorZAxis(LengthDirection))
    {
      pln = Plane.XY;
      Point3D BasePoint1 = new Point3D(0.0, TrapezHeight, 0.0);
      Point3D BasePoint2 = new Point3D(TrapezTopWidth, TrapezHeight, 0.0);
      this.DiagonalLengthByAnglePerpendicularDistance(BasePoint1, 90.0 - TrapezTopLeftAngle, -TrapezHeight, Plane.XY, ref CalcPoint1);
      this.DiagonalLengthByAnglePerpendicularDistance(BasePoint2, TrapezTopRightAngle - 90.0, -TrapezHeight, Plane.XY, ref CalcPoint2);
      Points.Add(BasePoint1);
      Points.Add(BasePoint2);
      Points.Add(CalcPoint2);
      Points.Add(CalcPoint1);
      Points.Add(BasePoint1);
      this.BoxSizeWithContentAlignment(Points, new WorkPlane(LengthDirection), ref AlignPoints);
      this.Move(((EyeCreateProps) AlignPoints).pntTopLeft, TopLeftPoint, ref Points);
      if (this.GetClockDirection(Points, Plane.YZ) == ClockDirectionType.CW)
        Points.Reverse();
    }
    Plane plane;
    if (Vec3D.isVectorYAxis(LengthDirection))
    {
      double Angle = Rotation - 90.0;
      plane = Plane.XZ;
      Point3D BasePoint3 = new Point3D(0.0, 0.0, TrapezHeight);
      Point3D BasePoint4 = new Point3D(TrapezTopWidth, 0.0, TrapezHeight);
      this.DiagonalLengthByAnglePerpendicularDistance(BasePoint3, 90.0 - TrapezTopLeftAngle, -TrapezHeight, Plane.XZ, ref CalcPoint1);
      this.DiagonalLengthByAnglePerpendicularDistance(BasePoint4, TrapezTopRightAngle - 90.0, -TrapezHeight, Plane.XZ, ref CalcPoint2);
      Points.Add(BasePoint3);
      Points.Add(BasePoint4);
      Points.Add(CalcPoint2);
      Points.Add(CalcPoint1);
      Points.Add(BasePoint3);
      this.BoxSizeWithContentAlignment(Points, new WorkPlane(LengthDirection), ref AlignPoints);
      this.Move(((EyeCreateProps) AlignPoints).pntTopLeft, TopLeftPoint, ref Points);
      buVector5.Copy(Points, ref point3DList2);
      this.Rotate(TopLeftPoint, Angle, Plane.XY, ref Points);
      pln = new Plane(Points[0], Points[1], Points[2]);
      buVector5.OffsetPoint3D(ref point3DList2, 0.0, DirectionLength, 0.0);
      this.Rotate(TopLeftPoint, Angle, Plane.XY, ref point3DList2);
      TopFirstLine = (buEntity) new buMultilineText(Points[0], point3DList2[0]);
      BottomFirstLine = (buEntity) new buMultilineText(Points[3], point3DList2[3]);
      BottomLastLine = (buEntity) new buMultilineText(Points[2], point3DList2[2]);
      TopLastLine = (buEntity) new buMultilineText(Points[1], point3DList2[1]);
    }
    if (Vec3D.isVectorXAxis(LengthDirection))
    {
      double Angle = -Rotation;
      plane = Plane.YZ;
      Point3D BasePoint5 = new Point3D(0.0, 0.0, TrapezHeight);
      Point3D BasePoint6 = new Point3D(0.0, TrapezTopWidth, TrapezHeight);
      this.DiagonalLengthByAnglePerpendicularDistance(BasePoint5, 90.0 - TrapezTopLeftAngle, -TrapezHeight, Plane.YZ, ref CalcPoint1);
      this.DiagonalLengthByAnglePerpendicularDistance(BasePoint6, TrapezTopRightAngle - 90.0, -TrapezHeight, Plane.YZ, ref CalcPoint2);
      Points.Add(BasePoint5);
      Points.Add(CalcPoint1);
      Points.Add(CalcPoint2);
      Points.Add(BasePoint6);
      Points.Add(BasePoint5);
      this.BoxSizeWithContentAlignment(Points, new WorkPlane(LengthDirection), ref AlignPoints);
      this.Move(((EyeCreateProps) AlignPoints).pntTopLeft, TopLeftPoint, ref Points);
      buVector5.Copy(Points, ref point3DList2);
      this.Rotate(TopLeftPoint, Angle, Plane.XY, ref Points);
      pln = new Plane(Points[0], Points[1], Points[2]);
      buVector5.OffsetPoint3D(ref point3DList2, DirectionLength, 0.0, 0.0);
      this.Rotate(TopLeftPoint, Angle, Plane.XY, ref point3DList2);
      TopFirstLine = (buEntity) new buMultilineText(Points[0], point3DList2[0]);
      BottomFirstLine = (buEntity) new buMultilineText(Points[1], point3DList2[1]);
      BottomLastLine = (buEntity) new buMultilineText(Points[2], point3DList2[2]);
      TopLastLine = (buEntity) new buMultilineText(Points[3], point3DList2[3]);
    }
    devDept.Eyeshot.Entities.Brep brep = new devDept.Eyeshot.Entities.Region((ICurve) new LinearPath((ICollection<Point3D>) Points), pln).ExtrudeAsBrep(DirectionLength, 0.0, 0.0);
    SurfaceEntity = (Entity) brep;
  }

  public void TrapezoidPerpendicular(
    Point3D BottomLeftPoint,
    double BottomWidth,
    double TopWidth,
    double TrapezHeight,
    double Rotation,
    double Thickness,
    bool CreateAsCompositeCurve,
    ref List<Point3D> Vertice2D,
    ref ICurve WireEntitiy,
    ref Entity SurfaceEntity)
  {
    try
    {
      Vertice2D.Clear();
      Vertice2D = new List<Point3D>();
      Vertice2D.Add(new Point3D(BottomLeftPoint.X, BottomLeftPoint.Y, 0.0));
      Vertice2D.Add(new Point3D(BottomLeftPoint.X + BottomWidth, BottomLeftPoint.Y, 0.0));
      Vertice2D.Add(new Point3D(BottomLeftPoint.X + TopWidth, BottomLeftPoint.Y + TrapezHeight, 0.0));
      Vertice2D.Add(new Point3D(BottomLeftPoint.X, BottomLeftPoint.Y + TrapezHeight, 0.0));
      Vertice2D.Add(new Point3D(BottomLeftPoint.X, BottomLeftPoint.Y, 0.0));
      this.Rotate(BottomLeftPoint, Rotation, Plane.XY, ref Vertice2D);
      Plane xy = Plane.XY;
      Plane pln = new Plane(Vertice2D[0], Vertice2D[1], Vertice2D[2]);
      if (!CreateAsCompositeCurve)
      {
        WireEntitiy = (ICurve) new LinearPath((ICollection<Point3D>) Vertice2D);
      }
      else
      {
        List<ICurve> curveList = new List<ICurve>();
        for (int index = 1; index <= Vertice2D.Count - 1; ++index)
          curveList.Add((ICurve) new Line(Vertice2D[index - 1], Vertice2D[index]));
        WireEntitiy = (ICurve) new CompositeCurve((IEnumerable<ICurve>) curveList);
      }
      devDept.Eyeshot.Entities.Brep brep = new devDept.Eyeshot.Entities.Region(WireEntitiy, pln).ExtrudeAsBrep(Thickness, 0.0, 0.0);
      SurfaceEntity = (Entity) brep;
    }
    catch (Exception ex)
    {
    }
  }

  public void RectangleChamfer(
    Point3D CornerPnt1,
    double Width,
    double Height,
    double Chamfer,
    Plane Plane,
    ref List<Point3D> Points)
  {
    Point3D CornerPnt2 = new Point3D();
    if (buVector5.isPlaneXYorYX(Plane))
      CornerPnt2 = new Point3D(CornerPnt1.X + Width, CornerPnt1.Y + Height, CornerPnt1.Z);
    if (buVector5.isPlaneXZorZX(Plane))
      CornerPnt2 = new Point3D(CornerPnt1.X + Width, CornerPnt1.Y, CornerPnt1.Z + Height);
    if (buVector5.isPlaneYZ(Plane))
      CornerPnt2 = new Point3D(CornerPnt1.X, CornerPnt1.Y + Width, CornerPnt1.Z + Height);
    this.RectangleChamfer(CornerPnt1, CornerPnt2, Chamfer, Plane, ref Points);
  }

  public void RectangleChamfer(
    Point3D CornerPnt1,
    Point3D CornerPnt2,
    double Chamfer,
    Plane Plane,
    ref List<Point3D> Points)
  {
    try
    {
      Points.Clear();
      if (buVector5.isPlaneXYorYX(Plane))
      {
        double num1 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
        double num2 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
        double num3;
        double num4;
        if (CornerPnt2.X > CornerPnt1.X)
        {
          if (CornerPnt2.Y > CornerPnt1.Y)
          {
            num3 = num1 * 1.0;
            num4 = num2 * 1.0;
          }
          else
          {
            num3 = num1 * 1.0;
            num4 = num2 * -1.0;
          }
        }
        else if (CornerPnt2.Y > CornerPnt1.Y)
        {
          num3 = num1 * -1.0;
          num4 = num2 * 1.0;
        }
        else
        {
          num3 = num1 * -1.0;
          num4 = num2 * -1.0;
        }
        Points.Add(new Point3D(CornerPnt1.X + num3, CornerPnt1.Y, CornerPnt1.Z));
        Points.Add(new Point3D(CornerPnt2.X - num3, CornerPnt1.Y, CornerPnt1.Z));
        Points.Add(new Point3D(CornerPnt2.X, CornerPnt1.Y + num4, CornerPnt1.Z));
        Points.Add(new Point3D(CornerPnt2.X, CornerPnt2.Y - num4, CornerPnt1.Z));
        Points.Add(new Point3D(CornerPnt2.X - num3, CornerPnt2.Y, CornerPnt1.Z));
        Points.Add(new Point3D(CornerPnt1.X + num3, CornerPnt2.Y, CornerPnt1.Z));
        Points.Add(new Point3D(CornerPnt1.X, CornerPnt2.Y - num4, CornerPnt1.Z));
        Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y + num4, CornerPnt1.Z));
        Points.Add(new Point3D(CornerPnt1.X + num3, CornerPnt1.Y, CornerPnt1.Z));
      }
      if (buVector5.isPlaneXZorZX(Plane))
      {
        double num5 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
        double num6 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
        double num7;
        double num8;
        if (CornerPnt2.X > CornerPnt1.X)
        {
          if (CornerPnt2.Z > CornerPnt1.Z)
          {
            num7 = num5 * 1.0;
            num8 = num6 * 1.0;
          }
          else
          {
            num7 = num5 * 1.0;
            num8 = num6 * -1.0;
          }
        }
        else if (CornerPnt2.Z > CornerPnt1.Z)
        {
          num7 = num5 * -1.0;
          num8 = num6 * 1.0;
        }
        else
        {
          num7 = num5 * -1.0;
          num8 = num6 * -1.0;
        }
        Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num8));
        Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt2.Z - num8));
        Points.Add(new Point3D(CornerPnt1.X + num7, CornerPnt1.Y, CornerPnt2.Z));
        Points.Add(new Point3D(CornerPnt2.X - num7, CornerPnt1.Y, CornerPnt2.Z));
        Points.Add(new Point3D(CornerPnt2.X, CornerPnt1.Y, CornerPnt2.Z - num8));
        Points.Add(new Point3D(CornerPnt2.X, CornerPnt1.Y, CornerPnt1.Z + num8));
        Points.Add(new Point3D(CornerPnt2.X - num7, CornerPnt1.Y, CornerPnt1.Z));
        Points.Add(new Point3D(CornerPnt1.X + num7, CornerPnt1.Y, CornerPnt1.Z));
        Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num8));
        Points.Add(new Point3D());
      }
      if (!buVector5.isPlaneYZorZY(Plane))
        return;
      double num9 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
      double num10 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
      double num11;
      double num12;
      if (CornerPnt2.Y > CornerPnt1.Y)
      {
        if (CornerPnt2.Z > CornerPnt1.Z)
        {
          num11 = num9 * 1.0;
          num12 = num10 * 1.0;
        }
        else
        {
          num11 = num9 * 1.0;
          num12 = num10 * -1.0;
        }
      }
      else if (CornerPnt2.Z > CornerPnt1.Z)
      {
        num11 = num9 * -1.0;
        num12 = num10 * 1.0;
      }
      else
      {
        num11 = num9 * -1.0;
        num12 = num10 * -1.0;
      }
      Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num12));
      Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt2.Z - num12));
      Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y + num11, CornerPnt2.Z));
      Points.Add(new Point3D(CornerPnt1.X, CornerPnt2.Y - num11, CornerPnt2.Z));
      Points.Add(new Point3D(CornerPnt1.X, CornerPnt2.Y, CornerPnt2.Z - num12));
      Points.Add(new Point3D(CornerPnt1.X, CornerPnt2.Y, CornerPnt1.Z + num12));
      Points.Add(new Point3D(CornerPnt2.X, CornerPnt2.Y - num11, CornerPnt1.Z));
      Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y + num11, CornerPnt1.Z));
      Points.Add(new Point3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num12));
    }
    catch (Exception ex)
    {
      string str = $"CornerPnt1: {CornerPnt1.ToString()} - CornerPnt2: {CornerPnt2.ToString()} - Plane: {Plane.ToString()} - Chamfer: {Chamfer.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

