  public void Rectangle3Point(
    Point3D FirstPoint,
    Point3D SecondPoint,
    Point3D ThirdPoint,
    Plane refPlane,
    ref List<Point3D> Vertices,
    ref Point3D ConnectPoint)
  {
    try
    {
      Point3D pntOver = new Point3D();
      Point3D point3D1 = new Point3D();
      Point3D point3D2 = new Point3D();
      Point3D point3D3 = new Point3D();
      Vertices.Clear();
      if (((F_EntitiesProps) this).isPointReflectionOverLine(FirstPoint, SecondPoint, ThirdPoint, 0.1, ref pntOver) && ((F_DeleteType) this).IsPointInsideLine(FirstPoint, SecondPoint, ThirdPoint, refPlane, 0.1))
      {
        Vertices.Add(F_NotchEdit.ToPoint3D(FirstPoint));
        Vertices.Add(F_NotchEdit.ToPoint3D(SecondPoint));
      }
      Point3D point3D4 = !((F_EntitiesProps) this).isPointReflectionOverLine(FirstPoint, SecondPoint, ThirdPoint, 0.1, ref pntOver) ? (this.Length3D(FirstPoint, ThirdPoint) >= this.Length3D(SecondPoint, ThirdPoint) ? F_NotchEdit.ToPoint3D(SecondPoint) : F_NotchEdit.ToPoint3D(FirstPoint)) : pntOver;
      ConnectPoint = F_NotchEdit.ToPoint3D(point3D4);
      double Length1 = this.Length3D(point3D4, ThirdPoint);
      double Length2 = this.Length3D(FirstPoint, SecondPoint);
      double num1 = this.PointAngle(FirstPoint, SecondPoint, refPlane);
      Vertices.Add(F_NotchEdit.ToPoint3D(FirstPoint));
      Vertices.Add(F_NotchEdit.ToPoint3D(SecondPoint));
      Point3D StartPnt1 = new Point3D();
      Point3D StartPnt2 = new Point3D();
      Point3D EndPnt1 = new Point3D();
      Point3D EndPnt2 = new Point3D();
      this.LineWithLengthAndAngle(SecondPoint, Length1, num1 - 90.0, refPlane, ref StartPnt1, ref EndPnt1);
      this.LineWithLengthAndAngle(SecondPoint, Length1, num1 + 90.0, refPlane, ref StartPnt2, ref EndPnt2);
      Point3D point3D5;
      Point3D point3D6;
      int num2;
      if (this.Length3D(EndPnt1, ThirdPoint) < this.Length3D(EndPnt2, ThirdPoint))
      {
        Vertices.Add(F_NotchEdit.ToPoint3D(EndPnt1));
        point3D5 = F_NotchEdit.ToPoint3D(StartPnt1);
        point3D6 = F_NotchEdit.ToPoint3D(EndPnt1);
        num2 = -1;
      }
      else
      {
        Vertices.Add(F_NotchEdit.ToPoint3D(EndPnt2));
        point3D5 = F_NotchEdit.ToPoint3D(StartPnt2);
        point3D6 = F_NotchEdit.ToPoint3D(EndPnt2);
        num2 = 1;
      }
      double num3 = this.PointAngle(point3D5, point3D6, refPlane);
      this.LineWithLengthAndAngle(point3D6, Length2, num3 + (double) (90 * num2), refPlane, ref StartPnt1, ref EndPnt1);
      Vertices.Add(F_NotchEdit.ToPoint3D(EndPnt1));
      Point3D point3D7 = F_NotchEdit.ToPoint3D(StartPnt1);
      Point3D point3D8 = F_NotchEdit.ToPoint3D(EndPnt1);
      double num4 = this.PointAngle(point3D7, point3D8, refPlane);
      this.LineWithLengthAndAngle(point3D8, Length1, num4 + (double) (90 * num2), refPlane, ref StartPnt1, ref EndPnt1);
      Vertices.Add(F_NotchEdit.ToPoint3D(EndPnt1));
      point3D2 = F_NotchEdit.ToPoint3D(StartPnt1);
      point3D3 = F_NotchEdit.ToPoint3D(EndPnt1);
    }
    catch (Exception ex)
    {
      string str = $"FirstPoint: {FirstPoint.ToString()} - SecondPoint: {SecondPoint.ToString()} - ThirdPoint: {ThirdPoint.ToString()} - Plane: {refPlane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void Rectangle2Point(
    Point3D FirstPoint,
    Point3D SecondPoint,
    Plane refPlane,
    ref Entity entRectangle)
  {
    List<Point3D> Vertices = new List<Point3D>();
    this.Rectangle2Point(FirstPoint, SecondPoint, refPlane, ref Vertices, ref entRectangle);
    Vertices.Clear();
  }

  public void Rectangle2Point(
    Point3D FirstPoint,
    Point3D SecondPoint,
    Plane refPlane,
    ref List<Point3D> Vertices,
    ref Entity entRectangle)
  {
    try
    {
      double s1;
      double t1;
      refPlane.Project(SecondPoint, out s1, out t1);
      double s2;
      double t2;
      refPlane.Project(FirstPoint, out s2, out t2);
      double width = s1 - s2;
      double height = t1 - t2;
      entRectangle = (Entity) CompositeCurve.CreateRectangle(refPlane, s2, t2, width, height);
      entRectangle.Regen(0.1);
      Vertices.Clear();
      for (int index = 0; index <= entRectangle.Vertices.Length - 1; ++index)
        Vertices.Add(new Point3D(entRectangle.Vertices[index].X, entRectangle.Vertices[index].Y, entRectangle.Vertices[index].Z));
    }
    catch (Exception ex)
    {
      string str = $"FirstPoint: {FirstPoint.ToString()} - SecondPoint: {SecondPoint.ToString()} - Plane: {refPlane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void PolygonCenter(
    Point3D pntBase,
    Point3D pntTip,
    int Side,
    Plane refPlane,
    ref List<Point3D> Vertices)
  {
    try
    {
      if (Side <= 2)
        return;
      Vertices.Clear();
      if (buVector5.isPlaneXYorYX(refPlane))
      {
        double num1 = this.Length3D(pntBase, pntTip);
        double num2 = 360.0 / (double) Side;
        double num3 = this.PointAngle(pntTip, pntTip, refPlane);
        double x1 = Math.Round(pntBase.X + num1 * Math.Cos(buString5.DegreeToRadian(num3 + 0.0 * num2)), 8);
        double y1 = Math.Round(pntBase.Y + num1 * Math.Sin(buString5.DegreeToRadian(num3 + 0.0 * num2)), 8);
        double z1 = Math.Round(pntBase.Z, 8);
        Vertices.Add(new Point3D(x1, y1, z1));
        for (int index = 0; index <= Side - 1; ++index)
        {
          double x2 = Math.Round(pntBase.X + num1 * Math.Cos(buString5.DegreeToRadian(num3 + (double) (index + 1) * num2)), 8);
          double y2 = Math.Round(pntBase.Y + num1 * Math.Sin(buString5.DegreeToRadian(num3 + (double) (index + 1) * num2)), 8);
          double z2 = Math.Round(pntBase.Z, 8);
          Vertices.Add(new Point3D(x2, y2, z2));
        }
      }
      if (buVector5.isPlaneXZorZX(refPlane))
      {
        double num4 = this.Length3D(pntBase, pntTip);
        double num5 = 360.0 / (double) Side;
        double num6 = this.PointAngle(pntTip, pntTip, refPlane);
        double x3 = Math.Round(pntBase.X + num4 * Math.Cos(buString5.DegreeToRadian(num6 + 0.0 * num5)), 8);
        double y3 = Math.Round(pntBase.Y, 8);
        double z3 = Math.Round(pntBase.Z + num4 * Math.Sin(buString5.DegreeToRadian(num6 + 0.0 * num5)), 8);
        Vertices.Add(new Point3D(x3, y3, z3));
        for (int index = 0; index <= Side - 1; ++index)
        {
          double x4 = Math.Round(pntBase.X + num4 * Math.Cos(buString5.DegreeToRadian(num6 + (double) (index + 1) * num5)), 8);
          double y4 = Math.Round(pntBase.Y, 8);
          double z4 = Math.Round(pntBase.Z + num4 * Math.Sin(buString5.DegreeToRadian(num6 + (double) (index + 1) * num5)), 8);
          Vertices.Add(new Point3D(x4, y4, z4));
        }
      }
      if (!buVector5.isPlaneYZorZY(refPlane))
        return;
      double num7 = this.Length3D(pntBase, pntTip);
      double num8 = 360.0 / (double) Side;
      double num9 = this.PointAngle(pntTip, pntTip, refPlane);
      double x5 = Math.Round(pntBase.X, 8);
      double y5 = Math.Round(pntBase.Y + num7 * Math.Cos(buString5.DegreeToRadian(num9 + 0.0 * num8)), 8);
      double z5 = Math.Round(pntBase.Z + num7 * Math.Sin(buString5.DegreeToRadian(num9 + 0.0 * num8)), 8);
      Vertices.Add(new Point3D(x5, y5, z5));
      for (int index = 0; index <= Side - 1; ++index)
      {
        double x6 = Math.Round(pntBase.X, 8);
        double y6 = Math.Round(pntBase.Y + num7 * Math.Cos(buString5.DegreeToRadian(num9 + (double) (index + 1) * num8)), 8);
        double z6 = Math.Round(pntBase.Z + num7 * Math.Sin(buString5.DegreeToRadian(num9 + (double) (index + 1) * num8)), 8);
        Vertices.Add(new Point3D(x6, y6, z6));
      }
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void PolygonCenter(
    Point3D pntBase,
    double Radius,
    int Side,
    Plane refPlane,
    ref List<Point3D> Vertices)
  {
    Point3D pntTip = new Point3D();
    if (buVector5.isPlaneXYorYX(refPlane))
      pntTip = new Point3D(pntBase.X + Radius, pntBase.Y, pntBase.Z);
    if (buVector5.isPlaneXZorZX(refPlane))
      pntTip = new Point3D(pntBase.X + Radius, pntBase.Y, pntBase.Z);
    if (buVector5.isPlaneYZ(refPlane))
      pntTip = new Point3D(pntBase.X, pntBase.Y + Radius, pntBase.Z);
    this.PolygonCenter(pntBase, pntTip, Side, refPlane, ref Vertices);
  }

  public double CrossProductLength(Point3D PA, Point3D PB, Point3D PC)
  {
    return this.CrossProductLength(PA.X, PA.Y, PB.X, PB.Y, PC.X, PC.Y);
  }

  public double CrossProductLength(
    double Ax,
    double Ay,
    double Bx,
    double By,
    double Cx,
    double Cy)
  {
    double num1 = Ax - Bx;
    double num2 = Ay - By;
    double num3 = Cx - Bx;
    double num4 = Cy - By;
    return num1 * num4 - num2 * num3;
  }

  public Entity Slot3Point(Point3D First, Point3D Second, Point3D Third, Plane refPlane)
  {
    double radius = this.SlotRad((Point2D) First, (Point2D) Second, (Point2D) Third);
    if (radius <= 0.0)
      radius = 0.1;
    return (Entity) CompositeCurve.CreateSlot(refPlane, First.X, First.Y, First.DistanceTo(Second), radius, (Second - First).AsVector.Angle);
  }

  public Entity Slot3Point(Point2D First, Point2D Second, Point2D Third)
  {
    double radius = this.SlotRad(First, Second, Third);
    if (radius <= 0.0)
      radius = 0.1;
    return (Entity) CompositeCurve.CreateSlot(Plane.XY, First.X, First.Y, First.DistanceTo(Second), radius, (Second - First).AsVector.Angle);
  }

  public double SlotRad(Point2D start, Point2D end, Point2D radial)
  {
    Segment2D segment2D = new Segment2D(start, end);
    Point2D b = segment2D.PointAt(segment2D.ClosestPointTo(radial));
    return radial.DistanceTo(b);
  }

  public void KeyHole(
    Point3D HeadPosition,
    double HeadRadius,
    double TaleRadius,
    double Length,
    double Angle,
    bool Reverse,
    Plane refPlane,
    ref buArc HeadArc,
    ref buArc TaleArc)
  {
    try
    {
      double num1 = 0.0;
      if (Reverse)
        num1 = 180.0;
      Point3D point3D = new Point3D();
      if (buVector5.isPlaneXYorYX(refPlane))
      {
        double num2 = HeadPosition.Y + TaleRadius;
        double num3 = Math.Sqrt(Math.Pow(HeadRadius, 2.0) - Math.Pow(HeadPosition.Y - num2, 2.0));
        double num4 = HeadPosition.X + num3;
        double degree = buString5.RadianToDegree(Math.Atan((num2 - HeadPosition.Y) / (num4 - HeadPosition.X)));
        double num5 = 360.0 - degree;
        double startAngle1 = degree + Angle + num1;
        double endAngle1 = num5 + Angle + num1;
        if (startAngle1 > 360.0 & endAngle1 > 360.0)
        {
          startAngle1 -= 360.0;
          endAngle1 -= 360.0;
        }
        HeadArc = (buArc) new buEntityList(refPlane, F_NotchEdit.ToPoint3D(HeadPosition), HeadRadius, startAngle1, endAngle1);
        Point3D EndPnt = new Point3D();
        Point3D StartPnt = new Point3D();
        this.LineWithLengthAndAngle(HeadPosition, Length, Angle + num1, refPlane, ref StartPnt, ref EndPnt);
        double startAngle2 = 270.0 + Angle + num1;
        double endAngle2 = 450.0 + Angle + num1;
        if (startAngle2 > 360.0 & endAngle2 > 360.0)
        {
          startAngle2 -= 360.0;
          endAngle2 -= 360.0;
        }
        TaleArc = (buArc) new buEntityList(refPlane, F_NotchEdit.ToPoint3D(EndPnt), TaleRadius, startAngle2, endAngle2);
      }
      else if (buVector5.isPlaneXZorZX(refPlane))
      {
        double num6 = HeadPosition.Z + TaleRadius;
        double num7 = Math.Sqrt(Math.Pow(HeadRadius, 2.0) - Math.Pow(HeadPosition.Z - num6, 2.0));
        double num8 = HeadPosition.X + num7;
        double degree = buString5.RadianToDegree(Math.Atan((num6 - HeadPosition.Z) / (num8 - HeadPosition.X)));
        double num9 = 360.0 - degree;
        double startAngle3 = degree + Angle + num1;
        double endAngle3 = num9 + Angle + num1;
        if (startAngle3 > 360.0 & endAngle3 > 360.0)
        {
          startAngle3 -= 360.0;
          endAngle3 -= 360.0;
        }
        HeadArc = (buArc) new buEntityList(refPlane, F_NotchEdit.ToPoint3D(HeadPosition), HeadRadius, startAngle3, endAngle3);
        Point3D EndPnt = new Point3D();
        Point3D StartPnt = new Point3D();
        this.LineWithLengthAndAngle(HeadPosition, Length, Angle + num1, refPlane, ref StartPnt, ref EndPnt);
        double startAngle4 = 270.0 + Angle + num1;
        double endAngle4 = 450.0 + Angle + num1;
        if (startAngle4 > 360.0 & endAngle4 > 360.0)
        {
          startAngle4 -= 360.0;
          endAngle4 -= 360.0;
        }
        TaleArc = (buArc) new buEntityList(refPlane, F_NotchEdit.ToPoint3D(EndPnt), TaleRadius, startAngle4, endAngle4);
      }
      else
      {
        if (!buVector5.isPlaneYZorZY(refPlane))
          return;
        double num10 = HeadPosition.Z + TaleRadius;
        double num11 = Math.Sqrt(Math.Pow(HeadRadius, 2.0) - Math.Pow(HeadPosition.Z - num10, 2.0));
        double num12 = HeadPosition.Y + num11;
        double degree = buString5.RadianToDegree(Math.Atan((num10 - HeadPosition.Z) / (num12 - HeadPosition.Y)));
        double num13 = 360.0 - degree;
        double startAngle5 = degree + Angle + num1;
        double endAngle5 = num13 + Angle + num1;
        if (startAngle5 > 360.0 & endAngle5 > 360.0)
        {
          startAngle5 -= 360.0;
          endAngle5 -= 360.0;
        }
        HeadArc = (buArc) new buEntityList(refPlane, F_NotchEdit.ToPoint3D(HeadPosition), HeadRadius, startAngle5, endAngle5);
        Point3D EndPnt = new Point3D();
        Point3D StartPnt = new Point3D();
        this.LineWithLengthAndAngle(HeadPosition, Length + num1, Angle, refPlane, ref StartPnt, ref EndPnt);
        double startAngle6 = 270.0 + Angle + num1;
        double endAngle6 = 450.0 + Angle + num1;
        if (startAngle6 > 360.0 & endAngle6 > 360.0)
        {
          startAngle6 -= 360.0;
          endAngle6 -= 360.0;
        }
        TaleArc = (buArc) new buEntityList(refPlane, F_NotchEdit.ToPoint3D(EndPnt), TaleRadius, startAngle6, endAngle6);
      }
    }
    catch (Exception ex)
    {
      string str = $"HeadPosition: {HeadPosition.ToString()} - HeadRadius: {HeadRadius.ToString()} - TaleRadius: {TaleRadius.ToString()} - Length: {Length.ToString()} - Angle: {Angle.ToString()} - Plane: {refPlane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

