  public void EntitiesToSweep(
    List<buEntity> refEntities,
    double RampHeight,
    double RampLength,
    double TargetZ,
    CamZRampType RampType,
    ref buEntity SweepEntity,
    double Resolution = 0.1)
  {
    List<Point3D> Points1 = new List<Point3D>();
    for (int index = 0; index <= refEntities.Count - 1; ++index)
    {
      List<Point3D> pntDevided = new List<Point3D>();
      this.EntityDevideByCamDir(refEntities[index], Resolution, ref pntDevided);
      Points1.AddRange((IEnumerable<Point3D>) pntDevided);
    }
    ((F_CutterMachineSettings) this).CheckDuplicatedPointsWithPrevious(ref Points1);
    List<Point3D> collection1 = new List<Point3D>();
    List<Point3D> collection2 = new List<Point3D>();
    List<Point3D> collection3 = new List<Point3D>();
    this.DevidePointList(Points1, Resolution + 0.1, RampLength, RampLength, true, DevideTipType.StartAndEnd, ref collection1, ref collection2, ref collection3);
    this.Move(0.0, 0.0, TargetZ, ref collection1);
    this.Move(0.0, 0.0, TargetZ, ref collection2);
    this.Move(0.0, 0.0, TargetZ, ref collection3);
    List<double> doubleList1 = new List<double>();
    List<double> doubleList2;
    if (RampType == CamZRampType.Linear)
    {
      doubleList2 = new List<double>();
      buFile5.DevideMinMaxValueByNumber(RampHeight, TargetZ, collection1.Count, ref doubleList2);
      for (int index = 0; index <= doubleList2.Count - 1; ++index)
        collection1[index] = new Point3D(collection1[index].X, collection1[index].Y, doubleList2[index]);
      doubleList2 = new List<double>();
      buFile5.DevideMinMaxValueByNumber(TargetZ, RampHeight, collection3.Count, ref doubleList2);
      for (int index = 0; index <= doubleList2.Count - 1; ++index)
        collection3[index] = new Point3D(collection3[index].X, collection3[index].Y, doubleList2[index]);
    }
    if (RampType == CamZRampType.Circular)
    {
      List<Point3D> Points2 = new List<Point3D>();
      doubleList2 = new List<double>();
      this.CircularZHeightRampByLengthAndHeight(RampLength, RampHeight, TargetZ, 1.0, 200, ref doubleList2, ref Points2);
      double num1 = 0.0;
      collection1[0] = new Point3D(collection1[0].X, collection1[0].Y, doubleList2[0]);
      for (int index1 = 1; index1 <= collection1.Count - 1; ++index1)
      {
        double num2 = this.Length3D(collection1[index1 - 1], collection1[index1], Plane.XY);
        num1 += num2;
        double num3 = 0.0;
        double num4 = 0.0;
        for (int index2 = 1; index2 <= Points2.Count - 1; ++index2)
        {
          double num5 = this.Length3D(Points2[index2 - 1], Points2[index2], Plane.XY);
          num3 += num5;
          if (num4 <= num1 & num1 <= num3)
          {
            collection1[index1] = new Point3D(collection1[index1].X, collection1[index1].Y, doubleList2[index2]);
            index2 = 100000;
          }
          num4 = num3;
        }
      }
      collection1[collection1.Count - 1] = new Point3D(collection1[collection1.Count - 1].X, collection1[collection1.Count - 1].Y, doubleList2[doubleList2.Count - 1]);
      doubleList2 = new List<double>();
      this.CircularZHeightRampByLengthAndHeight(RampLength, TargetZ, RampHeight, 1.0, 200, ref doubleList2, ref Points2);
      double num6 = 0.0;
      collection3[0] = new Point3D(collection3[0].X, collection3[0].Y, doubleList2[0]);
      for (int index3 = 1; index3 <= collection3.Count - 1; ++index3)
      {
        double num7 = this.Length3D(collection3[index3 - 1], collection3[index3], Plane.XY);
        num6 += num7;
        double num8 = 0.0;
        double num9 = 0.0;
        for (int index4 = 1; index4 <= Points2.Count - 1; ++index4)
        {
          double num10 = this.Length3D(Points2[index4 - 1], Points2[index4], Plane.XY);
          num8 += num10;
          if (num9 <= num6 & num6 <= num8)
          {
            collection3[index3] = new Point3D(collection3[index3].X, collection3[index3].Y, doubleList2[index4]);
            index4 = 100000;
          }
          num9 = num8;
        }
      }
      collection3[collection3.Count - 1] = new Point3D(collection3[collection3.Count - 1].X, collection3[collection3.Count - 1].Y, doubleList2[doubleList2.Count - 1]);
    }
    List<Point3D> Points3 = new List<Point3D>();
    Points3.AddRange((IEnumerable<Point3D>) collection1);
    Points3.AddRange((IEnumerable<Point3D>) collection2);
    Points3.AddRange((IEnumerable<Point3D>) collection3);
    ((F_CutterMachineSettings) this).CheckDuplicatedPointsWithPrevious(ref Points3);
    if (Points3.Count >= 2)
      SweepEntity = (buEntity) new buShape(Points3);
    else
      SweepEntity = (buEntity) null;
  }

  public void DrawHelix(
    Point3D Center,
    double Diameter,
    double Depth,
    double Pitch,
    Plane refPlane,
    ref List<Point3D> Points,
    double DegreeResolution = 1.0)
  {
    double num = Depth / Pitch * 360.0;
    if (Points == null)
      Points = new List<Point3D>();
    Points.Clear();
    for (double Degree = 0.0; Degree <= num; Degree += DegreeResolution)
    {
      Point3D point3D = new Point3D();
      if (refPlane.Equation.Z > 0.0)
      {
        point3D.X = Center.X + Diameter * 0.5 * Math.Cos(buString5.DegreeToRadian(Degree));
        point3D.Y = Center.Y + Diameter * 0.5 * Math.Sin(buString5.DegreeToRadian(Degree));
        point3D.Z = Center.Z - Pitch * Degree / 360.0;
      }
      if (refPlane.Equation.Z < 0.0)
      {
        point3D.X = Center.X + Diameter * 0.5 * Math.Cos(buString5.DegreeToRadian(Degree));
        point3D.Y = Center.Y + Diameter * 0.5 * Math.Sin(buString5.DegreeToRadian(Degree));
        point3D.Z = Center.Z + Pitch * Degree / 360.0;
      }
      if (refPlane.Equation.Y > 0.0)
      {
        point3D.X = Center.X + Diameter * 0.5 * Math.Cos(buString5.DegreeToRadian(Degree));
        point3D.Y = Center.Y - Pitch * Degree / 360.0;
        point3D.Z = Center.Z + Diameter * 0.5 * Math.Sin(buString5.DegreeToRadian(Degree));
      }
      if (refPlane.Equation.Y < 0.0)
      {
        point3D.X = Center.X + Diameter * 0.5 * Math.Cos(buString5.DegreeToRadian(Degree));
        point3D.Y = Center.Y + Pitch * Degree / 360.0;
        point3D.Z = Center.Z + Diameter * 0.5 * Math.Sin(buString5.DegreeToRadian(Degree));
      }
      Points.Add(point3D);
    }
  }

  public void SurfaceToFaceAsMesh(Entity entSurface, ref List<devDept.Eyeshot.Entities.Mesh> FaceMeshes)
  {
    FaceMeshes = new List<devDept.Eyeshot.Entities.Mesh>();
    switch (entSurface)
    {
      case devDept.Eyeshot.Entities.Brep _:
        devDept.Eyeshot.Entities.Brep brep = entSurface as devDept.Eyeshot.Entities.Brep;
        if (brep.Faces == null)
          break;
        for (int index = 0; index <= brep.Faces.Length - 1; ++index)
        {
          if (brep.Faces[index].Tessellation == null)
            brep.Regen(0.01);
          if (brep.Faces[index].Tessellation != null)
          {
            FastMesh fastMesh = (FastMesh) brep.Faces[index].Tessellation.Clone();
            FaceMeshes.Add(fastMesh.ConvertToMesh());
          }
        }
        break;
      case devDept.Eyeshot.Entities.Surface _:
        devDept.Eyeshot.Entities.Mesh mesh = ((devDept.Eyeshot.Entities.Surface) entSurface).ConvertToMesh(0.01);
        FaceMeshes.Add(mesh);
        break;
    }
  }

  public void SurfaceToFaceAsSurface(Entity entSurface, ref List<devDept.Eyeshot.Entities.Surface> FaceSurface)
  {
    FaceSurface = new List<devDept.Eyeshot.Entities.Surface>();
    if (!(entSurface is devDept.Eyeshot.Entities.Brep))
      return;
    devDept.Eyeshot.Entities.Brep brep = entSurface as devDept.Eyeshot.Entities.Brep;
    if (brep.Faces == null)
      return;
    brep.Rebuild();
    for (int index1 = 0; index1 <= brep.Faces.Length - 1; ++index1)
    {
      devDept.Eyeshot.Entities.Surface[] surface1 = brep.Faces[index1].ConvertToSurface();
      if (surface1 != null)
      {
        for (int index2 = 0; index2 <= surface1.Length - 1; ++index2)
        {
          devDept.Eyeshot.Entities.Surface surface2 = (devDept.Eyeshot.Entities.Surface) surface1[index2].Clone();
          FaceSurface.Add(surface2);
        }
      }
    }
  }

  public void SurfaceToFaceAsCurve(Entity entSurface, ref List<Entity> CurveSurface)
  {
    CurveSurface = new List<Entity>();
    if (entSurface is devDept.Eyeshot.Entities.Brep)
    {
      devDept.Eyeshot.Entities.Brep brep = entSurface as devDept.Eyeshot.Entities.Brep;
      if (brep.Edges != null)
      {
        brep.Rebuild();
        for (int index = 0; index <= brep.Edges.Length - 1; ++index)
        {
          Entity curve = (Entity) brep.Edges[index].Curve;
          if (curve != null)
            CurveSurface.Add((Entity) curve.Clone());
        }
      }
    }
    if (!(entSurface is devDept.Eyeshot.Entities.Surface) || !(entSurface is devDept.Eyeshot.Entities.Surface surface))
      return;
    surface.RebuildEdges(0.01);
    ICurve[] edges = surface.ExtractEdges();
    for (int index = 0; index <= edges.Length - 1; ++index)
    {
      Entity entity = (Entity) edges[index];
      if (entity != null)
        CurveSurface.Add((Entity) entity.Clone());
    }
  }

  public void SurfaceToControlPoints(Entity entSurface, ref List<List<Point3D>> ControlPoints)
  {
    switch (entSurface)
    {
      case devDept.Eyeshot.Entities.Brep _:
        devDept.Eyeshot.Entities.Brep brep = entSurface as devDept.Eyeshot.Entities.Brep;
        if (brep.Faces == null)
          break;
        for (int index = 0; index <= brep.Faces.Length - 1; ++index)
        {
          if (brep.Faces[index].Tessellation == null)
            brep.Regen(0.01);
          if (brep.Faces[index].Tessellation != null)
            ;
        }
        break;
      case devDept.Eyeshot.Entities.Surface _:
        ControlPoints = new List<List<Point3D>>();
        devDept.Eyeshot.Entities.Surface surface = entSurface as devDept.Eyeshot.Entities.Surface;
        if (surface.ControlPoints == null)
          break;
        int num1 = surface.KnotVectorU.Length - surface.DegreeU - 1;
        int num2 = surface.KnotVectorV.Length - surface.DegreeV - 1;
        int index1 = 0;
        int index2 = 0;
        List<Point3D> point3DList = new List<Point3D>();
        for (int index3 = 0; index3 <= surface.ControlPoints.Length - 1; ++index3)
        {
          Point3D euclid = surface.ControlPoints[index1, index2].Euclid;
          point3DList.Add(euclid);
          if (index3 > 0 & point3DList.Count == num2)
          {
            index2 = 0;
            ++index1;
            ControlPoints.Add(point3DList);
            point3DList = new List<Point3D>();
          }
          else
            ++index2;
        }
        break;
    }
  }

  public void GetMeshSurfacePointsFromDepth(
    List<Entity> entMesh,
    double DepthLevel,
    Plane refPlane,
    MeshToSurfacePointsSettings Settings,
    ref List<Point3D> Outside,
    ref List<List<Point3D>> Insides)
  {
    Point3D MinPoint = new Point3D();
    Point3D MidPoint = new Point3D();
    Point3D MaxPoint = new Point3D();
    this.BoxSizeCalculate(entMesh, ref MinPoint, ref MidPoint, ref MaxPoint);
    if (!buVector5.isPlaneXYorYX(refPlane))
      return;
    if (((ObjectSize3D) Settings).BoxBoundOffset > 0.0)
    {
      MinPoint.X -= ((ObjectSize3D) Settings).BoxBoundOffset;
      MinPoint.Y -= ((ObjectSize3D) Settings).BoxBoundOffset;
      MaxPoint.X += ((ObjectSize3D) Settings).BoxBoundOffset;
      MaxPoint.Y += ((ObjectSize3D) Settings).BoxBoundOffset;
    }
    double num = this.Length2D(MinPoint, MaxPoint, refPlane);
    if (num <= 0.0)
      return;
