      Plane plane = new Plane(((EyeCreateProps) Calc).NormalVector);
      double c = this.PointAngle(new Point3D(((EyeCreateProps) Calc).NormalVector.X, ((EyeCreateProps) Calc).NormalVector.Y, ((EyeCreateProps) Calc).NormalVector.Z), new Point3D(), Plane.XY);
      double b2 = this.PointAngle(new Point3D(((EyeCreateProps) Calc).NormalVector.X, ((EyeCreateProps) Calc).NormalVector.Y, ((EyeCreateProps) Calc).NormalVector.Z), new Point3D(), Plane.XZ);
      double a = this.PointAngle(new Point3D(((EyeCreateProps) Calc).NormalVector.X, ((EyeCreateProps) Calc).NormalVector.Y, ((EyeCreateProps) Calc).NormalVector.Z), new Point3D(), Plane.YZ);
      Line line = new Line(new Point3D(point3D1.X, point3D1.Y, point3D1.Z), new Point3D(point3D1.X + ((EyeCreateProps) Settings).SurfaceNormalLength * ((EyeCreateProps) Calc).NormalVector.X, point3D1.Y + ((EyeCreateProps) Settings).SurfaceNormalLength * ((EyeCreateProps) Calc).NormalVector.Y, point3D1.Z + ((EyeCreateProps) Settings).SurfaceNormalLength * ((EyeCreateProps) Calc).NormalVector.Z));
      ((EyeCreateProps) Calc).normalEntities = (Entity) line;
      ((EyeCreateProps) Calc).normalPoint = new Pnt6D(point3D1.X, point3D1.Y, point3D1.Z, a, b2, c);
      return true;
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return false;
    }
