  public void SurfaceWithTwoVerticeList(
    List<Point3D> FirstVertice,
    List<Point3D> SecondVertice,
    ref List<devDept.Eyeshot.Entities.Triangle> SurfaceTriangles)
  {
    try
    {
      Point3D point3D1 = new Point3D();
      Point3D point3D2 = new Point3D();
      Point3D point3D3 = new Point3D();
      SurfaceTriangles.Clear();
      if (FirstVertice.Count != SecondVertice.Count || FirstVertice.Count <= 0)
        return;
      for (int index = 0; index <= FirstVertice.Count - 2; ++index)
      {
        devDept.Eyeshot.Entities.Triangle triangle1 = new devDept.Eyeshot.Entities.Triangle(F_NotchEdit.ToPoint3D(FirstVertice[index]), F_NotchEdit.ToPoint3D(SecondVertice[index]), F_NotchEdit.ToPoint3D(FirstVertice[index + 1]));
        SurfaceTriangles.Add(triangle1);
        devDept.Eyeshot.Entities.Triangle triangle2 = new devDept.Eyeshot.Entities.Triangle(F_NotchEdit.ToPoint3D(FirstVertice[index + 1]), F_NotchEdit.ToPoint3D(SecondVertice[index + 1]), F_NotchEdit.ToPoint3D(SecondVertice[index]));
        SurfaceTriangles.Add(triangle2);
      }
    }
    catch (Exception ex)
    {
      string str = $"FirstVertice: {FirstVertice.Count.ToString()} - SecondVertice: {SecondVertice.Count.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void CreateBoxProfile(
    double Width,
    double Height,
    double Length,
    double FirstAngle,
    double EndAngle,
    bool IfLengthSmallFitLength,
    ref Entity entProfile)
  {
    int num1 = 1;
    double num2 = Length;
    List<Point3D> points1;
    List<Point3D> points2;
    while (true)
    {
      points1 = new List<Point3D>();
      double num3 = Math.Tan(buString5.DegreeToRadian(FirstAngle)) * Width;
      points1.Add(new Point3D(0.0, 0.0, 0.0));
      points1.Add(new Point3D(0.0, 0.0, Height));
      points1.Add(new Point3D(0.0 - num3, Width, Height));
      points1.Add(new Point3D(0.0 - num3, Width, 0.0));
      points1.Add(new Point3D(0.0, 0.0, 0.0));
      LinearPath linearPath1 = new LinearPath((ICollection<Point3D>) points1);
      points2 = new List<Point3D>();
      double num4 = Math.Tan(buString5.DegreeToRadian(EndAngle)) * Width;
      points2.Add(new Point3D(0.0 + num2, 0.0, 0.0));
      points2.Add(new Point3D(0.0 + num2, 0.0, Height));
      points2.Add(new Point3D(0.0 - num4 + num2, Width, Height));
      points2.Add(new Point3D(0.0 - num4 + num2, Width, 0.0));
      points2.Add(new Point3D(0.0 + num2, 0.0, 0.0));
      LinearPath linearPath2 = new LinearPath((ICollection<Point3D>) points2);
      ++num1;
      if (IfLengthSmallFitLength && points1[2].X > points2[2].X & num1 < 20)
        num2 += Math.Round(points1[2].X - points2[2].X, 3);
      else
        break;
    }
    devDept.Eyeshot.Entities.Surface surface = devDept.Eyeshot.Entities.Surface.GlobalInterpolation(new Point3D[2, 5]
    {
      {
        points1[0],
        points1[1],
        points1[2],
        points1[3],
        points1[4]
      },
      {
        points2[0],
        points2[1],
        points2[2],
        points2[3],
        points2[4]
      }
    }, 1, 1);
    entProfile = (Entity) surface;
    entProfile.Color = Color.Gray;
    entProfile.ColorMethod = colorMethodType.byEntity;
  }

