  public void SurfaceExturudeByEntities(
    List<buEntity> refEntities,
    Vector3D Direction,
    double Length,
    bool MoveToZero,
    double DevideLen,
    ref buEntity entSureface)
  {
    List<Point3D> Points = new List<Point3D>();
    Point3D MinPoint = new Point3D();
    Point3D MaxPoint = new Point3D();
    SortbuSettings Settings = (SortbuSettings) new MeasureItem();
    SortbuResult Result = (SortbuResult) new MachineConfigSettings();
    ((ShapeUpdateArg) ((ShapeArray) Settings).Option).IntersectionRules = SortingIntersectionRulesType.FromDrawing;
    ((ShapeUpdateArg) ((ShapeArray) Settings).Option).NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
    Point3D point3D = new Point3D();
    List<buEntity> SortedEntities = new List<buEntity>();
    this.BoxSizeCalculate(refEntities, ref MinPoint, ref MaxPoint);
    if (MoveToZero)
    {
      this.Move(-MinPoint.X, -MinPoint.Y, -MinPoint.Z, ref refEntities);
      MinPoint = new Point3D();
      this.SortEntitiesByRefPoint(MinPoint, ref refEntities, Settings, ref SortedEntities, ref Result);
    }
    else
      this.SortEntitiesByRefPoint(MinPoint, ref refEntities, Settings, ref SortedEntities, ref Result);
    if (DevideLen > 0.0)
    {
      for (int index = 0; index <= SortedEntities.Count - 1; ++index)
      {
        List<Point3D> pntDevided = new List<Point3D>();
        this.EntityDevideByCamDir(SortedEntities[index], 0.5, ref pntDevided);
        Points.AddRange((IEnumerable<Point3D>) pntDevided);
      }
    }
    else
      this.EntitiesToPointsWithCamDirection(SortedEntities, ref Points);
    ((F_CutterMachineSettings) this).CheckDuplicatedPointsWithPrevious(ref Points);
    ClockDirectionType clockDirection = this.GetClockDirection(Points);
    Plane xy = Plane.XY;
    this.isPointsWhichPlane(Points, ref xy);
    if (!buVector5.isPlaneXYorYX(xy))
      return;
    if (Direction == Vector3D.AxisX)
    {
      if (clockDirection == ClockDirectionType.CW)
        Points.Reverse();
      this.Rotate(MinPoint, 90.0, Plane.YZ, ref Points);
      this.Rotate(MinPoint, 90.0, Plane.XY, ref Points);
      devDept.Eyeshot.Entities.Mesh another = new devDept.Eyeshot.Entities.Region((ICurve) new LinearPath((ICollection<Point3D>) Points)).ExtrudeAsMesh(Length, 0.1, devDept.Eyeshot.Entities.Mesh.natureType.RichSmooth);
      if (another != null)
        entSureface = (buEntity) new buShapeFreeLines(another);
    }
    if (!(Direction == Vector3D.AxisY))
      return;
    if (clockDirection == ClockDirectionType.CW)
      ;
    this.Rotate(MinPoint, 90.0, Plane.YZ, ref Points);
    devDept.Eyeshot.Entities.Mesh another1 = new devDept.Eyeshot.Entities.Region((ICurve) new LinearPath((ICollection<Point3D>) Points)).ExtrudeAsMesh(Length, 0.1, devDept.Eyeshot.Entities.Mesh.natureType.RichSmooth);
    if (another1 == null)
      return;
    entSureface = (buEntity) new buShapeFreeLines(another1);
  }

  public void SurfaceExturudeByPoints(
    List<Point3D> refPoints,
    Vector3D Direction,
    double Length,
    ref Entity entSureface,
    bool AsMesh = false)
  {
    Point3D MinPoint = new Point3D();
    Point3D MaxPoint = new Point3D();
    List<Point3D> point3DList = new List<Point3D>();
    buVector5.Copy(refPoints, ref point3DList);
    this.BoxSizeCalculate(point3DList, ref MinPoint, ref MaxPoint);
    ClockDirectionType clockDirection = this.GetClockDirection(point3DList);
    Plane xy = Plane.XY;
    this.isPointsWhichPlane(point3DList, ref xy);
    if (buVector5.isPlaneXYorYX(xy))
    {
      if (Direction == Vector3D.AxisX)
      {
        if (clockDirection == ClockDirectionType.CW)
          point3DList.Reverse();
        this.Rotate(MinPoint, 90.0, Plane.YZ, ref point3DList);
        this.Rotate(MinPoint, 90.0, Plane.XY, ref point3DList);
        devDept.Eyeshot.Entities.Brep brep = new devDept.Eyeshot.Entities.Region((ICurve) new LinearPath((ICollection<Point3D>) point3DList)).ExtrudeAsBrep(Length, 0.0, 0.0);
        if (brep != null)
          entSureface = (Entity) brep;
      }
      if (Direction == Vector3D.AxisY)
      {
        if (clockDirection == ClockDirectionType.CW)
          ;
        this.Rotate(MinPoint, 90.0, Plane.YZ, ref point3DList);
        devDept.Eyeshot.Entities.Brep brep = new devDept.Eyeshot.Entities.Region((ICurve) new LinearPath((ICollection<Point3D>) point3DList)).ExtrudeAsBrep(Length, 0.0, 0.0);
        if (brep != null)
          entSureface = (Entity) brep;
      }
    }
    if (buVector5.isPlaneXZorZX(xy) && Direction == Vector3D.AxisY)
    {
      LinearPath outer = new LinearPath((ICollection<Point3D>) point3DList);
      devDept.Eyeshot.Entities.Mesh mesh = outer.ExtrudeAsMesh(new Vector3D(0.0, Length, 0.0), 0.1, devDept.Eyeshot.Entities.Mesh.natureType.RichSmooth);
      if (new devDept.Eyeshot.Entities.Region((ICurve) outer).ExtrudeAsBrep(Length, 0.0, 0.0) != null)
        entSureface = (Entity) mesh;
    }
    if (buVector5.isPlaneYZorZY(xy) && Direction == Vector3D.AxisX)
    {
      devDept.Eyeshot.Entities.Brep brep = new devDept.Eyeshot.Entities.Region((ICurve) new LinearPath((ICollection<Point3D>) point3DList)).ExtrudeAsBrep(new Vector3D(Length, 0.0, 0.0));
      brep.Regen(0.1);
      if (brep != null)
        entSureface = (Entity) brep;
    }
    if (entSureface == null)
      return;
    if (entSureface is devDept.Eyeshot.Entities.Brep)
    {
      entSureface.Regen(0.1);
      entSureface = (Entity) ((devDept.Eyeshot.Entities.Brep) entSureface).ConvertToMesh();
    }
    else
    {
      if (!(entSureface is devDept.Eyeshot.Entities.Mesh))
        return;
      entSureface.Regen(0.1);
    }
  }

