  public int surfaceRevolveByPath(
    CompositeCurve refCurve,
    Vector3D Axis,
    Point3D refPoint,
    double StartAngle,
    double DeltaAngle,
    ref Entity entRevolved,
    ref Entity entTop,
    ref Entity entBottom,
    double Regen = 0.1,
    bool AsMesh = false,
    int MeshSlices = 360,
    bool CreateTop = true,
    bool CreateBottom = true)
  {
    try
    {
      devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region((ICurve) refCurve);
      region.Regen(0.05);
      refCurve.Regen(0.05);
      Plane plane = new Plane(Axis);
      double radius1 = this.Length3D(refPoint, refCurve.Vertices[0], plane);
      double radius2 = this.Length3D(refPoint, refCurve.Vertices[refCurve.Vertices.Length - 1], plane);
      Entity entity1;
      Entity entity2;
      Entity entity3;
      if (!AsMesh)
      {
        entity1 = (Entity) region.RevolveAsBrep(Utility.DegToRad(StartAngle), Utility.DegToRad(DeltaAngle), Axis, refPoint);
        entity1.Regen(Regen);
        entity2 = (Entity) new devDept.Eyeshot.Entities.Region((ICurve) new Circle(plane, refPoint, radius1)).ExtrudeAsBrep(Axis * 0.1);
        entity2.Translate(Axis.X * refCurve.Vertices[0].X, Axis.Y * refCurve.Vertices[0].Y, Axis.Z * refCurve.Vertices[0].Z);
        entity2.Regen(Regen);
        entity3 = (Entity) new devDept.Eyeshot.Entities.Region((ICurve) new Circle(plane, refPoint, radius2)).ExtrudeAsBrep(Axis * -0.1);
        entity3.Translate(Axis.X * refCurve.Vertices[refCurve.Vertices.Length - 1].X, Axis.Y * refCurve.Vertices[refCurve.Vertices.Length - 1].Y, Axis.Z * refCurve.Vertices[refCurve.Vertices.Length - 1].Z);
        entity3.Regen(Regen);
      }
      else
      {
        entity1 = (Entity) region.RevolveAsMesh(Utility.DegToRad(StartAngle), Utility.DegToRad(DeltaAngle), Axis, refPoint, MeshSlices, 0.01, devDept.Eyeshot.Entities.Mesh.natureType.RichSmooth);
        entity2 = (Entity) new Circle(plane, refPoint, radius1).ExtrudeAsMesh(Axis * 0.1, Regen, devDept.Eyeshot.Entities.Mesh.natureType.RichSmooth);
        entity2.Translate(Axis.X * refCurve.Vertices[0].X, Axis.Y * refCurve.Vertices[0].Y, Axis.Z * refCurve.Vertices[0].Z);
        entity2.Regen(Regen);
        entity3 = (Entity) new Circle(plane, refPoint, radius2).ExtrudeAsMesh(Axis * 0.1, Regen, devDept.Eyeshot.Entities.Mesh.natureType.RichSmooth);
        entity3.Translate(Axis.X * refCurve.Vertices[refCurve.Vertices.Length - 1].X, Axis.Y * refCurve.Vertices[refCurve.Vertices.Length - 1].Y, Axis.Z * refCurve.Vertices[refCurve.Vertices.Length - 1].Z);
        entity3.Regen(Regen);
      }
      entRevolved = entity1;
      entTop = entity3;
      entBottom = entity2;
      return 1;
    }
    catch (Exception ex)
    {
      return -1;
    }
  }

