  public void GetSlicesContourFromMeshAtZPosition(
    Entity refMesh,
    double Z,
    bool Simplify,
    ref buEntitiesGroup EntGroup,
    double Deviation = 0.1)
  {
    if ((refMesh == null ? 0 : (refMesh is devDept.Eyeshot.Entities.Mesh ? 1 : 0)) == 0)
      return;
    devDept.Eyeshot.Entities.Mesh mesh = refMesh as devDept.Eyeshot.Entities.Mesh;
    if (mesh.BoxMin == (Point3D) null)
      mesh.Regen(Deviation);
    LinkedList<SharedEdge>[] edgesPerVertex;
    Utility.GetEdgesWithoutDuplicates((IList<IndexTriangle>) mesh.Triangles, mesh.Vertices.Length, out edgesPerVertex);
    Plane plane = new Plane(mesh.BoxMin, Vector3D.AxisX, Vector3D.AxisY);
    double num1 = new Size3D(mesh.BoxMax, mesh.BoxMax).Z / 100.0;
    double num2 = 0.0001 * (mesh.BoxMax.Z - mesh.BoxMin.Z) * num1;
    double deviation = 0.0001 * Point2D.Distance(new Point2D(mesh.BoxMin.X, mesh.BoxMin.Y), new Point2D(mesh.BoxMax.X, mesh.BoxMax.Y));
    List<ICurve> curveList = new List<ICurve>();
    ICurve[] curveArray;
    \u0007.\u0001.\u0001(num2, ref curveArray, edgesPerVertex, mesh, plane, this);
    foreach (ICurve curve in curveArray)
    {
      if (!Simplify)
      {
        curveList.Add(curve);
      }
      else
      {
        Point3D[] point3DArray = Utility.RemoveDuplicates<Point3D>((IList<Point3D>) Utility.Simplify<Point3D>((IList<Point3D>) ((Entity) curve).Vertices, deviation));
        curveList.Add((ICurve) new LinearPath(point3DArray));
      }
    }
  }

