  public void DimensionLinear(
    Point3D StartPoint,
    Point3D EndPoint,
    Point3D SetPoint,
    double dimtextH,
    ref buEntity StartPointExtension,
    ref buEntity EndPointExtension,
    ref buEntity DimLine)
  {
    bool flag = SetPoint.X > StartPoint.X && SetPoint.X > EndPoint.X || SetPoint.X < StartPoint.X && SetPoint.X < EndPoint.X;
    Point3D point3D1 = new Point3D();
    Point3D point3D2 = new Point3D();
    Point3D point3D3;
    Point3D end;
    if (flag)
    {
      point3D3 = new Point3D(SetPoint.X, StartPoint.Y);
      end = new Point3D(SetPoint.X, EndPoint.Y);
      if ((SetPoint.X <= StartPoint.X ? 0 : (SetPoint.X > EndPoint.X ? 1 : 0)) != 0)
      {
        point3D3.X += dimtextH / 2.0;
        end.X += dimtextH / 2.0;
      }
      else
      {
        point3D3.X -= dimtextH / 2.0;
        end.X -= dimtextH / 2.0;
      }
    }
    else
    {
      point3D3 = new Point3D(StartPoint.X, SetPoint.Y);
      end = new Point3D(EndPoint.X, SetPoint.Y);
      if ((SetPoint.Y <= StartPoint.Y ? 0 : (SetPoint.Y > EndPoint.Y ? 1 : 0)) != 0)
      {
