  public void CreateArrow(
    Point3D refPoint,
    double Width,
    double Height,
    double Angle,
    ref Entity entArrow,
    double Thickness = 0.1)
  {
    devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region((ICurve) new LinearPath((ICollection<Point3D>) new List<Point3D>()
    {
      new Point3D(0.0, 0.0, 0.0),
      new Point3D(-Width, Height / 2.0, 0.0),
      new Point3D(-Width, -Height / 2.0, 0.0),
      new Point3D(0.0, 0.0, 0.0)
    }), Plane.XY);
    entArrow = (Entity) region.ExtrudeAsMesh(Thickness, 0.1, devDept.Eyeshot.Entities.Mesh.natureType.RichSmooth);
    entArrow.Rotate(buString5.DegreeToRadian(Angle), Vector3D.AxisZ);
    entArrow.Translate(refPoint.X, refPoint.Y, refPoint.Z);
  }

  public double Length2D(double X1, double Y1, double X2, double Y2)
  {
    try
    {
      return Math.Sqrt((X1 - X2) * (X1 - X2) + (Y1 - Y2) * (Y1 - Y2));
    }
    catch (Exception ex)
    {
      string str = $"X1: {X1.ToString()} - X2: {X2.ToString()} - Y1: {Y1.ToString()} - Y2: {Y2.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

