  public double PolygonArea(List<Point3D> Vertices, Plane refPlane)
  {
    try
    {
      double num = 0.0;
      if (Vertices == null || Vertices.Count == 0)
        return 0.0;
      if (buVector5.isPlaneXYorYX(refPlane))
      {
        for (int index = 1; index <= Vertices.Count - 1; ++index)
          num += (Vertices[index].X - Vertices[index - 1].X) * (Vertices[index].Y + Vertices[index - 1].Y) / 2.0;
      }
      if (buVector5.isPlaneXZorZX(refPlane))
      {
        for (int index = 1; index <= Vertices.Count - 1; ++index)
          num += (Vertices[index].X - Vertices[index - 1].X) * (Vertices[index].Z + Vertices[index - 1].Z) / 2.0;
      }
      if (buVector5.isPlaneYZorZY(refPlane))
      {
        for (int index = 1; index <= Vertices.Count - 1; ++index)
          num += (Vertices[index].Y - Vertices[index - 1].Y) * (Vertices[index].Z + Vertices[index - 1].Z) / 2.0;
      }
      return Math.Abs(num);
    }
    catch (Exception ex)
    {
      string str = $"Vertices: {Vertices.Count.ToString()} - Plane: {refPlane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public void AreaUnitRatioFromMM(LengthUnit Unit, ref double UnitRatio)
  {
    switch (Unit)
    {
      case LengthUnit.mm:
        UnitRatio = 1.0;
        break;
      case LengthUnit.cm:
        UnitRatio = 100.0;
        break;
      case LengthUnit.dm:
        UnitRatio = 10000.0;
        break;
      case LengthUnit.m:
        UnitRatio = 1000000.0;
        break;
      case LengthUnit.dam:
        UnitRatio = 100000000.0;
        break;
      case LengthUnit.hm:
        UnitRatio = 10000000000.0;
        break;
      case LengthUnit.km:
        UnitRatio = 1000000000000.0;
        break;
    }
  }

  public void StepCalculation(double Start, double End, double Step, ref List<double> calcSteps)
  {
    calcSteps.Clear();
    if (buConversion5.EQ(Start, End))
      return;
    if (Math.Abs(Start - End) <= Step)
    {
      calcSteps.Add((Start + End) / 2.0);
    }
    else
    {
      int lower = (int) buFile5.RoundToLower(Math.Abs(Start - End) / Step);
      if (End > Start)
      {
        double num1 = Start;
        for (int index = 0; index <= lower - 1; ++index)
        {
          if (index == 0)
            num1 += Step / 2.0;
          else
            num1 += Step;
          calcSteps.Add(num1);
        }
        double num2 = End - Step;
        if (calcSteps.Count <= 0)
          return;
        if (num2 > calcSteps[calcSteps.Count - 1])
        {
          calcSteps.Add(num2);
        }
        else
        {
          double num3 = End - Step / 2.0;
          if (num3 <= calcSteps[calcSteps.Count - 1])
            return;
          calcSteps.Add(num3);
        }
      }
      else
      {
        double num4 = Start;
        for (int index = 0; index <= lower - 1; ++index)
        {
          if (index == 0)
            num4 -= Step / 2.0;
          else
            num4 -= Step;
          calcSteps.Add(num4);
        }
        double num5 = End + Step;
        if (calcSteps.Count <= 0)
          return;
        if (num5 < calcSteps[calcSteps.Count - 1])
        {
          calcSteps.Add(num5);
        }
        else
        {
          double num6 = End + Step / 2.0;
          if (num6 >= calcSteps[calcSteps.Count - 1])
            return;
          calcSteps.Add(num6);
        }
      }
    }
  }

