  public Point3D CalculateCentroid(List<Point3D> Vertices)
  {
    Point3D centroid;
    if (Vertices.Count == 0)
      centroid = new Point3D();
    else if (Vertices.Count == 1)
    {
      centroid = new Point3D(Vertices[0].X, Vertices[0].Y, Vertices[0].Z);
    }
    else
    {
      Vector3D vector3D = new Vector3D();
      double num1 = 0.0;
      Point3D vertex1 = Vertices[0];
      Point3D point3D1 = Vertices[1];
      for (int index = 2; index < Vertices.Count; ++index)
      {
        Point3D vertex2 = Vertices[index];
        double num2 = Vector3D.Cross(vertex2 - vertex1, vertex2 - point3D1).Length / 2.0;
        vector3D.X += num2 * (vertex1.X + point3D1.X + vertex2.X) / 3.0;
        vector3D.Y += num2 * (vertex1.Y + point3D1.Y + vertex2.Y) / 3.0;
        vector3D.Z += num2 * (vertex1.Z + point3D1.Z + vertex2.Z) / 3.0;
        num1 += num2;
        point3D1 = vertex2;
      }
      Point3D point3D2 = new Point3D();
      point3D2.X = vector3D.X / num1;
      point3D2.Y = vector3D.Y / num1;
      point3D2.Z = vector3D.Z / num1;
      centroid = point3D2;
    }
    return centroid;
  }

  public Point3D CalculateMassCenterFromVertices(List<Point3D> Vertices)
  {
    Point3D centerFromVertices;
    if (Vertices.Count == 0)
      centerFromVertices = new Point3D();
    else if (Vertices.Count == 1)
    {
      centerFromVertices = new Point3D(Vertices[0].X, Vertices[0].Y, Vertices[0].Z);
    }
    else
    {
      double num1 = 0.0;
      double num2 = 0.0;
      double num3 = 0.0;
      for (int index = 0; index <= Vertices.Count - 1; ++index)
      {
        num1 += Vertices[index].X;
        num2 += Vertices[index].Y;
        num3 += Vertices[index].Z;
      }
      centerFromVertices = new Point3D(num1 / (double) Vertices.Count, num2 / (double) Vertices.Count, num3 / (double) Vertices.Count);
    }
    return centerFromVertices;
  }

  public Point3D CalculateMassCenterFromEdges(List<Point3D> Vertices)
  {
    Point3D massCenterFromEdges;
    if (Vertices.Count == 0)
      massCenterFromEdges = new Point3D();
    else if (Vertices.Count == 1)
    {
      massCenterFromEdges = new Point3D(Vertices[0].X, Vertices[0].Y, Vertices[0].Z);
    }
    else
    {
      double num1 = 0.0;
      double num2 = 0.0;
      double num3 = 0.0;
      double num4 = 0.0;
      double num5 = Vertices[0].X;
      double num6 = Vertices[0].Y;
      double num7 = Vertices[0].Z;
      for (int index = 1; index <= Vertices.Count - 1; ++index)
      {
        double x = Vertices[index].X;
        double y = Vertices[index].Y;
        double z = Vertices[index].Z;
        double num8 = x - num5;
        double num9 = y - num6;
        double num10 = z - num7;
        double num11 = Math.Sqrt(num8 * num8 + num9 * num9 + num10 * num10);
        num1 += (num5 + x) / 2.0 * num11;
        num2 += (num6 + y) / 2.0 * num11;
        num3 += (num7 + z) / 2.0 * num11;
        num4 += num11;
        num5 = x;
        num6 = y;
        num7 = z;
      }
      massCenterFromEdges = new Point3D(num1 / num4, num2 / num4, num3 / num4);
    }
    return massCenterFromEdges;
  }

