  public void DevidePointList(List<Pnt6D> Points, double Length, ref List<Pnt6D> Vertices)
  {
    try
    {
      Vertices.Clear();
      if (Length <= 0.0 || Points.Count <= 1)
        return;
      for (int index = 1; index <= Points.Count - 1; ++index)
      {
        List<Pnt6D> Vertices1 = new List<Pnt6D>();
        ((MachineAxisInfo) this).LineToLineer(Points[index - 1], Points[index], Length, ref Vertices1);
        if (Vertices1.Count > 1)
          Pnt6D.Add(Vertices1, ref Vertices);
        if (index < Points.Count - 1 && Vertices.Count > 0)
          Vertices.RemoveAt(Vertices.Count - 1);
      }
      ((F_CutterMachineSettings) this).CheckDuplicatedPointsWithPrevious(ref Vertices);
    }
    catch (Exception ex)
    {
      string str = "Len:" + Length.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

