  public void DevidePointListAngleAndLength(
    List<Pnt6DS> Points,
    double XYZLength,
    double ABCLength,
    ref List<Pnt6DS> Vertices)
  {
    try
    {
      Vertices.Clear();
      if (XYZLength <= 0.0 || ABCLength <= 0.0 || Points.Count <= 1)
        return;
      Vertices.Add(new Pnt6DS(Points[0]));
      for (int index1 = 1; index1 <= Points.Count - 1; ++index1)
      {
        this.Length6D(new Pnt6D(Points[index1 - 1]), new Pnt6D(Points[index1]));
        double num1 = this.Length3D(new Pnt3D(Points[index1 - 1].X, Points[index1 - 1].Y, Points[index1 - 1].Z), new Pnt3D(Points[index1].X, Points[index1].Y, Points[index1].Z));
        double num2 = this.Length3D(new Pnt3D(Points[index1 - 1].A, Points[index1 - 1].B, Points[index1 - 1].C), new Pnt3D(Points[index1].A, Points[index1].B, Points[index1].C));
        int upper1 = (int) buFile5.RoundToUpper(num1 / XYZLength);
        int upper2 = (int) buFile5.RoundToUpper(num2 / ABCLength);
        if (upper2 > upper1)
        {
          if (upper2 > 2)
          {
            List<Point3D> Values1 = new List<Point3D>();
            List<Point3D> Values2 = new List<Point3D>();
            buFile5.DevideMinMaxValueByNumber(new Point3D(Points[index1 - 1].X, Points[index1 - 1].Y, Points[index1 - 1].Z), new Point3D(Points[index1].X, Points[index1].Y, Points[index1].Z), upper2, ref Values1);
            buFile5.DevideMinMaxValueByNumber(new Point3D(Points[index1 - 1].A, Points[index1 - 1].B, Points[index1 - 1].C), new Point3D(Points[index1].A, Points[index1].B, Points[index1].C), upper2, ref Values2);
            if (Values1.Count == Values2.Count)
            {
              for (int index2 = 1; index2 <= Values1.Count - 1; ++index2)
                Vertices.Add(new Pnt6DS(Values1[index2].X, Values1[index2].Y, Values1[index2].Z, Values2[index2].X, Values2[index2].Y, Values2[index2].Z, Points[index1].S));
            }
            else
              Vertices.Add(new Pnt6DS(Points[index1]));
          }
          else
            Vertices.Add(new Pnt6DS(Points[index1]));
        }
        else if (upper1 > 2)
        {
          List<Point3D> Values3 = new List<Point3D>();
          List<Point3D> Values4 = new List<Point3D>();
          buFile5.DevideMinMaxValueByNumber(new Point3D(Points[index1 - 1].X, Points[index1 - 1].Y, Points[index1 - 1].Z), new Point3D(Points[index1].X, Points[index1].Y, Points[index1].Z), upper1, ref Values3);
          buFile5.DevideMinMaxValueByNumber(new Point3D(Points[index1 - 1].A, Points[index1 - 1].B, Points[index1 - 1].C), new Point3D(Points[index1].A, Points[index1].B, Points[index1].C), upper1, ref Values4);
          if (Values3.Count == Values4.Count)
          {
            for (int index3 = 1; index3 <= Values3.Count - 1; ++index3)
              Vertices.Add(new Pnt6DS(Values3[index3].X, Values3[index3].Y, Values3[index3].Z, Values4[index3].X, Values4[index3].Y, Values4[index3].Z, Points[index1].S));
          }
          else
            Vertices.Add(new Pnt6DS(Points[index1]));
        }
        else
          Vertices.Add(new Pnt6DS(Points[index1]));
      }
    }
    catch (Exception ex)
    {
      string str = "Len:" + XYZLength.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public int DevidePointList(
    List<Point3D> refPoints,
    double DevideLength,
    double StartLength,
    double EndLength,
    bool DevideMiddlePoints,
    DevideTipType DevidePoint,
    ref List<Point3D> calcStartPoints,
    ref List<Point3D> calcMiddlePoints,
    ref List<Point3D> calcEndPoints)
  {
    try
    {
      double num1 = 0.0;
      double num2 = 0.0;
      bool flag1 = false;
      bool flag2 = false;
      bool flag3 = false;
      calcStartPoints.Clear();
      calcMiddlePoints.Clear();
      calcEndPoints.Clear();
      double num3 = this.Length3D(refPoints);
      if (refPoints.Count <= 1)
        return 0;
      if (num3 < StartLength + EndLength)
      {
        buVector5.Copy(refPoints, ref calcMiddlePoints);
        return 1;
      }
      calcStartPoints.Add(F_NotchEdit.ToPoint3D(refPoints[0]));
      for (int index = 1; index <= refPoints.Count - 1; ++index)
      {
        double num4 = this.Length3D(refPoints[index - 1], refPoints[index]);
        num1 += num4;
        double num5 = num3 - num1;
        if (!flag1 & num1 > StartLength)
        {
          double Angle = this.PointAngle(new Point3D(refPoints[index].X, refPoints[index].Y), new Point3D(refPoints[index - 1].X, refPoints[index - 1].Y));
          Point3D EndPnt = new Point3D();
          if (StartLength - num2 > 0.1)
          {
            this.LineWithLengthAndAngle(new Point3D(refPoints[index - 1].X, refPoints[index - 1].Y), StartLength - num2, Angle, Plane.XY, ref EndPnt);
            calcStartPoints.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
            calcMiddlePoints.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
          }
          flag1 = true;
        }
        if (!flag1 && !flag1)
          calcStartPoints.Add(F_NotchEdit.ToPoint3D(refPoints[index]));
        if (num5 < EndLength & !flag3)
        {
          double Angle = this.PointAngle(refPoints[index - 1], refPoints[index]);
          Point3D EndPnt = new Point3D();
          this.LineWithLengthAndAngle(new Point3D(refPoints[index].X, refPoints[index].Y), EndLength - num5, Angle, Plane.XY, ref EndPnt);
          calcEndPoints.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
          if (!flag3)
            calcMiddlePoints.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
          flag3 = true;
          flag2 = true;
        }
        if (!flag2 & flag1 & !flag3)
          calcMiddlePoints.Add(F_NotchEdit.ToPoint3D(refPoints[index]));
        if (calcEndPoints.Count > 0)
          calcEndPoints.Add(F_NotchEdit.ToPoint3D(refPoints[index]));
        num2 = num1;
      }
      this.DevidePointsByLength(ref calcStartPoints, DevideLength);
      this.DevidePointsByLength(ref calcEndPoints, DevideLength);
      if (DevideMiddlePoints)
        this.DevidePointsByLength(ref calcMiddlePoints, DevideLength);
      return 2;
    }
    catch (Exception ex)
    {
      string str = $"DevideLength: {DevideLength.ToString()} - StartLength: {StartLength.ToString()} - EndLength: {EndLength.ToString()} - DevidePoint: {DevidePoint.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return -1;
    }
  }

  public void CoordinateFromPlaneAndCorner(
    SizeObject Size,
    CornerLocation Corner,
    planeBoxNames Plane,
    ref buShape Item,
    ref Point3D calcPoint,
    double SingX = 1.0,
    double SingY = 1.0)
  {
    Point3D point3D = new Point3D(((buClipper) Item).BasePoint.X, ((buClipper) Item).BasePoint.Y, ((buClipper) Item).BasePoint.Z);
    ((buClipperBase) Item).Corner = Corner;
    if (Plane == planeBoxNames.Top | Plane == planeBoxNames.Bottom | Plane == planeBoxNames.Free)
    {
      double num = Size.Depth;
      ((buClipper) Item).CornerPoint = new Point3D(0.0, 0.0, Size.Depth);
      if (Plane == planeBoxNames.Bottom)
      {
        num = 0.0;
        ((buClipper) Item).CornerPoint = new Point3D(0.0, 0.0, 0.0);
      }
      if (Corner == CornerLocation.RightTop | Corner == CornerLocation.RightCenter | Corner == CornerLocation.RightBottom)
      {
        if (SingX > 0.0)
          ((buClipper) Item).CornerPoint.X = Size.Width;
        else
          ((buClipper) Item).CornerPoint.X = 0.0;
      }
      if (Corner == CornerLocation.LeftBottom | Corner == CornerLocation.LeftCenter | Corner == CornerLocation.LeftTop)
      {
        if (SingX > 0.0)
          ((buClipper) Item).CornerPoint.X = 0.0;
        else
          ((buClipper) Item).CornerPoint.X = -Size.Width;
      }
      if (Corner == CornerLocation.TopCenter | Corner == CornerLocation.LeftTop | Corner == CornerLocation.RightTop)
      {
        if (SingY > 0.0)
          ((buClipper) Item).CornerPoint.Y = Size.Height;
        else
          ((buClipper) Item).CornerPoint.Y = 0.0;
      }
      if (Corner == CornerLocation.BottomCenter | Corner == CornerLocation.LeftBottom | Corner == CornerLocation.RightBottom)
      {
        if (SingY > 0.0)
          ((buClipper) Item).CornerPoint.Y = 0.0;
        else
          ((buClipper) Item).CornerPoint.Y = -Size.Height;
      }
      if (Corner == CornerLocation.RightCenter | Corner == CornerLocation.LeftCenter)
      {
        if (SingY > 0.0)
          ((buClipper) Item).CornerPoint.Y = Size.Height / 2.0;
        else
          ((buClipper) Item).CornerPoint.Y = -Size.Height / 2.0;
      }
      if (Corner == CornerLocation.BottomCenter | Corner == CornerLocation.BottomCenter)
      {
        if (SingX > 0.0)
          ((buClipper) Item).CornerPoint.X = Size.Width / 2.0;
        else
          ((buClipper) Item).CornerPoint.X = -Size.Width / 2.0;
      }
      if (Corner == CornerLocation.RightTop)
      {
        calcPoint.X = Size.Width - point3D.X;
        calcPoint.Y = Size.Height - point3D.Y;
        calcPoint.Z = num;
      }
      if (Corner == CornerLocation.RightBottom)
      {
        calcPoint.X = Size.Width - point3D.X;
        calcPoint.Y = point3D.Y;
        calcPoint.Z = num;
      }
      if (Corner == CornerLocation.RightCenter)
      {
        calcPoint.X = Size.Width - point3D.X;
        calcPoint.Y = Size.Height / 2.0 + point3D.Y;
        calcPoint.Z = num;
      }
      if (Corner == CornerLocation.LeftTop)
      {
        calcPoint.X = point3D.X;
        calcPoint.Y = Size.Height - point3D.Y;
        calcPoint.Z = num;
      }
      if (Corner == CornerLocation.LeftBottom)
      {
        calcPoint.X = point3D.X;
        calcPoint.Y = point3D.Y;
        calcPoint.Z = num;
      }
      if (Corner == CornerLocation.LeftCenter)
      {
        calcPoint.X = point3D.X;
        calcPoint.Y = Size.Height / 2.0 + point3D.Y;
        calcPoint.Z = num;
      }
      if (Corner == CornerLocation.BottomCenter)
      {
        calcPoint.X = Size.Width / 2.0 + point3D.X;
        calcPoint.Y = point3D.Y;
        calcPoint.Z = num;
      }
      if (Corner == CornerLocation.TopCenter)
      {
        calcPoint.X = Size.Width / 2.0 + point3D.X;
        calcPoint.Y = Size.Height - point3D.Y;
        calcPoint.Z = num;
      }
    }
    if (Plane == planeBoxNames.Right | Plane == planeBoxNames.Left)
