  public void GetDirectionVectorFromCornerAndPlane(ref buShape Item)
  {
    if (((buClipperBase) Item).planeName == planeBoxNames.Top)
    {
      if (((buClipperBase) Item).Corner == CornerLocation.LeftBottom)
        ((buClipper) Item).CornerDirection = new Vector3D(1.0, 1.0, 1.0);
      if (((buClipperBase) Item).Corner == CornerLocation.LeftTop)
        ((buClipper) Item).CornerDirection = new Vector3D(1.0, -1.0, 1.0);
      if (((buClipperBase) Item).Corner == CornerLocation.RightBottom)
        ((buClipper) Item).CornerDirection = new Vector3D(-1.0, 1.0, 1.0);
      if (((buClipperBase) Item).Corner == CornerLocation.RightTop)
        ((buClipper) Item).CornerDirection = new Vector3D(-1.0, -1.0, 1.0);
      if (((buClipperBase) Item).Corner == CornerLocation.LeftCenter)
        ((buClipper) Item).CornerDirection = new Vector3D(1.0, 1.0, 1.0);
      if (((buClipperBase) Item).Corner == CornerLocation.RightCenter)
        ((buClipper) Item).CornerDirection = new Vector3D(-1.0, 1.0, 1.0);
      if (((buClipperBase) Item).Corner == CornerLocation.TopCenter)
        ((buClipper) Item).CornerDirection = new Vector3D(1.0, -1.0, 1.0);
      if (((buClipperBase) Item).Corner == CornerLocation.BottomCenter)
        ((buClipper) Item).CornerDirection = new Vector3D(1.0, 1.0, 1.0);
    }
    if (((buClipperBase) Item).planeName == planeBoxNames.Bottom)
    {
      if (((buClipperBase) Item).Corner == CornerLocation.LeftBottom)
        ((buClipper) Item).CornerDirection = new Vector3D(1.0, 1.0, -1.0);
      if (((buClipperBase) Item).Corner == CornerLocation.LeftTop)
