  public void XYFromZ(Point3D StartPoint, Point3D EndPoint, double ZValue, ref Point3D CalcPoint)
  {
    try
    {
      double num1 = StartPoint.X - EndPoint.X;
      double num2 = StartPoint.Y - EndPoint.Y;
      double num3 = StartPoint.Z - EndPoint.Z;
      double num4 = StartPoint.Z - ZValue;
      if (num3 != 0.0)
      {
        double num5 = num4 / num3;
        CalcPoint = new Point3D(StartPoint.X - num1 * num5, StartPoint.Y - num2 * num5, ZValue);
      }
      else
        CalcPoint = new Point3D(StartPoint.X, StartPoint.Y, StartPoint.Z);
    }
    catch (Exception ex)
    {
      string str = $"StartPoint: {StartPoint.ToString()} - EndPoint: {EndPoint.ToString()} - ZValue: {ZValue.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void CircularZHeightRampByLengthAndHeight(
    double Length,
    double ZUp,
    double ZDown,
    double ArcRatio,
    int Count,
    ref List<double> Heights,
    ref List<Point3D> Points)
  {
    List<Point3D> refPoint = new List<Point3D>();
    Point3D ArcCenter = new Point3D();
    double ArcSA = 0.0;
    double ArcEA = 0.0;
    Point3D point3D = new Point3D(0.0, ZUp, 0.0);
    Point3D ArcEndPoint = new Point3D(Length, ZDown, 0.0);
    if (ZDown > ZUp)
    {
      point3D = new Point3D(0.0, ZDown, 0.0);
      ArcEndPoint = new Point3D(Length, ZUp, 0.0);
    }
    double Radius = Length / ArcRatio;
    for (double num1 = 1.0; num1 <= 1000.0; num1 += 0.5)
    {
      double num2 = this.Length3D(new Point3D(ArcEndPoint.X, ArcEndPoint.Y + num1), point3D);
      Math.Abs(num2 - num1);
      if (buConversion5.EQ(num2, num1, 1.0))
      {
        Radius = num2;
        num1 = 1000.0;
      }
    }
    this.ArcWithTwoPointAndRadius(point3D, ArcEndPoint, Radius, false, Plane.XY, ref ArcCenter, ref ArcSA, ref ArcEA);
    this.ArcWithCenter(ArcCenter, Radius, ArcSA, ArcEA, Plane.XY, new EntityResolution(1.0, Count - 1, 10.0, EntityResolutionType.ByNumber), ref refPoint);
    this.RotateByMatrix(new Point3D(), 90.0, VectorType.XVector, ref refPoint);
    if (ZUp > ZDown)
    {
      if (refPoint[0].Z < refPoint[refPoint.Count - 1].Z)
        refPoint.Reverse();
    }
    else if (refPoint[0].Z > refPoint[refPoint.Count - 1].Z)
      refPoint.Reverse();
    for (int index = 0; index <= refPoint.Count - 1; ++index)
      Heights.Add(refPoint[index].Z);
    Points.Clear();
    buVector5.Copy(refPoint, ref Points);
  }

  public bool isEntityEntityBoxBoundingIntersect(Entity entFirst, Entity entSecond)
  {
    try
    {
      if (!(entFirst.BoxMax != (Point3D) null & entSecond.BoxMax != (Point3D) null))
        return false;
      Size3D intersectionBox = (Size3D) null;
      return Utility.DoOverlapOrTouchWithIntersectionBox(entFirst.BoxMin, entFirst.BoxMax, entSecond.BoxMin, entSecond.BoxMax, out intersectionBox);
    }
    catch (Exception ex)
    {
      string str = "isEntityEntityBoxBoundingIntersect: ";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return false;
    }
  }

  public void PointConversionByPlane(
    Plane FromPlane,
    Plane ToPlane,
    Point3D RefPoint,
    ref Point3D CalcPoint)
  {
    try
    {
      if (buVector5.isPlaneXYorYX(FromPlane))
      {
        if (buVector5.isPlaneXYorYX(ToPlane))
        {
          CalcPoint.X = RefPoint.X;
          CalcPoint.Y = RefPoint.Y;
          CalcPoint.Z = RefPoint.Z;
        }
        if (buVector5.isPlaneXZorZX(ToPlane))
        {
          CalcPoint.X = RefPoint.X;
          CalcPoint.Z = RefPoint.Y;
          CalcPoint.Y = RefPoint.Z;
        }
        if (buVector5.isPlaneYZorZY(ToPlane))
        {
          CalcPoint.Y = RefPoint.X;
          CalcPoint.Z = RefPoint.Y;
          CalcPoint.X = RefPoint.Z;
        }
      }
      if (buVector5.isPlaneXZorZX(FromPlane))
      {
        if (buVector5.isPlaneXYorYX(ToPlane))
        {
          CalcPoint.X = RefPoint.X;
          CalcPoint.Z = RefPoint.Y;
          CalcPoint.Y = RefPoint.Z;
        }
        if (buVector5.isPlaneXZorZX(ToPlane))
        {
          CalcPoint.X = RefPoint.X;
          CalcPoint.Y = RefPoint.Y;
          CalcPoint.Z = RefPoint.Z;
        }
        if (buVector5.isPlaneYZorZY(ToPlane))
        {
          CalcPoint.Y = RefPoint.X;
          CalcPoint.X = RefPoint.Y;
          CalcPoint.Z = RefPoint.Z;
        }
      }
      if (!buVector5.isPlaneYZorZY(FromPlane))
        return;
      if (buVector5.isPlaneYZorZY(ToPlane))
      {
        CalcPoint.X = RefPoint.X;
        CalcPoint.Y = RefPoint.Y;
        CalcPoint.Z = RefPoint.Z;
      }
      if (buVector5.isPlaneXYorYX(ToPlane))
      {
        CalcPoint.Z = RefPoint.X;
        CalcPoint.X = RefPoint.Y;
        CalcPoint.Y = RefPoint.Z;
      }
      if (!buVector5.isPlaneXZorZX(ToPlane))
        return;
      CalcPoint.Y = RefPoint.X;
      CalcPoint.X = RefPoint.Y;
      CalcPoint.Z = RefPoint.Z;
    }
    catch (Exception ex)
    {
      string str = $"FromPlane: {FromPlane.ToString()} - ToPlane: {ToPlane.ToString()} - RefPoint: {RefPoint.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void PointConversionByPlane(
    Plane FromPlane,
    Plane ToPlane,
    List<Point3D> RefPoint,
    ref List<Point3D> CalcPoint)
  {
