  public void ShiftPointsByLength(
    Point3D FirstRefPoints,
    Point3D SecondRefPoints,
    ref List<Point3D> Points)
  {
    this.ShiftPointsByLength(FirstRefPoints, SecondRefPoints, false, ref Points);
  }

  public void ShiftPointsByLength(
    Point3D FirstRefPoints,
    Point3D SecondRefPoints,
    bool OnlyXYPlane,
    ref List<Point3D> Points)
  {
    double num1 = double.MaxValue;
    int num2 = 0;
    for (int index = 0; index <= Points.Count - 1; ++index)
    {
      double num3 = this.Length3D(FirstRefPoints, Points[index]);
      if (OnlyXYPlane)
        num3 = this.Length3D(FirstRefPoints, Points[index], Plane.XY);
      if (num3 < num1)
      {
        num2 = index;
        num1 = num3;
      }
    }
    for (int index = 0; index <= Points.Count - 1; ++index)
    {
      double num4 = this.Length3D(SecondRefPoints, Points[index]);
      if (OnlyXYPlane)
        num4 = this.Length3D(SecondRefPoints, Points[index], Plane.XY);
      if (num4 < num1)
        num1 = num4;
    }
    if (num2 <= 0)
      return;
    List<Point3D> copiedPoint = new List<Point3D>();
    buVector5.Copy(Points, ref copiedPoint);
    Points.Clear();
    for (int index = num2; index <= copiedPoint.Count - 1; ++index)
      Points.Add(F_NotchEdit.ToPoint3D(copiedPoint[index]));
    for (int index = 0; index < num2; ++index)
    {
      if (index == 0)
      {
        if (!buConversion5.EQ(Points[Points.Count - 1], copiedPoint[index]))
          Points.Add(F_NotchEdit.ToPoint3D(copiedPoint[index]));
      }
      else
        Points.Add(F_NotchEdit.ToPoint3D(copiedPoint[index]));
    }
  }

  public void ShiftPointsByLength(Point3D RefPoints, ref List<Point3D> Points, bool OnlyXY = false)
  {
    double num1 = double.MaxValue;
    int num2 = 0;
    bool flag = ((F_AnalyseResult) this).IsClosed(Points);
    for (int index = 0; index <= Points.Count - 1; ++index)
    {
      double num3 = OnlyXY ? this.Length3D(RefPoints, Points[index], Plane.XY) : this.Length3D(RefPoints, Points[index]);
      if (num3 < num1)
      {
        num2 = index;
        num1 = num3;
      }
    }
    if (num2 > 0)
    {
      List<Point3D> copiedPoint = new List<Point3D>();
      buVector5.Copy(Points, ref copiedPoint);
      Points.Clear();
      for (int index = num2; index <= copiedPoint.Count - 1; ++index)
        Points.Add(F_NotchEdit.ToPoint3D(copiedPoint[index]));
      for (int index = 0; index < num2; ++index)
      {
        if (index == 0)
        {
          if (!buConversion5.EQ(Points[Points.Count - 1], copiedPoint[index]))
            Points.Add(F_NotchEdit.ToPoint3D(copiedPoint[index]));
        }
        else
          Points.Add(F_NotchEdit.ToPoint3D(copiedPoint[index]));
      }
    }
    if (!(flag & Points.Count > 2) || !(Points[0] != Points[Points.Count - 1]))
      return;
    Points.Add(F_NotchEdit.ToPoint3D(Points[0]));
  }

  public void ShiftList(ref List<Point3D> List, int ShiftValue)
  {
    if (ShiftValue == 0 || ShiftValue >= List.Count)
      return;
    if (ShiftValue < 0)
    {
      List<Point3D> copiedPoint = new List<Point3D>();
      buVector5.Copy(List, ref copiedPoint);
      List.Clear();
      for (int index = Math.Abs(ShiftValue); index <= copiedPoint.Count - 1; ++index)
        List.Add(F_NotchEdit.ToPoint3D(copiedPoint[index]));
      for (int index = 0; index < Math.Abs(ShiftValue); ++index)
        List.Add(F_NotchEdit.ToPoint3D(copiedPoint[index]));
    }
    if (ShiftValue <= 0)
      return;
    List<Point3D> copiedPoint1 = new List<Point3D>();
    buVector5.Copy(List, ref copiedPoint1);
    List.Clear();
    for (int index = copiedPoint1.Count - Math.Abs(ShiftValue) - 1; index <= copiedPoint1.Count - 1; ++index)
      List.Add(F_NotchEdit.ToPoint3D(copiedPoint1[index]));
    for (int index = 0; index < copiedPoint1.Count - Math.Abs(ShiftValue) - 1; ++index)
      List.Add(F_NotchEdit.ToPoint3D(copiedPoint1[index]));
  }

  public static void OffsetPoint3D(
    ref List<Point3D> pnt,
    double offsetX,
    double offsetY,
    double offsetZ)
  {
    for (int index = 0; index < pnt.Count; ++index)
      pnt[index] = new Point3D(pnt[index].X + offsetX, pnt[index].Y + offsetY, pnt[index].Z + offsetZ);
  }

  public static void OffsetPoint3D(
    ref Point3D[] pnt,
    double offsetX,
    double offsetY,
    double offsetZ)
  {
    for (int index = 0; index < pnt.Length; ++index)
      pnt[index] = new Point3D(pnt[index].X + offsetX, pnt[index].Y + offsetY, pnt[index].Z + offsetZ);
  }

  public static void OffsetPoint3D(
    ref Point3D pnt,
    double offsetX,
    double offsetY,
    double offsetZ)
  {
    pnt = new Point3D(pnt.X + offsetX, pnt.Y + offsetY, pnt.Z + offsetZ);
  }

  public Pnt3D SnapFunction(Point3D Base, Vec3D SnapDistances, Plane RefPlane)
  {
    try
    {
      Pnt3D pnt3D = new Pnt3D();
      if (buVector5.isPlaneXYorYX(RefPlane))
      {
        pnt3D.X = Math.Round(Base.X / SnapDistances.X) * SnapDistances.X;
        pnt3D.Y = Math.Round(Base.Y / SnapDistances.Y) * SnapDistances.Y;
        pnt3D.Z = 0.0;
      }
      if (buVector5.isPlaneXZorZX(RefPlane))
      {
        pnt3D.X = Math.Round(Base.X / SnapDistances.X) * SnapDistances.X;
        pnt3D.Y = 0.0;
        pnt3D.Z = Math.Round(Base.Z / SnapDistances.Z) * SnapDistances.Z;
      }
      if (buVector5.isPlaneYZorZY(RefPlane))
      {
        pnt3D.X = 0.0;
        pnt3D.Y = Math.Round(Base.Y / SnapDistances.Y) * SnapDistances.Y;
        pnt3D.Z = Math.Round(Base.Z / SnapDistances.Z) * SnapDistances.Z;
      }
      return pnt3D;
    }
    catch (Exception ex)
    {
      string str = $"Base: {Base.ToString()} - SnapDistances: {SnapDistances.ToString()} - Plane: {RefPlane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return new Pnt3D();
    }
  }

  public void OrthoFunction(
    Point3D RefPnt,
    Point3D CenterPnt,
    Plane RefPlane,
    ref Point3D OrthoPnt,
    ref int OrthoDir)
  {
    try
    {
      Pnt3D pnt3D = new Pnt3D();
      if ((!(RefPnt != (Point3D) null) ? 0 : (CenterPnt != (Point3D) null ? 1 : 0)) == 0)
        return;
      if (buVector5.isPlaneXYorYX(RefPlane))
      {
        pnt3D.X = CenterPnt.X;
        pnt3D.Y = CenterPnt.Y;
        if (RefPnt.X - pnt3D.X != 0.0)
        {
          OrthoPnt.X = RefPnt.X;
          OrthoPnt.Y = RefPnt.Y;
          double num = (RefPnt.Y - pnt3D.Y) / (RefPnt.X - pnt3D.X);
          if (RefPnt.X > pnt3D.X & RefPnt.Y > pnt3D.Y & num > 1.0)
          {
            OrthoPnt.X = pnt3D.X;
            OrthoPnt.Y = RefPnt.Y;
            OrthoDir = 2;
          }
          if (RefPnt.X > pnt3D.X & RefPnt.Y > pnt3D.Y & num < 1.0)
          {
            OrthoPnt.X = RefPnt.X;
            OrthoPnt.Y = pnt3D.Y;
            OrthoDir = 1;
          }
          if (RefPnt.X > pnt3D.X & RefPnt.Y < pnt3D.Y & num < -1.0)
          {
            OrthoPnt.X = pnt3D.X;
            OrthoPnt.Y = RefPnt.Y;
            OrthoDir = 4;
          }
          if (RefPnt.X > pnt3D.X & RefPnt.Y < pnt3D.Y & num > -1.0)
          {
            OrthoPnt.X = RefPnt.X;
            OrthoPnt.Y = pnt3D.Y;
            OrthoDir = 1;
          }
          if (RefPnt.X < pnt3D.X & RefPnt.Y < pnt3D.Y & num > 1.0)
          {
            OrthoPnt.X = pnt3D.X;
            OrthoPnt.Y = RefPnt.Y;
            OrthoDir = 4;
          }
          if (RefPnt.X < pnt3D.X & RefPnt.Y < pnt3D.Y & num < 1.0)
          {
            OrthoPnt.X = RefPnt.X;
            OrthoPnt.Y = pnt3D.Y;
            OrthoDir = 3;
          }
          if (RefPnt.X < pnt3D.X & RefPnt.Y > pnt3D.Y & num < -1.0)
          {
            OrthoPnt.X = pnt3D.X;
            OrthoPnt.Y = RefPnt.Y;
            OrthoDir = 2;
          }
          if (RefPnt.X < pnt3D.X & RefPnt.Y > pnt3D.Y & num > -1.0)
          {
            OrthoPnt.X = RefPnt.X;
            OrthoPnt.Y = pnt3D.Y;
            OrthoDir = 3;
          }
        }
        else
        {
          OrthoPnt.X = RefPnt.X;
          OrthoPnt.Y = RefPnt.Y;
        }
      }
      if (buVector5.isPlaneXZorZX(RefPlane))
      {
        pnt3D.X = CenterPnt.X;
        pnt3D.Z = CenterPnt.Z;
        if (RefPnt.X - pnt3D.X != 0.0)
        {
          OrthoPnt.X = RefPnt.X;
          OrthoPnt.Z = RefPnt.Z;
          double num = (RefPnt.Z - pnt3D.Z) / (RefPnt.X - pnt3D.X);
          if (RefPnt.X > pnt3D.X & RefPnt.Z > pnt3D.Z & num > 1.0)
          {
            OrthoPnt.X = pnt3D.X;
            OrthoPnt.Z = RefPnt.Z;
            OrthoDir = 2;
          }
          if (RefPnt.X > pnt3D.X & RefPnt.Z > pnt3D.Z & num < 1.0)
          {
            OrthoPnt.X = RefPnt.X;
            OrthoPnt.Z = pnt3D.Z;
            OrthoDir = 1;
          }
          if (RefPnt.X > pnt3D.X & RefPnt.Z < pnt3D.Z & num < -1.0)
          {
            OrthoPnt.X = pnt3D.X;
            OrthoPnt.Z = RefPnt.Z;
            OrthoDir = 4;
          }
          if (RefPnt.X > pnt3D.X & RefPnt.Z < pnt3D.Z & num > -1.0)
          {
            OrthoPnt.X = RefPnt.X;
            OrthoPnt.Z = pnt3D.Z;
            OrthoDir = 1;
          }
          if (RefPnt.X < pnt3D.X & RefPnt.Z < pnt3D.Z & num > 1.0)
          {
            OrthoPnt.X = pnt3D.X;
            OrthoPnt.Z = RefPnt.Z;
            OrthoDir = 4;
          }
          if (RefPnt.X < pnt3D.X & RefPnt.Z < pnt3D.Z & num < 1.0)
          {
            OrthoPnt.X = RefPnt.X;
            OrthoPnt.Z = pnt3D.Z;
            OrthoDir = 3;
          }
          if (RefPnt.X < pnt3D.X & RefPnt.Z > pnt3D.Z & num < -1.0)
          {
            OrthoPnt.X = pnt3D.X;
            OrthoPnt.Z = RefPnt.Z;
            OrthoDir = 2;
          }
          if (RefPnt.X < pnt3D.X & RefPnt.Z > pnt3D.Z & num > -1.0)
          {
            OrthoPnt.X = RefPnt.X;
            OrthoPnt.Z = pnt3D.Z;
            OrthoDir = 3;
          }
        }
        else
        {
          OrthoPnt.X = RefPnt.X;
          OrthoPnt.Z = RefPnt.Z;
        }
      }
      if (!buVector5.isPlaneYZorZY(RefPlane))
        return;
      pnt3D.Y = CenterPnt.Y;
      pnt3D.Z = CenterPnt.Z;
      if (RefPnt.Y - pnt3D.Y != 0.0)
      {
        OrthoPnt.Y = RefPnt.Y;
        OrthoPnt.Z = RefPnt.Z;
        double num = (RefPnt.Z - pnt3D.Z) / (RefPnt.Y - pnt3D.Y);
        if (RefPnt.Y > pnt3D.Y & RefPnt.Z > pnt3D.Z & num > 1.0)
        {
          OrthoPnt.Y = pnt3D.Y;
          OrthoPnt.Z = RefPnt.Z;
          OrthoDir = 2;
        }
        if (RefPnt.Y > pnt3D.Y & RefPnt.Z > pnt3D.Z & num < 1.0)
        {
          OrthoPnt.Y = RefPnt.Y;
          OrthoPnt.Z = pnt3D.Z;
          OrthoDir = 1;
        }
        if (RefPnt.Y > pnt3D.Y & RefPnt.Z < pnt3D.Z & num < -1.0)
        {
          OrthoPnt.Y = pnt3D.Y;
          OrthoPnt.Z = RefPnt.Z;
          OrthoDir = 4;
        }
        if (RefPnt.Y > pnt3D.Y & RefPnt.Z < pnt3D.Z & num > -1.0)
        {
          OrthoPnt.Y = RefPnt.Y;
          OrthoPnt.Z = pnt3D.Z;
          OrthoDir = 1;
        }
        if (RefPnt.Y < pnt3D.Y & RefPnt.Z < pnt3D.Z & num > 1.0)
        {
          OrthoPnt.Y = pnt3D.Y;
          OrthoPnt.Z = RefPnt.Z;
          OrthoDir = 4;
        }
        if (RefPnt.Y < pnt3D.Y & RefPnt.Z < pnt3D.Z & num < 1.0)
        {
          OrthoPnt.Y = RefPnt.Y;
          OrthoPnt.Z = pnt3D.Z;
          OrthoDir = 3;
        }
        if (RefPnt.Y < pnt3D.Y & RefPnt.Z > pnt3D.Z & num < -1.0)
        {
          OrthoPnt.Y = pnt3D.Y;
          OrthoPnt.Z = RefPnt.Z;
          OrthoDir = 2;
        }
        if (!(RefPnt.Y < pnt3D.Y & RefPnt.Z > pnt3D.Z & num > -1.0))
          return;
        OrthoPnt.Y = RefPnt.Y;
        OrthoPnt.Z = pnt3D.Z;
        OrthoDir = 3;
      }
      else
      {
        OrthoPnt.Y = RefPnt.Y;
        OrthoPnt.Z = RefPnt.Z;
      }
    }
    catch (Exception ex)
    {
      string str = $"RefPnt: {RefPnt.ToString()} - CenterPnt: {CenterPnt.ToString()} - Plane: {RefPlane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

