  public void BoxSizeCalculateSelected(
    EntityList refEntities,
    ref Point3D MinPoint,
    ref Point3D MidPoint,
    ref Point3D MaxPoint)
  {
    MinPoint = new Point3D(double.MaxValue, double.MaxValue, double.MaxValue);
    MaxPoint = new Point3D(double.MinValue, double.MinValue, double.MinValue);
    for (int index = 0; index <= refEntities.Count - 1; ++index)
    {
      Entity refEntity = refEntities[index];
      Point3D point3D1 = new Point3D();
      if (refEntities[index].Selected)
      {
        if (refEntity.BoxMin == (Point3D) null)
        {
          if (refEntity is devDept.Eyeshot.Entities.Text)
            refEntity.Regen(new RegenParams(0.001, (IWorkspace) DrawingFinisedEventArgs.baseModel));
          else
            refEntity.Regen(new RegenParams(0.001));
        }
        if (refEntity.BoxMin != (Point3D) null)
        {
          Point3D point3D2 = new Point3D(refEntity.BoxMin.X + point3D1.X, refEntity.BoxMin.Y + point3D1.Y, refEntity.BoxMin.Z + point3D1.Z);
          if (point3D2.X < MinPoint.X)
            MinPoint.X = point3D2.X;
          if (point3D2.Y < MinPoint.Y)
            MinPoint.Y = point3D2.Y;
          if (point3D2.Z < MinPoint.Z)
            MinPoint.Z = point3D2.Z;
        }
        if (refEntity.BoxMax != (Point3D) null)
        {
          Point3D point3D3 = new Point3D(refEntity.BoxMax.X + point3D1.X, refEntity.BoxMax.Y + point3D1.Y, refEntity.BoxMax.Z + point3D1.Z);
          if (MaxPoint.X < point3D3.X)
            MaxPoint.X = point3D3.X;
          if (MaxPoint.Y < point3D3.Y)
            MaxPoint.Y = point3D3.Y;
          if (MaxPoint.Z < point3D3.Z)
            MaxPoint.Z = point3D3.Z;
        }
      }
    }
    MidPoint = this.MiddlePointOfLine(MinPoint, MaxPoint);
  }

