    Point3D point3D3 = new Point3D(((CustomData) refEntity).BoxMax.X + point3D1.X, ((CustomData) refEntity).BoxMax.Y + point3D1.Y, ((CustomData) refEntity).BoxMax.Z + point3D1.Z);
