      if (point3D2.Z < MinPoint.Z)
        MinPoint.Z = point3D2.Z;
    }
    if (refEntity.BoxMax != (Point3D) null)
    {
      Point3D point3D3 = new Point3D(refEntity.BoxMax.X + point3D1.X, refEntity.BoxMax.Y + point3D1.Y, refEntity.BoxMax.Z + point3D1.Z);
