  public void BoxSizeCornerPoints(
    Point3D MinPoint,
    Point3D MaxPoint,
    Plane refPlane,
    ref Point3D LeftBottom,
    ref Point3D RightBottom,
    ref Point3D RightTop,
    ref Point3D LeftTop)
  {
    if (buVector5.isPlaneXYorYX(refPlane))
    {
      LeftBottom.X = MinPoint.X;
      LeftBottom.Y = MinPoint.Y;
      LeftBottom.Z = MinPoint.Z;
      RightBottom.X = MaxPoint.X;
      RightBottom.Y = MinPoint.Y;
      RightBottom.Z = MinPoint.Z;
      RightTop.X = MaxPoint.X;
      RightTop.Y = MaxPoint.Y;
      RightTop.Z = MinPoint.Z;
      LeftTop.X = MinPoint.X;
      LeftTop.Y = MaxPoint.Y;
      LeftTop.Z = MinPoint.Z;
    }
    if (buVector5.isPlaneXZorZX(refPlane))
    {
      LeftBottom.X = MinPoint.X;
      LeftBottom.Y = MinPoint.Y;
      LeftBottom.Z = MinPoint.Z;
      RightBottom.X = MaxPoint.X;
      RightBottom.Y = MinPoint.Y;
      RightBottom.Z = MinPoint.Z;
      RightTop.X = MaxPoint.X;
      RightTop.Y = MinPoint.Y;
      RightTop.Z = MaxPoint.Z;
      LeftTop.X = MinPoint.X;
      LeftTop.Y = MinPoint.Y;
      LeftTop.Z = MaxPoint.Z;
    }
    if (!buVector5.isPlaneYZorZY(refPlane))
      return;
    LeftBottom.X = MinPoint.X;
    LeftBottom.Y = MinPoint.Y;
    LeftBottom.Z = MinPoint.Z;
    RightBottom.X = MinPoint.X;
    RightBottom.Y = MaxPoint.Y;
    RightBottom.Z = MinPoint.Z;
    RightTop.X = MinPoint.X;
    RightTop.Y = MaxPoint.Y;
    RightTop.Z = MaxPoint.Z;
    LeftTop.X = MinPoint.X;
    LeftTop.Y = MinPoint.Y;
    LeftTop.Z = MaxPoint.Z;
  }

  public bool isBoxSizesIntersection(
    Point3D refMinPoint,
    Point3D refMaxPoint,
    Point3D checkMinPoint,
    Point3D checkMaxPoint,
    Plane refPlane)
  {
    bool flag;
    if (refMinPoint == (Point3D) null | refMaxPoint == (Point3D) null | checkMinPoint == (Point3D) null | checkMaxPoint == (Point3D) null)
    {
      flag = false;
    }
    else
    {
      Point3D LeftBottom = new Point3D();
      Point3D RightBottom = new Point3D();
      Point3D RightTop = new Point3D();
      Point3D LeftTop = new Point3D();
      this.BoxSizeCornerPoints(refMinPoint, refMaxPoint, refPlane, ref LeftBottom, ref RightBottom, ref RightTop, ref LeftTop);
      if (this.IsPointInsideBoxsize(LeftBottom, checkMinPoint, checkMaxPoint, refPlane))
        flag = true;
      else if (this.IsPointInsideBoxsize(RightBottom, checkMinPoint, checkMaxPoint, refPlane))
        flag = true;
      else if (this.IsPointInsideBoxsize(RightTop, checkMinPoint, checkMaxPoint, refPlane))
        flag = true;
      else if (this.IsPointInsideBoxsize(LeftTop, checkMinPoint, checkMaxPoint, refPlane))
      {
        flag = true;
      }
      else
      {
        this.BoxSizeCornerPoints(checkMinPoint, checkMaxPoint, refPlane, ref LeftBottom, ref RightBottom, ref RightTop, ref LeftTop);
        flag = this.IsPointInsideBoxsize(LeftBottom, refMinPoint, refMaxPoint, refPlane) || this.IsPointInsideBoxsize(RightBottom, refMinPoint, refMaxPoint, refPlane) || this.IsPointInsideBoxsize(RightTop, refMinPoint, refMaxPoint, refPlane) || this.IsPointInsideBoxsize(LeftTop, refMinPoint, refMaxPoint, refPlane);
      }
    }
    return flag;
  }

  public bool isBoxSizeInsideBoxSize(
    Point3D refMinPoint,
    Point3D refMaxPoint,
    Point3D checkMinPoint,
    Point3D checkMaxPoint,
    Plane refPlane)
  {
    return !(refMinPoint == (Point3D) null | refMaxPoint == (Point3D) null | checkMinPoint == (Point3D) null | checkMaxPoint == (Point3D) null) && (buVector5.isPlaneXYorYX(refPlane) && checkMinPoint.X >= refMinPoint.X & checkMinPoint.Y >= refMinPoint.Y && checkMaxPoint.X <= refMaxPoint.X & checkMaxPoint.Y <= refMaxPoint.Y || buVector5.isPlaneXZorZX(refPlane) && checkMinPoint.X > refMinPoint.X & checkMinPoint.Z > refMinPoint.Z && checkMaxPoint.X < refMaxPoint.X & checkMaxPoint.Z < refMaxPoint.Z || buVector5.isPlaneYZorZY(refPlane) && checkMinPoint.Y > refMinPoint.Y & checkMinPoint.Z > refMinPoint.Z && checkMaxPoint.Y < refMaxPoint.Y & checkMaxPoint.Z < refMaxPoint.Z);
  }

  public void BoxSizeWithContentAlignment(
    List<Point3D> RefPoints,
    WorkPlane Plane,
    ref AlingmentPoints3D AlignPoints)
  {
    try
    {
      Point3D MinPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      Point3D MidPoint = new Point3D();
      this.BoxSizeCalculate(RefPoints, ref MinPoint, ref MidPoint, ref MaxPoint);
      if (WorkPlane.isPlaneXY(Plane))
      {
        ((EyeCreateProps) AlignPoints).pntTopLeft = new Point3D(MinPoint.X, MaxPoint.Y, MinPoint.Z);
        ((EyeCreateProps) AlignPoints).pntTopCenter = new Point3D(MidPoint.X, MaxPoint.Y, MinPoint.Z);
        ((EyeCreateProps) AlignPoints).pntTopRight = new Point3D(MaxPoint.X, MaxPoint.Y, MinPoint.Z);
        ((EyeCreateProps) AlignPoints).pntMiddleLeft = new Point3D(MinPoint.X, MidPoint.Y, MinPoint.Z);
        ((EyeCreateProps) AlignPoints).pntMiddleCenter = new Point3D(MidPoint.X, MidPoint.Y, MinPoint.Z);
        ((EyeCreateProps) AlignPoints).pntMiddleRight = new Point3D(MaxPoint.X, MidPoint.Y, MinPoint.Z);
        ((EyeCreateProps) AlignPoints).pntBottomLeft = new Point3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
        ((EyeCreateProps) AlignPoints).pntBottomCenter = new Point3D(MidPoint.X, MinPoint.Y, MinPoint.Z);
        ((EyeCreateProps) AlignPoints).pntBottomRight = new Point3D(MaxPoint.X, MinPoint.Y, MinPoint.Z);
      }
      if (WorkPlane.isPlaneXZ(Plane))
      {
        ((EyeCreateProps) AlignPoints).pntTopLeft = new Point3D(MinPoint.X, MinPoint.Y, MaxPoint.Z);
        ((EyeCreateProps) AlignPoints).pntTopCenter = new Point3D(MidPoint.X, MinPoint.Y, MaxPoint.Z);
        ((EyeCreateProps) AlignPoints).pntTopRight = new Point3D(MaxPoint.X, MinPoint.Y, MaxPoint.Z);
        ((EyeCreateProps) AlignPoints).pntMiddleLeft = new Point3D(MinPoint.X, MinPoint.Y, MidPoint.Z);
        ((EyeCreateProps) AlignPoints).pntMiddleCenter = new Point3D(MidPoint.X, MinPoint.Y, MidPoint.Z);
        ((EyeCreateProps) AlignPoints).pntMiddleRight = new Point3D(MaxPoint.X, MinPoint.Y, MidPoint.Z);
        ((EyeCreateProps) AlignPoints).pntBottomLeft = new Point3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
        ((EyeCreateProps) AlignPoints).pntBottomCenter = new Point3D(MidPoint.X, MinPoint.Y, MinPoint.Z);
        ((EyeCreateProps) AlignPoints).pntBottomRight = new Point3D(MaxPoint.X, MinPoint.Y, MinPoint.Z);
      }
      if (!WorkPlane.isPlaneYZ(Plane))
        return;
      ((EyeCreateProps) AlignPoints).pntTopLeft = new Point3D(MinPoint.X, MinPoint.Y, MaxPoint.Z);
      ((EyeCreateProps) AlignPoints).pntTopCenter = new Point3D(MinPoint.X, MidPoint.Y, MaxPoint.Z);
      ((EyeCreateProps) AlignPoints).pntTopRight = new Point3D(MinPoint.X, MaxPoint.Y, MaxPoint.Z);
      ((EyeCreateProps) AlignPoints).pntMiddleLeft = new Point3D(MinPoint.X, MinPoint.Y, MidPoint.Z);
      ((EyeCreateProps) AlignPoints).pntMiddleCenter = new Point3D(MinPoint.X, MidPoint.Y, MidPoint.Z);
      ((EyeCreateProps) AlignPoints).pntMiddleRight = new Point3D(MinPoint.X, MaxPoint.Y, MidPoint.Z);
      ((EyeCreateProps) AlignPoints).pntBottomLeft = new Point3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
      ((EyeCreateProps) AlignPoints).pntBottomCenter = new Point3D(MinPoint.X, MidPoint.Y, MinPoint.Z);
      ((EyeCreateProps) AlignPoints).pntBottomRight = new Point3D(MinPoint.X, MaxPoint.Y, MinPoint.Z);
    }
    catch (Exception ex)
    {
      string str = $"RefPoints: {RefPoints.Count.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

