      ((EyeCreateProps) AlingPoints).pntMiddleRight = new Point3D(MaxPoint.X, MaxPoint.Y, point3D2.Z);
      ((EyeCreateProps) AlingPoints).pntTopLeft = new Point3D(MinPoint.X, MinPoint.Y, MaxPoint.Z);
      ((EyeCreateProps) AlingPoints).pntTopCenter = new Point3D(point3D2.X, point3D2.Y, MaxPoint.Z);
      ((EyeCreateProps) AlingPoints).pntTopRight = new Point3D(MaxPoint.X, MaxPoint.Y, MaxPoint.Z);
    }
    catch (Exception ex)
    {
      string str = $"MinPoint: {MinPoint.ToString()} - MaxPoint: {MaxPoint.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

