  public void AlingementContentPointByPlane(
    Point3D MinPoint,
    Point3D MaxPoint,
    ContentAlignment Alingement,
    Plane Plane,
    ref Point3D CalcPoint,
    ref Vector3D Length,
    ref AxesEnableXYZ IsCatchMiddle)
  {
    try
    {
      IsCatchMiddle = new AxesEnableXYZ(false, false, false);
      if (buVector5.isPlaneXYorYX(Plane))
      {
        if (Alingement == ContentAlignment.TopLeft)
        {
          CalcPoint.X = MinPoint.X;
          CalcPoint.Y = MaxPoint.Y;
          CalcPoint.Z = 0.0;
          Length.X = MaxPoint.X - MinPoint.X;
          Length.Y = MaxPoint.Y - MinPoint.Y;
          Length.Z = MaxPoint.Z - MinPoint.Z;
        }
        if (Alingement == ContentAlignment.TopCenter)
        {
          CalcPoint.X = (MinPoint.X + MaxPoint.X) / 2.0;
          CalcPoint.Y = MaxPoint.Y;
          CalcPoint.Z = 0.0;
          Length.X = MaxPoint.X - CalcPoint.X;
          Length.Y = MaxPoint.Y - MinPoint.Y;
          Length.Z = MaxPoint.Z - MinPoint.Z;
          IsCatchMiddle = new AxesEnableXYZ(true, false, false);
        }
        if (Alingement == ContentAlignment.TopRight)
        {
          CalcPoint.X = MaxPoint.X;
          CalcPoint.Y = MaxPoint.Y;
          CalcPoint.Z = 0.0;
          Length.X = MaxPoint.X - MinPoint.X;
          Length.Y = MaxPoint.Y - MinPoint.Y;
          Length.Z = MaxPoint.Z - MinPoint.Z;
        }
        if (Alingement == ContentAlignment.MiddleLeft)
        {
          CalcPoint.X = MinPoint.X;
          CalcPoint.Y = (MinPoint.Y + MaxPoint.Y) / 2.0;
          CalcPoint.Z = 0.0;
          Length.X = MaxPoint.X - MinPoint.X;
          Length.Y = MaxPoint.Y - CalcPoint.Y;
          Length.Z = MaxPoint.Z - MinPoint.Z;
          IsCatchMiddle = new AxesEnableXYZ(false, true, false);
        }
        if (Alingement == ContentAlignment.MiddleCenter)
        {
          CalcPoint.X = (MinPoint.X + MaxPoint.X) / 2.0;
          CalcPoint.Y = (MinPoint.Y + MaxPoint.Y) / 2.0;
          CalcPoint.Z = 0.0;
          Length.X = MaxPoint.X - CalcPoint.X;
          Length.Y = MaxPoint.Y - CalcPoint.Y;
          Length.Z = MaxPoint.Z - MinPoint.Z;
          IsCatchMiddle = new AxesEnableXYZ(true, true, false);
        }
        if (Alingement == ContentAlignment.MiddleRight)
        {
          CalcPoint.X = MaxPoint.X;
          CalcPoint.Y = (MinPoint.Y + MaxPoint.Y) / 2.0;
          CalcPoint.Z = 0.0;
          Length.X = MaxPoint.X - MinPoint.X;
          Length.Y = MaxPoint.Y - CalcPoint.Y;
          Length.Z = MaxPoint.Z - MinPoint.Z;
          IsCatchMiddle = new AxesEnableXYZ(false, true, false);
        }
        if (Alingement == ContentAlignment.BottomLeft)
        {
          CalcPoint.X = MinPoint.X;
          CalcPoint.Y = MinPoint.Y;
          CalcPoint.Z = 0.0;
          Length.X = MaxPoint.X - MinPoint.X;
          Length.Y = MaxPoint.Y - MinPoint.Y;
          Length.Z = MaxPoint.Z - MinPoint.Z;
        }
        if (Alingement == ContentAlignment.BottomCenter)
        {
          CalcPoint.X = (MinPoint.X + MaxPoint.X) / 2.0;
          CalcPoint.Y = MinPoint.Y;
          CalcPoint.Z = 0.0;
          Length.X = MaxPoint.X - CalcPoint.X;
          Length.Y = MaxPoint.Y - MinPoint.Y;
          Length.Z = MaxPoint.Z - MinPoint.Z;
          IsCatchMiddle = new AxesEnableXYZ(true, false, false);
        }
        if (Alingement == ContentAlignment.BottomRight)
        {
          CalcPoint.X = MaxPoint.X;
          CalcPoint.Y = MinPoint.Y;
          CalcPoint.Z = 0.0;
          Length.X = MaxPoint.X - MinPoint.X;
          Length.Y = MaxPoint.Y - MinPoint.Y;
          Length.Z = MaxPoint.Z - MinPoint.Z;
        }
      }
      if (buVector5.isPlaneXZorZX(Plane))
      {
        if (Alingement == ContentAlignment.TopLeft)
        {
          CalcPoint.X = MinPoint.X;
