          Length.Z = MaxPoint.Z - MinPoint.Z;
        }
      }
      if (!buVector5.isPlaneYZorZY(Plane))
        return;
      if (Alingement == ContentAlignment.TopLeft)
      {
        CalcPoint.X = 0.0;
        CalcPoint.Y = MinPoint.Y;
        CalcPoint.Z = MaxPoint.Z;
        Length.X = MaxPoint.X - MinPoint.X;
        Length.Y = MaxPoint.Y - MinPoint.Y;
        Length.Z = MaxPoint.Z - MinPoint.Z;
      }
      if (Alingement == ContentAlignment.TopCenter)
      {
        CalcPoint.X = 0.0;
        CalcPoint.Y = (MinPoint.Y + MaxPoint.Y) / 2.0;
        CalcPoint.Z = MaxPoint.Z;
        Length.X = MaxPoint.X - MinPoint.X;
        Length.Y = MaxPoint.Y - CalcPoint.Y;
        Length.Z = MaxPoint.Z - MinPoint.Z;
        IsCatchMiddle = new AxesEnableXYZ(false, true, false);
      }
      if (Alingement == ContentAlignment.TopRight)
      {
        CalcPoint.X = 0.0;
        CalcPoint.Y = MaxPoint.Y;
        CalcPoint.Z = MaxPoint.Z;
        Length.X = MaxPoint.X - MinPoint.X;
        Length.Y = MaxPoint.Y - MinPoint.Y;
        Length.Z = MaxPoint.Z - MinPoint.Z;
      }
      if (Alingement == ContentAlignment.MiddleLeft)
      {
        CalcPoint.X = 0.0;
        CalcPoint.Y = MinPoint.Y;
        CalcPoint.Z = (MinPoint.Z + MaxPoint.Z) / 2.0;
        Length.X = MaxPoint.X - MinPoint.X;
        Length.Y = MaxPoint.Y - MinPoint.Y;
        Length.Z = MaxPoint.Z - CalcPoint.Z;
        IsCatchMiddle = new AxesEnableXYZ(false, false, true);
      }
      if (Alingement == ContentAlignment.MiddleCenter)
      {
        CalcPoint.X = 0.0;
        CalcPoint.Y = (MinPoint.Y + MaxPoint.Y) / 2.0;
        CalcPoint.Z = (MinPoint.Z + MaxPoint.Z) / 2.0;
        Length.X = MaxPoint.X - MinPoint.X;
        Length.Y = MaxPoint.Y - CalcPoint.Y;
        Length.Z = MaxPoint.Z - CalcPoint.Z;
        IsCatchMiddle = new AxesEnableXYZ(false, true, true);
      }
      if (Alingement == ContentAlignment.MiddleRight)
      {
        CalcPoint.X = 0.0;
        CalcPoint.Y = MaxPoint.Y;
        CalcPoint.Z = (MinPoint.Z + MaxPoint.Z) / 2.0;
        Length.X = MaxPoint.X - MinPoint.X;
        Length.Y = MaxPoint.Y - MinPoint.Y;
        Length.Z = MaxPoint.Z - CalcPoint.Z;
        IsCatchMiddle = new AxesEnableXYZ(false, false, true);
      }
      if (Alingement == ContentAlignment.BottomLeft)
      {
        CalcPoint.X = 0.0;
        CalcPoint.Y = MinPoint.Y;
        CalcPoint.Z = MinPoint.Z;
        Length.X = MaxPoint.X - MinPoint.X;
        Length.Y = MaxPoint.Y - MinPoint.Y;
