        Length.Y = MaxPoint.Y - CalcPoint.Y;
        Length.Z = MaxPoint.Z - MinPoint.Z;
        IsCatchMiddle = new AxesEnableXYZ(false, true, false);
      }
      if (Alingement != ContentAlignment.BottomRight)
        return;
      CalcPoint.X = 0.0;
      CalcPoint.Y = MaxPoint.Y;
      CalcPoint.Z = MinPoint.Z;
      Length.X = MaxPoint.X - MinPoint.X;
