  public void AddValueToPointList(double x, double y, double z, ref List<Point3D> pntList)
  {
    for (int index = 0; index <= pntList.Count - 1; ++index)
    {
      Point3D point3D = new Point3D(pntList[index].X + x, pntList[index].Y + y, pntList[index].Z + z);
      pntList[index] = point3D;
    }
  }

  public void AddValueToPointList(double x, double y, double z, ref List<PointRGB> pntList)
  {
    for (int index = 0; index <= pntList.Count - 1; ++index)
    {
      Color color = Color.FromArgb((int) byte.MaxValue, (int) pntList[index].R, (int) pntList[index].G, (int) pntList[index].B);
      PointRGB pointRgb = new PointRGB(pntList[index].X + x, pntList[index].Y + y, pntList[index].Z + z, color.R, color.G, color.B);
      pntList[index] = pointRgb;
    }
  }

  public void AddPointOffsetedPath(
    List<Point3D> ModifiedPoints,
    List<Point3D> SortedOriginalPoints,
    double Offset,
    bool Closed,
    ClockDirectionType ClockDir,
    double Resolution,
    ref List<Point3D> CalcPoints)
  {
    double num = this.PointAngle(SortedOriginalPoints[1], SortedOriginalPoints[0], Plane.XY);
    Point3D EndPnt1 = new Point3D();
    Point3D EndPnt2 = new Point3D();
    this.LineWithLengthAndAngle(SortedOriginalPoints[0], Math.Abs(Offset), num + 90.0, Plane.XY, ref EndPnt1);
    this.LineWithLengthAndAngle(SortedOriginalPoints[0], Math.Abs(Offset), num - 90.0, Plane.XY, ref EndPnt2);
    List<Point3D> copiedPoint = new List<Point3D>();
    buVector5.Copy(ModifiedPoints, ref copiedPoint);
    for (int index = 1; index <= copiedPoint.Count - 1; ++index)
    {
      Point3D point3D = new Point3D();
      if (((F_EntitiesProps) this).isPointOverLine(copiedPoint[index - 1], copiedPoint[index], EndPnt1, Resolution))
      {
        copiedPoint.Insert(index, new Point3D(point3D.X, point3D.Y, copiedPoint[index].Z));
        index = copiedPoint.Count;
      }
      if (index <= copiedPoint.Count - 1 && ((F_EntitiesProps) this).isPointOverLine(copiedPoint[index - 1], copiedPoint[index], EndPnt2, Resolution))
      {
        copiedPoint.Insert(index, new Point3D(point3D.X, point3D.Y, copiedPoint[index].Z));
        index = copiedPoint.Count;
      }
    }
    if (this.GetClockDirection(ModifiedPoints, Plane.XY) != ClockDir & Closed)
      ModifiedPoints.Reverse();
    CalcPoints = new List<Point3D>((IEnumerable<Point3D>) copiedPoint);
  }

  public void SetValueToPointList(
    double x,
    double y,
    double z,
    bool XEnable,
    bool YEnable,
    bool ZEnable,
    ref List<Point3D> pntList)
  {
    for (int index = 0; index <= pntList.Count - 1; ++index)
    {
      Point3D point3D = new Point3D();
      if (XEnable)
        point3D.X = x;
      else
        point3D.X = pntList[index].X;
      if (YEnable)
        point3D.Y = y;
      else
        point3D.Y = pntList[index].Y;
      point3D.Z = !ZEnable ? pntList[index].Z : z;
      pntList[index] = point3D;
    }
  }

