  public ClockDirectionType GetClockDirection(
    List<Point3D> Vertices,
    Plane refPlane,
    ref double TotalArea)
  {
    try
    {
      double num1 = 0.0;
      double num2 = 0.0;
      List<Point3D> copiedPoint = new List<Point3D>();
      buVector5.Copy(Vertices, ref copiedPoint);
      if (!((F_AnalyseResult) this).IsClosed(copiedPoint))
        copiedPoint.Add(F_NotchEdit.ToPoint3D(Vertices[0]));
      if (buVector5.isPlaneXYorYX(refPlane))
      {
        for (int index = 1; index <= copiedPoint.Count - 1; ++index)
        {
          double num3 = copiedPoint[index].X - copiedPoint[index - 1].X;
          double num4 = copiedPoint[index].Y + copiedPoint[index - 1].Y;
          num1 += (copiedPoint[index].X - copiedPoint[index - 1].X) * (copiedPoint[index].Y + copiedPoint[index - 1].Y) / 2.0;
          num2 += (copiedPoint[index - 1].X * copiedPoint[index].Y - copiedPoint[index].X * copiedPoint[index - 1].Y) / 2.0;
        }
      }
      if (buVector5.isPlaneXZorZX(refPlane))
      {
        for (int index = 1; index <= copiedPoint.Count - 1; ++index)
          num1 += (copiedPoint[index].X - copiedPoint[index - 1].X) * (copiedPoint[index].Z + copiedPoint[index - 1].Z) / 2.0;
      }
      if (buVector5.isPlaneYZorZY(refPlane))
      {
        for (int index = 1; index <= copiedPoint.Count - 1; ++index)
          num1 += (copiedPoint[index].Y - copiedPoint[index - 1].Y) * (copiedPoint[index].Z + copiedPoint[index - 1].Z) / 2.0;
      }
      TotalArea = num1;
      return num1 > 0.0 ? ClockDirectionType.CW : ClockDirectionType.CCW;
    }
    catch (Exception ex)
    {
      string str = "Vertices: " + Vertices.Count.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return ClockDirectionType.CW;
    }
  }

  public bool IsPointInsideWindow(
    Point3D Base,
    Point3D ControledPoint,
    double WindowSize,
    Plane refPlane)
  {
    try
    {
      if (buVector5.isPlaneXYorYX(refPlane))
      {
        if (Base.X - WindowSize / 2.0 <= ControledPoint.X & ControledPoint.X <= Base.X + WindowSize / 2.0 && Base.Y - WindowSize / 2.0 <= ControledPoint.Y & ControledPoint.Y <= Base.Y + WindowSize / 2.0)
          return true;
      }
      else if (buVector5.isPlaneXZorZX(refPlane))
      {
        if (Base.X - WindowSize / 2.0 <= ControledPoint.X & ControledPoint.X <= Base.X + WindowSize / 2.0 && Base.Z - WindowSize / 2.0 <= ControledPoint.Z & ControledPoint.Z <= Base.Z + WindowSize / 2.0)
          return true;
      }
      else if (buVector5.isPlaneYZorZY(refPlane))
      {
        if (Base.Y - WindowSize / 2.0 <= ControledPoint.Y & ControledPoint.Y <= Base.Y + WindowSize / 2.0 && Base.Z - WindowSize / 2.0 <= ControledPoint.Z & ControledPoint.Z <= Base.Z + WindowSize / 2.0)
          return true;
      }
      else if (Base.X - WindowSize / 2.0 <= ControledPoint.X & ControledPoint.X <= Base.X + WindowSize / 2.0 && Base.Y - WindowSize / 2.0 <= ControledPoint.Y & ControledPoint.Y <= Base.Y + WindowSize / 2.0 && Base.Z - WindowSize / 2.0 <= ControledPoint.Z & ControledPoint.Z <= Base.Z + WindowSize / 2.0)
        return true;
      return false;
    }
    catch (Exception ex)
    {
      string str = $"Base: {Base.ToString()} - ControledPoint: {ControledPoint.ToString()} - Resolution: {WindowSize.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return false;
    }
  }

  public bool IsPointInsideWindow(
    Point3D Base,
    Point3D ControledPoint,
    double Width,
    double Height,
    Plane refPlane)
  {
    bool flag;
    try
    {
      if (buVector5.isPlaneXYorYX(refPlane) && Base.X - Width / 2.0 <= ControledPoint.X & ControledPoint.X <= Base.X + Width / 2.0 && Base.Y - Height / 2.0 <= ControledPoint.Y & ControledPoint.Y <= Base.Y + Height / 2.0)
      {
        flag = true;
        goto label_11;
      }
      if (buVector5.isPlaneXZorZX(refPlane) && Base.X - Width / 2.0 <= ControledPoint.X & ControledPoint.X <= Base.X + Width / 2.0 && Base.Z - Height / 2.0 <= ControledPoint.Z & ControledPoint.Z <= Base.Z + Height / 2.0)
      {
        flag = true;
        goto label_11;
      }
      if (buVector5.isPlaneYZorZY(refPlane))
      {
        if (Base.Y - Width / 2.0 <= ControledPoint.Y & ControledPoint.Y <= Base.Y + Width / 2.0)
        {
          if (Base.Z - Height / 2.0 <= ControledPoint.Z & ControledPoint.Z <= Base.Z + Height / 2.0)
          {
            flag = true;
            goto label_11;
          }
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"Base: {Base.ToString()} - ControledPoint: {ControledPoint.ToString()} - Width: {Width.ToString()} - Height: {Height.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      flag = false;
      goto label_11;
    }
    flag = false;
label_11:
    return flag;
  }

  public bool IsPointInsideWindow(
    Point3D LeftBottom,
    Point3D RightTop,
    Point3D ControledPoint,
    Plane refPlane,
    bool UseEqualCondition)
  {
    bool flag;
    try
    {
      if (UseEqualCondition)
      {
        if (buVector5.isPlaneXYorYX(refPlane) && buConversion5.LE(LeftBottom.X, ControledPoint.X) & buConversion5.LE(ControledPoint.X, RightTop.X) && buConversion5.LE(LeftBottom.Y, ControledPoint.Y) & buConversion5.LE(ControledPoint.Y, RightTop.Y))
        {
          flag = true;
          goto label_20;
        }
        if (buVector5.isPlaneXZorZX(refPlane) && LeftBottom.X <= ControledPoint.X & ControledPoint.X <= RightTop.X && LeftBottom.Z <= ControledPoint.Z & ControledPoint.Z <= RightTop.Z)
        {
          flag = true;
          goto label_20;
        }
        if (buVector5.isPlaneYZorZY(refPlane))
        {
          if (LeftBottom.Y <= ControledPoint.Y & ControledPoint.Y <= RightTop.Y)
          {
            if (LeftBottom.Z <= ControledPoint.Z & ControledPoint.Z <= RightTop.Z)
            {
              flag = true;
              goto label_20;
            }
          }
        }
      }
      else
      {
        if (buVector5.isPlaneXYorYX(refPlane) && LeftBottom.X < ControledPoint.X & ControledPoint.X < RightTop.X && LeftBottom.Y < ControledPoint.Y & ControledPoint.Y < RightTop.Y)
        {
          flag = true;
          goto label_20;
        }
        if (buVector5.isPlaneXZorZX(refPlane) && LeftBottom.X < ControledPoint.X & ControledPoint.X < RightTop.X && LeftBottom.Z < ControledPoint.Z & ControledPoint.Z < RightTop.Z)
        {
          flag = true;
          goto label_20;
        }
        if (buVector5.isPlaneYZorZY(refPlane))
        {
          if (LeftBottom.Y < ControledPoint.Y & ControledPoint.Y < RightTop.Y)
          {
            if (LeftBottom.Z < ControledPoint.Z & ControledPoint.Z < RightTop.Z)
            {
              flag = true;
              goto label_20;
            }
          }
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"LeftBottom: {LeftBottom.ToString()} - RightTop: {RightTop.ToString()} - ControledPoint: {ControledPoint.ToString()} - UseEqualCondition: {UseEqualCondition.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      flag = false;
      goto label_20;
    }
    flag = false;
label_20:
    return flag;
  }

