  public void ShiftPointList(ref List<Point3D> List, int ShiftValue)
  {
    if (ShiftValue == 0 || ShiftValue >= List.Count)
      return;
    if (ShiftValue < 0)
    {
      List<Point3D> CopyPnt = new List<Point3D>();
      F_AnalyseResult.ToPoint3D(List, ref CopyPnt);
      if (((F_AnalyseResult) this).IsClosed(CopyPnt) && ShiftValue != 0)
        CopyPnt.RemoveAt(CopyPnt.Count - 1);
      List.Clear();
      for (int index = Math.Abs(ShiftValue); index <= CopyPnt.Count - 1; ++index)
        List.Add(F_NotchEdit.ToPoint3D(CopyPnt[index]));
      for (int index = 0; index < Math.Abs(ShiftValue); ++index)
        List.Add(F_NotchEdit.ToPoint3D(CopyPnt[index]));
      List.Add(new Point3D(List[0].X, List[0].Y, List[0].Z));
    }
    if (ShiftValue <= 0)
      return;
    List<Point3D> CopyPnt1 = new List<Point3D>();
    F_AnalyseResult.ToPoint3D(List, ref CopyPnt1);
    List.Clear();
    for (int index = CopyPnt1.Count - Math.Abs(ShiftValue) - 1; index <= CopyPnt1.Count - 1; ++index)
      List.Add(F_NotchEdit.ToPoint3D(CopyPnt1[index]));
    for (int index = 0; index < CopyPnt1.Count - Math.Abs(ShiftValue) - 1; ++index)
      List.Add(F_NotchEdit.ToPoint3D(CopyPnt1[index]));
  }

