  public void PointFilterByLengthCornerPoint(double FilterLength, ref List<Point3D> Vertice)
  {
    try
    {
      List<Point3D> point3DList = new List<Point3D>();
      List<Point3D> refPoint = new List<Point3D>();
      if (Vertice.Count <= 0)
        return;
      for (int index = 0; index <= Vertice.Count - 1; ++index)
        point3DList.Add(F_NotchEdit.ToPoint3D(Vertice[index]));
      refPoint.Add(F_NotchEdit.ToPoint3D(point3DList[0]));
      AngleVector angleVector = new AngleVector();
      for (int index1 = 1; index1 <= point3DList.Count - 1; ++index1)
      {
        double num1 = this.Length3D(refPoint[refPoint.Count - 1], point3DList[index1]);
        double num2 = this.Length2D(refPoint[refPoint.Count - 1], point3DList[index1], Plane.YZ);
        double num3 = this.Length2D(refPoint[refPoint.Count - 1], point3DList[index1], Plane.XZ);
        double num4 = this.Length2D(refPoint[refPoint.Count - 1], point3DList[index1], Plane.YZ);
        Point3D point3D1 = new Point3D(point3DList[index1 - 1].X, point3DList[index1 - 1].Y, point3DList[index1 - 1].Z);
        Point3D point3D2 = new Point3D(point3DList[index1].X, point3DList[index1].Y, point3DList[index1].Z);
        AngleVector angle = new AngleVector();
        angle.X = this.PointAngle(point3DList[index1], point3DList[index1 - 1], Plane.YZ);
        angle.Y = this.PointAngle(point3DList[index1], point3DList[index1 - 1], Plane.XZ);
        angle.Z = this.PointAngle(point3DList[index1], point3DList[index1 - 1], Plane.XY);
        bool flag = false;
        double num5 = Math.Abs(angle.X - angleVector.X);
        double num6 = Math.Abs(angle.Y - angleVector.Y);
        double num7 = Math.Abs(angle.Z - angleVector.Z);
        if (num5 > 360.0)
          num5 -= 360.0;
        if (num6 > 360.0)
          num6 -= 360.0;
        if (num7 > 360.0)
          num7 -= 360.0;
        if (num5 > 180.0)
          num5 -= 180.0;
        if (num6 > 180.0)
          num6 -= 180.0;
        if (num7 > 180.0)
          num7 -= 180.0;
        if (num2 < 0.1)
          num5 = 0.0;
        if (num3 < 0.1)
          num6 = 0.0;
        if (num4 < 0.1)
          num7 = 0.0;
        if ((num5 > 30.0 & num5 < 170.0 | num6 > 30.0 & num6 < 170.0 | num7 > 30.0 & num7 < 170.0) & index1 > 1)
          flag = true;
        if (!flag)
        {
          if (num1 > FilterLength)
          {
            if (num1 < FilterLength * 2.0)
            {
              refPoint.Add(F_NotchEdit.ToPoint3D(point3DList[index1]));
            }
            else
            {
              int int32 = Convert.ToInt32(num1 / FilterLength);
              Line line = new Line(refPoint[refPoint.Count - 1], point3DList[index1]);
              double num8 = (line.Domain.t1 - line.Domain.t0) / (double) int32;
              for (int index2 = 1; index2 < int32; ++index2)
              {
                Point3D point3D3 = line.PointAt(num8 * (double) index2);
                refPoint.Add(point3D3);
              }
            }
          }
        }
        else
          refPoint.Add(F_NotchEdit.ToPoint3D(point3DList[index1]));
        angleVector = new AngleVector(angle);
      }
      if (point3DList.Count >= 2 & refPoint.Count == 1)
        refPoint.Add(F_NotchEdit.ToPoint3D(point3DList[point3DList.Count - 1]));
      if (!buConversion5.EQ(refPoint[refPoint.Count - 1], point3DList[point3DList.Count - 1]))
        refPoint.Add(F_NotchEdit.ToPoint3D(point3DList[point3DList.Count - 1]));
      Vertice.Clear();
      Vertice = new List<Point3D>();
      buVector5.Copy(refPoint, ref Vertice);
    }
    catch (Exception ex)
    {
      string str = "FilterLength: " + FilterLength.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void PointFilterByLength(double FilterLength, ref List<Point3D> Vertice)
  {
    try
    {
      List<Point3D> point3DList = new List<Point3D>();
      List<Point3D> refPoint = new List<Point3D>();
      if (Vertice.Count <= 0)
        return;
      for (int index = 0; index <= Vertice.Count - 1; ++index)
        point3DList.Add(F_NotchEdit.ToPoint3D(Vertice[index]));
      refPoint.Add(F_NotchEdit.ToPoint3D(point3DList[0]));
      for (int index1 = 1; index1 <= point3DList.Count - 1; ++index1)
      {
        double num1 = this.Length3D(refPoint[refPoint.Count - 1], point3DList[index1]);
        if (num1 > FilterLength)
        {
          if (num1 < FilterLength * 2.0)
          {
            refPoint.Add(F_NotchEdit.ToPoint3D(point3DList[index1]));
          }
          else
          {
            int int32 = Convert.ToInt32(num1 / FilterLength);
            Line line = new Line(refPoint[refPoint.Count - 1], point3DList[index1]);
            double num2 = (line.Domain.t1 - line.Domain.t0) / (double) int32;
            for (int index2 = 1; index2 < int32; ++index2)
            {
              Point3D point3D = line.PointAt(num2 * (double) index2);
              refPoint.Add(point3D);
            }
          }
        }
      }
      if (point3DList.Count >= 2 & refPoint.Count == 1)
        refPoint.Add(F_NotchEdit.ToPoint3D(point3DList[point3DList.Count - 1]));
      if (!buConversion5.EQ(refPoint[refPoint.Count - 1], point3DList[point3DList.Count - 1]))
        refPoint.Add(F_NotchEdit.ToPoint3D(point3DList[point3DList.Count - 1]));
      Vertice.Clear();
      Vertice = new List<Point3D>();
      buVector5.Copy(refPoint, ref Vertice);
    }
    catch (Exception ex)
    {
      string str = "FilterLength: " + FilterLength.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void RemoveSmallLengthFromPoints(double Length, ref List<Point3D> Vertice)
  {
    try
    {
      List<Point3D> point3DList = new List<Point3D>();
      List<Point3D> refPoint = new List<Point3D>();
      double num = 0.0;
      if (Vertice.Count <= 0)
        return;
      refPoint.Add(F_NotchEdit.ToPoint3D(Vertice[0]));
      for (int index = 1; index <= Vertice.Count - 1; ++index)
      {
        num += this.Length3D(refPoint[refPoint.Count - 1], Vertice[index]);
        if (num > Length)
        {
          refPoint.Add(F_NotchEdit.ToPoint3D(Vertice[index]));
          num = 0.0;
        }
      }
      if (!buConversion5.EQ(Vertice[Vertice.Count - 1], refPoint[refPoint.Count - 1]))
        refPoint.Add(F_NotchEdit.ToPoint3D(Vertice[Vertice.Count - 1]));
      Vertice.Clear();
      Vertice = new List<Point3D>();
      buVector5.Copy(refPoint, ref Vertice);
    }
    catch (Exception ex)
    {
      string str = "RemoveSmallLengthFromPoints: " + Length.ToString();
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

