  public void Vector3DToVectorXYZ(
    Vector3D baseVactor,
    ref Vector3D VectorX,
    ref Vector3D VectorY,
    ref Vector3D VectorZ)
  {
    VectorX = baseVactor.X <= 0.0 ? (baseVactor.X >= 0.0 ? new Vector3D(0.0, 0.0, 0.0) : Vector3D.AxisMinusX) : Vector3D.AxisX;
    VectorY = baseVactor.Y <= 0.0 ? (baseVactor.Y >= 0.0 ? new Vector3D(0.0, 0.0, 0.0) : Vector3D.AxisMinusY) : Vector3D.AxisY;
    if (baseVactor.Z > 0.0)
      VectorZ = Vector3D.AxisZ;
    else if (baseVactor.Z < 0.0)
      VectorZ = Vector3D.AxisMinusZ;
    else
      VectorZ = new Vector3D(0.0, 0.0, 0.0);
  }

