  public void HatchLinear(
    List<Point3D> Points,
    double ZPosition,
    double Step,
    HorizontalVertical Direction,
    Plane refPlane,
    ref List<buEntity> calcLines)
  {
    Point3D MinPoint = new Point3D();
    Point3D MaxPoint = new Point3D();
    this.BoxSizeCalculate(Points, ref MinPoint, ref MaxPoint);
    if (calcLines == null)
      calcLines = new List<buEntity>();
    calcLines.Clear();
    List<Point3D> points = new List<Point3D>();
    for (int index = 0; index <= Points.Count - 1; ++index)
      points.Add(new Point3D(Points[index].X, Points[index].Y, 0.0));
    if (Direction != HorizontalVertical.Horizontal)
      return;
    double x1 = MinPoint.X - 10.0;
    double x2 = MaxPoint.X + 10.0;
    double y1 = MinPoint.Y;
    double num1 = MaxPoint.Y - y1 - Step;
    int lower = (int) buFile5.RoundToLower(num1 / Step);
    double num2 = num1 / (double) lower;
    double y2 = MinPoint.Y;
    for (int index = 1; index <= lower + 1; ++index)
    {
      if (index == 1)
        y2 += Math.Round(num2 / 2.0, 3);
      else
        y2 += Math.Round(num2, 3);
      Point3D[] source = new Line(new Point3D(x1, y2, 0.0), new Point3D(x2, y2, 0.0)).IntersectWith((ICurve) new LinearPath((ICollection<Point3D>) points), 0.0, true);
      List<Point3D> SortingPoints = new List<Point3D>();
      SortingPoints.AddRange((IEnumerable<Point3D>) ((IEnumerable<Point3D>) source).ToArray<Point3D>());
      this.SortDeltaX(new Point3D(-100000.0, -100000.0, 0.0), SortDirectionType.Lower, ref SortingPoints);
      if (SortingPoints.Count >= 2)
      {
        buEntity buEntity = (buEntity) new buMultilineText(new Point3D(SortingPoints[0].X, y2, Math.Round(ZPosition, 3)), new Point3D(SortingPoints[SortingPoints.Count - 1].X, y2, Math.Round(ZPosition, 3)));
        calcLines.Add(buEntity);
      }
    }
  }

  public void HatchLinear(
    Point3D StartPoint,
    double Width,
    double Height,
    double Step,
    HorizontalVertical Direction,
    HatchCuttingMode Mode,
    Plane refPlane,
    ref List<List<Entity>> calcEntities)
  {
    if (calcEntities == null)
      calcEntities = new List<List<Entity>>();
    calcEntities.Clear();
    if (Direction == HorizontalVertical.Horizontal)
    {
      int num1 = (int) buFile5.RoundToLower(Height / Step);
      if (num1 == 0)
        num1 = 1;
      double num2 = Height / (double) num1;
      Point3D point3D = new Point3D();
      List<Entity> entityList1 = new List<Entity>();
      for (int index = 0; index <= num1; ++index)
      {
        if (buVector5.isPlaneXYorYX(refPlane))
        {
          double num3 = (double) index * num2;
          if (Mode == HatchCuttingMode.Forward)
            calcEntities.Add(new List<Entity>()
            {
              (Entity) new Line(new Point3D(StartPoint.X, StartPoint.Y + num3, StartPoint.Z), new Point3D(StartPoint.X + Width, StartPoint.Y + num3, StartPoint.Z))
            });
          if (Mode == HatchCuttingMode.Backward)
            calcEntities.Add(new List<Entity>()
            {
              (Entity) new Line(new Point3D(StartPoint.X + Width, StartPoint.Y + num3, StartPoint.Z), new Point3D(StartPoint.X, StartPoint.Y + num3, StartPoint.Z))
            });
          if (Mode == HatchCuttingMode.ForwardBackward)
          {
            List<Entity> entityList2 = new List<Entity>();
            Entity entity = (Entity) null;
            if (index % 2 == 0)
              entity = (Entity) new Line(new Point3D(StartPoint.X, StartPoint.Y + num3, StartPoint.Z), new Point3D(StartPoint.X + Width, StartPoint.Y + num3, StartPoint.Z));
            if (index % 2 == 1)
              entity = (Entity) new Line(new Point3D(StartPoint.X + Width, StartPoint.Y + num3, StartPoint.Z), new Point3D(StartPoint.X, StartPoint.Y + num3, StartPoint.Z));
            entityList2.Add(entity);
            calcEntities.Add(entityList2);
          }
        }
        if (buVector5.isPlaneXZorZX(refPlane))
        {
          double num4 = (double) index * num2;
          if (Mode == HatchCuttingMode.Forward)
            calcEntities.Add(new List<Entity>()
            {
              (Entity) new Line(new Point3D(StartPoint.X, StartPoint.Y, StartPoint.Z + num4), new Point3D(StartPoint.X + Width, StartPoint.Y, StartPoint.Z + num4))
            });
          if (Mode == HatchCuttingMode.Backward)
            calcEntities.Add(new List<Entity>()
            {
              (Entity) new Line(new Point3D(StartPoint.X + Width, StartPoint.Y, StartPoint.Z + num4), new Point3D(StartPoint.X, StartPoint.Y, StartPoint.Z + num4))
            });
          if (Mode == HatchCuttingMode.ForwardBackward)
          {
            List<Entity> entityList3 = new List<Entity>();
            Entity entity = (Entity) null;
            if (index % 2 == 0)
              entity = (Entity) new Line(new Point3D(StartPoint.X, StartPoint.Y, StartPoint.Z + num4), new Point3D(StartPoint.X + Width, StartPoint.Y, StartPoint.Z + num4));
            if (index % 2 == 1)
              entity = (Entity) new Line(new Point3D(StartPoint.X + Width, StartPoint.Y, StartPoint.Z + num4), new Point3D(StartPoint.X, StartPoint.Y, StartPoint.Z + num4));
            entityList3.Add(entity);
            calcEntities.Add(entityList3);
          }
        }
      }
    }
    if (Direction != HorizontalVertical.Vertical)
      return;
    int num5 = (int) buFile5.RoundToLower(Width / Step);
    if (num5 == 0)
      num5 = 1;
    double num6 = Width / (double) num5;
    Point3D point3D1 = new Point3D();
    List<Entity> entityList4 = new List<Entity>();
    for (int index = 0; index <= num5; ++index)
    {
      if (buVector5.isPlaneXYorYX(refPlane))
      {
        double num7 = (double) index * num6;
        if (Mode == HatchCuttingMode.Forward)
          calcEntities.Add(new List<Entity>()
          {
            (Entity) new Line(new Point3D(StartPoint.X + num7, StartPoint.Y, StartPoint.Z), new Point3D(StartPoint.X + num7, StartPoint.Y + Height, StartPoint.Z))
          });
        double num8 = (double) index * num6;
        if (Mode == HatchCuttingMode.Forward)
          calcEntities.Add(new List<Entity>()
          {
            (Entity) new Line(new Point3D(StartPoint.X + num8, StartPoint.Y + Height, StartPoint.Z), new Point3D(StartPoint.X + num8, StartPoint.Y, StartPoint.Z))
          });
        if (Mode == HatchCuttingMode.ForwardBackward)
        {
          List<Entity> entityList5 = new List<Entity>();
          Entity entity = (Entity) null;
          if (index % 2 == 0)
            entity = (Entity) new Line(new Point3D(StartPoint.X + num8, StartPoint.Y, StartPoint.Z), new Point3D(StartPoint.X + num8, StartPoint.Y + Height, StartPoint.Z));
          if (index % 2 == 1)
            entity = (Entity) new Line(new Point3D(StartPoint.X + num8, StartPoint.Y + Height, StartPoint.Z), new Point3D(StartPoint.X + num8, StartPoint.Y, StartPoint.Z));
          entityList5.Add(entity);
          calcEntities.Add(entityList5);
        }
      }
      if (buVector5.isPlaneXZorZX(refPlane))
      {
        double num9 = (double) index * num6;
        if (Mode == HatchCuttingMode.Forward)
          calcEntities.Add(new List<Entity>()
          {
            (Entity) new Line(new Point3D(StartPoint.X + num9, StartPoint.Y, StartPoint.Z), new Point3D(StartPoint.X + num9, StartPoint.Y, StartPoint.Z + Height))
          });
        double num10 = (double) index * num6;
        if (Mode == HatchCuttingMode.Forward)
          calcEntities.Add(new List<Entity>()
          {
            (Entity) new Line(new Point3D(StartPoint.X + num10, StartPoint.Y, StartPoint.Z + Height), new Point3D(StartPoint.X + num10, StartPoint.Y, StartPoint.Z))
          });
        if (Mode == HatchCuttingMode.ForwardBackward)
        {
          List<Entity> entityList6 = new List<Entity>();
          Entity entity = (Entity) null;
          if (index % 2 == 0)
            entity = (Entity) new Line(new Point3D(StartPoint.X + num10, StartPoint.Y, StartPoint.Z), new Point3D(StartPoint.X + num10, StartPoint.Y, StartPoint.Z + Height));
          if (index % 2 == 1)
            entity = (Entity) new Line(new Point3D(StartPoint.X + num10, StartPoint.Y, StartPoint.Z + Height), new Point3D(StartPoint.X + num10, StartPoint.Y, StartPoint.Z));
          entityList6.Add(entity);
          calcEntities.Add(entityList6);
        }
      }
    }
  }

