  public void Move(
    double dX,
    double dY,
    double dZ,
    ref buEntitiesGroup refEntities,
    double Regen = 0.01)
  {
    if (refEntities.Outside != null)
    {
      for (int index = 0; index <= ((\u0084.\u0001) refEntities.Outside).Entities.Count - 1; ++index)
      {
        buEntity entity = ((\u0084.\u0001) refEntities.Outside).Entities[index];
        this.Move(dX, dY, dZ, ref entity, Regen);
      }
      if (((\u0084.\u0001) refEntities.Outside).Points != null)
        this.Move(dX, dY, dZ, ref ((\u0084.\u0001) refEntities.Outside).Points);
    }
    if (((DimensionGroup) refEntities).Text != null)
    {
      for (int index = 0; index <= ((\u0084.\u0001) ((DimensionGroup) refEntities).Text).Entities.Count - 1; ++index)
      {
        buEntity entity = ((\u0084.\u0001) ((DimensionGroup) refEntities).Text).Entities[index];
        this.Move(dX, dY, dZ, ref entity, Regen);
      }
      if (((\u0084.\u0001) ((DimensionGroup) refEntities).Text).Points != null)
        this.Move(dX, dY, dZ, ref ((\u0084.\u0001) ((DimensionGroup) refEntities).Text).Points);
    }
    if (refEntities.Inside != null)
    {
      for (int index1 = 0; index1 <= refEntities.Inside.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= ((\u0084.\u0001) refEntities.Inside[index1]).Entities.Count - 1; ++index2)
        {
          buEntity entity = ((\u0084.\u0001) refEntities.Inside[index1]).Entities[index2];
          this.Move(dX, dY, dZ, ref entity, Regen);
        }
        if (((\u0084.\u0001) refEntities.Inside[index1]).Points != null)
          this.Move(dX, dY, dZ, ref ((\u0084.\u0001) refEntities.Inside[index1]).Points);
      }
    }
    if (refEntities.OpenEntities != null)
    {
      for (int index3 = 0; index3 <= refEntities.OpenEntities.Count - 1; ++index3)
      {
        for (int index4 = 0; index4 <= ((\u0084.\u0001) refEntities.OpenEntities[index3]).Entities.Count - 1; ++index4)
        {
          buEntity entity = ((\u0084.\u0001) refEntities.OpenEntities[index3]).Entities[index4];
          this.Move(dX, dY, dZ, ref entity, Regen);
        }
        if (((\u0084.\u0001) refEntities.OpenEntities[index3]).Points != null)
          this.Move(dX, dY, dZ, ref ((\u0084.\u0001) refEntities.OpenEntities[index3]).Points);
      }
    }
    if (((DimensionGroup) refEntities).Solid == null)
      return;
    for (int index = 0; index <= ((\u0084.\u0001) ((DimensionGroup) refEntities).Solid).Entities.Count - 1; ++index)
    {
      buEntity entity = ((\u0084.\u0001) ((DimensionGroup) refEntities).Solid).Entities[index];
      this.Move(dX, dY, dZ, ref entity, Regen);
      if (((\u0084.\u0001) ((DimensionGroup) refEntities).Solid).Points != null)
        this.Move(dX, dY, dZ, ref ((\u0084.\u0001) ((DimensionGroup) refEntities).Solid).Points);
    }
  }

