  public void Rotate(
    Point3D CenterPoint,
    double Angle,
    Vector3D RotateVector,
    ref List<Point3D> Points)
  {
    try
    {
      Point3D point3D1 = new Point3D();
      Plane plane = Plane.XY;
      if (RotateVector == Vector3D.AxisX | RotateVector == Vector3D.AxisMinusX)
        plane = Plane.YZ;
      if (RotateVector == Vector3D.AxisY | RotateVector == Vector3D.AxisMinusY)
        plane = Plane.XZ;
      for (int index = 0; index <= Points.Count - 1; ++index)
      {
        double num = this.Length3D(Points[index], CenterPoint, plane);
        double Degree = this.PointAngle(Points[index], CenterPoint, plane) + Angle;
        point3D1 = new Point3D();
        if (buVector5.isPlaneXY(plane))
        {
          Point3D point3D2 = F_NotchEdit.ToPoint3D(Points[index]);
          point3D2.X = CenterPoint.X + num * Math.Cos(buString5.DegreeToRadian(Degree));
          point3D2.Y = CenterPoint.Y + num * Math.Sin(buString5.DegreeToRadian(Degree));
          Points[index] = F_NotchEdit.ToPoint3D(point3D2);
        }
        if (buVector5.isPlaneXZ(plane))
        {
          Point3D point3D3 = F_NotchEdit.ToPoint3D(Points[index]);
          point3D3.X = CenterPoint.X + num * Math.Cos(buString5.DegreeToRadian(Degree));
          point3D3.Z = CenterPoint.Z + num * Math.Sin(buString5.DegreeToRadian(Degree));
          Points[index] = F_NotchEdit.ToPoint3D(point3D3);
        }
        if (buVector5.isPlaneYZ(plane))
        {
          Point3D point3D4 = F_NotchEdit.ToPoint3D(Points[index]);
          point3D4.Y = CenterPoint.Y + num * Math.Cos(buString5.DegreeToRadian(Degree));
          point3D4.Z = CenterPoint.Z + num * Math.Sin(buString5.DegreeToRadian(Degree));
          Points[index] = F_NotchEdit.ToPoint3D(point3D4);
        }
      }
    }
    catch (Exception ex)
    {
      string str = $"CenterPoint: {CenterPoint.ToString()} - Angle: {Angle.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

