  public void Rotate(Point3D CenterPoint, double Angle, Plane Plane, ref Point3D Points)
  {
    try
    {
      Point3D point3D1 = new Point3D();
      double num = this.Length3D(Points, CenterPoint, Plane);
      double Degree = this.PointAngle(Points, CenterPoint, Plane) + Angle;
      if (buVector5.isPlaneXYorYX(Plane))
      {
        Point3D point3D2 = F_NotchEdit.ToPoint3D(Points);
        point3D2.X = CenterPoint.X + num * Math.Cos(buString5.DegreeToRadian(Degree));
        point3D2.Y = CenterPoint.Y + num * Math.Sin(buString5.DegreeToRadian(Degree));
        Points = F_NotchEdit.ToPoint3D(point3D2);
      }
      if (buVector5.isPlaneXZorZX(Plane))
      {
        Point3D point3D3 = F_NotchEdit.ToPoint3D(Points);
        point3D3.X = CenterPoint.X + num * Math.Cos(buString5.DegreeToRadian(Degree));
        point3D3.Z = CenterPoint.Z + num * Math.Sin(buString5.DegreeToRadian(Degree));
