  public void Mirror(
    Point3D BasePoint,
    Point3D MirrorPoint,
    Plane planeMirror,
    ref buEntitiesGroup EntGroup)
  {
    if (((\u0084.\u0001) EntGroup.Outside).Entities.Count > 0)
    {
      this.Mirror(BasePoint, MirrorPoint, planeMirror, ref ((\u0084.\u0001) EntGroup.Outside).Entities);
      if (((\u0084.\u0001) EntGroup.Outside).Points != null)
        this.Mirror(BasePoint, MirrorPoint, planeMirror, ref ((\u0084.\u0001) EntGroup.Outside).Points);
    }
    if (((IntersectNode) EntGroup.Outside).pntMassCenter != (Point3D) null)
      this.Mirror(BasePoint, MirrorPoint, planeMirror, ref ((IntersectNode) EntGroup.Outside).pntMassCenter);
    if ((EntGroup.Inside == null ? 0 : (EntGroup.Inside.Count > 0 ? 1 : 0)) != 0)
    {
      for (int index = 0; index <= EntGroup.Inside.Count - 1; ++index)
      {
        this.Mirror(BasePoint, MirrorPoint, planeMirror, ref ((\u0084.\u0001) EntGroup.Inside[index]).Entities);
        if (((\u0084.\u0001) EntGroup.Inside[index]).Points != null)
          this.Mirror(BasePoint, MirrorPoint, planeMirror, ref ((\u0084.\u0001) EntGroup.Inside[index]).Points);
        if (((IntersectNode) EntGroup.Inside[index]).pntMassCenter != (Point3D) null)
          this.Mirror(BasePoint, MirrorPoint, planeMirror, ref ((IntersectNode) EntGroup.Inside[index]).pntMassCenter);
      }
    }
    if ((EntGroup.OpenEntities == null ? 0 : (EntGroup.OpenEntities.Count > 0 ? 1 : 0)) != 0)
    {
      for (int index = 0; index <= EntGroup.OpenEntities.Count - 1; ++index)
      {
        this.Mirror(BasePoint, MirrorPoint, planeMirror, ref ((\u0084.\u0001) EntGroup.OpenEntities[index]).Entities);
        if (((\u0084.\u0001) EntGroup.OpenEntities[index]).Points != null)
          this.Mirror(BasePoint, MirrorPoint, planeMirror, ref ((\u0084.\u0001) EntGroup.OpenEntities[index]).Points);
        if (((IntersectNode) EntGroup.OpenEntities[index]).pntMassCenter != (Point3D) null)
          this.Mirror(BasePoint, MirrorPoint, planeMirror, ref ((IntersectNode) EntGroup.OpenEntities[index]).pntMassCenter);
      }
    }
    if ((((DimensionGroup) EntGroup).Text == null ? 0 : (((\u0084.\u0001) ((DimensionGroup) EntGroup).Text).Entities.Count > 0 ? 1 : 0)) != 0)
    {
