  public void MirrorCornerLocation(
    CornerLocation baseCorner,
    VectorXYType MirrorVector,
    ref CornerLocation mirroredCorner)
  {
    switch (MirrorVector)
    {
      case VectorXYType.XVector:
        switch (baseCorner)
        {
          case CornerLocation.LeftTop:
            mirroredCorner = CornerLocation.LeftBottom;
            return;
          case CornerLocation.LeftBottom:
            mirroredCorner = CornerLocation.LeftTop;
            return;
          case CornerLocation.RightTop:
            mirroredCorner = CornerLocation.RightBottom;
            return;
          case CornerLocation.RightBottom:
            mirroredCorner = CornerLocation.RightTop;
            return;
          case CornerLocation.LeftCenter:
            mirroredCorner = CornerLocation.LeftCenter;
            return;
          case CornerLocation.RightCenter:
            mirroredCorner = CornerLocation.RightCenter;
            return;
          case CornerLocation.TopCenter:
            mirroredCorner = CornerLocation.BottomCenter;
            return;
          case CornerLocation.BottomCenter:
            mirroredCorner = CornerLocation.TopCenter;
            return;
          default:
            return;
        }
      case VectorXYType.YVector:
        if (baseCorner == CornerLocation.LeftTop)
        {
          mirroredCorner = CornerLocation.RightTop;
          break;
        }
        if (baseCorner == CornerLocation.LeftBottom)
        {
          mirroredCorner = CornerLocation.RightBottom;
          break;
        }
        if (baseCorner == CornerLocation.LeftCenter)
        {
          mirroredCorner = CornerLocation.RightCenter;
          break;
        }
        if (baseCorner == CornerLocation.RightTop)
        {
          mirroredCorner = CornerLocation.LeftTop;
          break;
        }
        if (baseCorner == CornerLocation.RightBottom)
        {
          mirroredCorner = CornerLocation.LeftBottom;
          break;
        }
        if (baseCorner == CornerLocation.RightCenter)
        {
          mirroredCorner = CornerLocation.LeftCenter;
          break;
        }
        if (baseCorner == CornerLocation.TopCenter)
        {
          mirroredCorner = CornerLocation.TopCenter;
          break;
        }
        if (baseCorner == CornerLocation.BottomCenter)
        {
          mirroredCorner = CornerLocation.BottomCenter;
          break;
        }
        if (baseCorner == CornerLocation.LeftCenter)
        {
          mirroredCorner = CornerLocation.LeftCenter;
          break;
        }
        if (baseCorner != CornerLocation.RightCenter)
          break;
        mirroredCorner = CornerLocation.RightCenter;
        break;
    }
  }

