            {
              if (SelectionList[index1][index4] >= 0 & SelectionList[index1][index4] <= refEntities.Count - 1)
              {
                refEntities[SelectionList[index1][index4]].Translate(dx, 0.0);
                refEntities[SelectionList[index1][index4]].Regen(0.01);
              }
            }
          }
          if (Alignment == AlignmentEvent.Top)
          {
            double dy = MaxPoint1.Y - MaxPoint2.Y;
            for (int index5 = 0; index5 <= SelectionList[index1].Count - 1; ++index5)
            {
              if (SelectionList[index1][index5] >= 0 & SelectionList[index1][index5] <= refEntities.Count - 1)
              {
                refEntities[SelectionList[index1][index5]].Translate(0.0, dy);
                refEntities[SelectionList[index1][index5]].Regen(0.01);
              }
            }
          }
          if (Alignment == AlignmentEvent.Bottom)
          {
            double dy = MinPoint1.Y - MinPoint2.Y;
            for (int index6 = 0; index6 <= SelectionList[index1].Count - 1; ++index6)
            {
              if (SelectionList[index1][index6] >= 0 & SelectionList[index1][index6] <= refEntities.Count - 1)
              {
                refEntities[SelectionList[index1][index6]].Translate(0.0, dy);
                refEntities[SelectionList[index1][index6]].Regen(0.01);
              }
            }
          }
          if (Alignment == AlignmentEvent.HorizontalCenter)
          {
            double dy = MidPoint1.Y - MidPoint2.Y;
            for (int index7 = 0; index7 <= SelectionList[index1].Count - 1; ++index7)
            {
              if (SelectionList[index1][index7] >= 0 & SelectionList[index1][index7] <= refEntities.Count - 1)
              {
                refEntities[SelectionList[index1][index7]].Translate(0.0, dy);
                refEntities[SelectionList[index1][index7]].Regen(0.01);
              }
            }
