          if (Alignment == AlignmentEvent.VerticalCenter)
          {
            double dx = MidPoint1.X - MidPoint2.X;
            for (int index8 = 0; index8 <= SelectionList[index1].Count - 1; ++index8)
            {
              if (SelectionList[index1][index8] >= 0 & SelectionList[index1][index8] <= refEntities.Count - 1)
