  public void FilletPointList(
    List<Point3D> refPoints,
    double FilletRadius,
    Plane refPlane,
    ref List<Point3D> filletedPoints)
  {
    bool flag = false;
    if (filletedPoints == null)
      filletedPoints = new List<Point3D>();
    filletedPoints.Clear();
    for (int index = 1; index <= refPoints.Count - 1; ++index)
    {
      if (Point3D.Distance(refPoints[index - 1], refPoints[index]) < FilletRadius)
        flag = true;
    }
    if (flag)
      buVector5.Copy(refPoints, ref filletedPoints);
    else if (FilletRadius <= 0.0)
    {
      buVector5.Copy(refPoints, ref filletedPoints);
    }
    else
    {
      filletedPoints.Add(F_NotchEdit.ToPoint3D(refPoints[0]));
      for (int index1 = 1; index1 <= refPoints.Count - 2; ++index1)
      {
        Line line1 = new Line(refPoints[index1 - 1], refPoints[index1]);
        Line line2 = new Line(refPoints[index1], refPoints[index1 + 1]);
        ICurve C1 = (ICurve) line1;
        ICurve C2 = (ICurve) line2;
        Arc fillet = (Arc) null;
        if (line1.Direction == line2.Direction)
        {
          filletedPoints.Add(F_NotchEdit.ToPoint3D(refPoints[index1]));
        }
        else
        {
          Curve.Fillet(C1, C2, refPlane.AxisZ, FilletRadius, false, false, true, true, out fillet);
          if (fillet == null)
            Curve.Fillet(C1, C2, refPlane.AxisZ, FilletRadius, true, false, true, true, out fillet);
          if (fillet == null)
            Curve.Fillet(C1, C2, refPlane.AxisZ, FilletRadius, false, true, true, true, out fillet);
          if (fillet == null)
            Curve.Fillet(C1, C2, refPlane.AxisZ, FilletRadius, true, true, true, true, out fillet);
          if (fillet != null)
          {
            if (fillet.Vertices == null)
            {
              double deviation = this.RegenDevisionFromRadius(fillet.Radius);
              fillet.Regen(deviation);
            }
            filletedPoints.Add(F_NotchEdit.ToPoint3D(line1.EndPoint));
            for (int index2 = 1; index2 <= fillet.Vertices.Length - 2; ++index2)
              filletedPoints.Add(F_NotchEdit.ToPoint3D(fillet.Vertices[index2]));
            filletedPoints.Add(F_NotchEdit.ToPoint3D(line2.StartPoint));
          }
          else
            filletedPoints.Add(F_NotchEdit.ToPoint3D(refPoints[index1]));
        }
      }
      filletedPoints.Add(F_NotchEdit.ToPoint3D(refPoints[refPoints.Count - 1]));
      ((F_CutterMachineSettings) this).CheckDuplicatedPointsWithPrevious(ref filletedPoints);
    }
  }

