  public static double PointAngleByPlane(Point3D TipPoint, Point3D BasePoint, Plane RefPlane)
  {
    try
    {
      Vector3D asVector = (TipPoint - BasePoint).AsVector;
      Math.Sqrt(asVector.X * asVector.X + asVector.Y * asVector.Y);
      Math.Sqrt(asVector.X * asVector.X + asVector.Z * asVector.Z);
      Math.Sqrt(asVector.Y * asVector.Y + asVector.Z * asVector.Z);
      double deg1 = Utility.RadToDeg(Math.Atan2(asVector.Y, asVector.X));
      if (Math.Round(deg1, 5) < 0.0)
        deg1 += 360.0;
      double deg2 = Utility.RadToDeg(Math.Atan2(asVector.Z, asVector.X));
      if (Math.Round(deg2, 5) < 0.0)
        deg2 += 360.0;
      double deg3 = Utility.RadToDeg(Math.Atan2(asVector.Z, asVector.Y));
      if (Math.Round(deg3, 5) < 0.0)
        deg3 += 360.0;
      if (buVector5.isPlaneXZorZX(RefPlane))
        return deg2;
      return buVector5.isPlaneYZorZY(RefPlane) ? deg3 : deg1;
    }
    catch (Exception ex)
    {
      string str = "";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

