  public double AngleOfTwoLines(
    Point3D FirstLineStart,
    Point3D FirstLineEnd,
    Point3D SecondLineStart,
    Point3D SecondLineEnd,
    Plane Plane)
  {
    try
    {
      Point3D point3D1 = new Point3D();
      Point3D point3D2 = new Point3D();
      Point3D pntIntersect = new Point3D();
      Line line1 = new Line(FirstLineStart, FirstLineEnd);
      Line line2 = new Line(SecondLineStart, SecondLineEnd);
      if (!this.LineLineIntersection(FirstLineStart, FirstLineEnd, SecondLineStart, SecondLineEnd, Plane, ref pntIntersect))
        return 180.0;
      double num1 = Point3D.Distance(FirstLineStart, pntIntersect);
      double num2 = Point3D.Distance(FirstLineEnd, pntIntersect);
      double num3 = Point3D.Distance(SecondLineStart, pntIntersect);
      double num4 = Point3D.Distance(SecondLineEnd, pntIntersect);
      Point3D TipPoint1 = num1 <= num2 ? new Point3D(FirstLineEnd.X, FirstLineEnd.Y, FirstLineEnd.Z) : new Point3D(FirstLineStart.X, FirstLineStart.Y, FirstLineStart.Z);
      Point3D TipPoint2 = num3 <= num4 ? new Point3D(SecondLineEnd.X, SecondLineEnd.Y, SecondLineEnd.Z) : new Point3D(SecondLineStart.X, SecondLineStart.Y, SecondLineStart.Z);
      double num5 = Math.Abs(this.PointAngle(TipPoint1, pntIntersect, Plane) - this.PointAngle(TipPoint2, pntIntersect, Plane));
      if (num5 > 180.0)
        num5 = 360.0 - num5;
      return num5;
    }
    catch (Exception ex)
    {
      string str = $"FirstLineStart: {FirstLineStart.ToString()} - FirstLineEnd: {FirstLineEnd.ToString()} - SecondLineStart: {SecondLineStart.ToString()} - SecondLineEnd: {SecondLineEnd.ToString()} - Plane: {Plane.ToString()}";
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
      return 0.0;
    }
  }

  public double PlaneAngleYZ(Plane plane)
  {
    double num1 = 0.0;
    num1 = buString5.RadianToDegree(plane.Equation.Angle);
    double num2 = this.PointAngle(new Point3D(plane.AxisY.X, plane.AxisY.Y, plane.AxisY.Z), new Point3D(), Plane.YZ) - 90.0;
    if (num2 > 180.0)
      num2 -= 180.0;
    return num2;
  }

  public static Plane WorkPlaneToPlane(WorkPlane plane)
  {
    return plane.PlaneName != planeNames.Top ? (plane.PlaneName != planeNames.Bottom ? (plane.PlaneName != planeNames.Front ? (plane.PlaneName != planeNames.Back ? (plane.PlaneName != planeNames.Right ? (plane.PlaneName != planeNames.Left ? new Plane(new Vector3D(plane.Normalies.X, plane.Normalies.Y, plane.Normalies.Z)) : Plane.ZY) : Plane.YZ) : new Plane(new Point3D(0.0, 0.0, 0.0), new Point3D(1.0, 0.0, 0.0), new Point3D(0.0, 0.0, -1.0))) : new Plane(new Point3D(0.0, 0.0, 0.0), new Point3D(1.0, 0.0, 0.0), new Point3D(0.0, 0.0, 1.0))) : Plane.YX) : Plane.XY;
