  public static WorkPlane PlaneToWorkPlane(Plane plane)
  {
    WorkPlane workPlane = new WorkPlane(new Vec3D(plane.Equation.X, plane.Equation.Y, plane.Equation.Z));
    if (buVector5.isPlaneXY(plane))
    {
      workPlane.PlaneName = planeNames.Top;
      workPlane.PlaneType = planeType.XY;
    }
    else if (buVector5.isPlaneYX(plane))
    {
      workPlane.PlaneName = planeNames.Bottom;
      workPlane.PlaneType = planeType.YX;
    }
    else if (buVector5.isPlaneXZ(plane))
    {
      workPlane.PlaneName = planeNames.Front;
      workPlane.PlaneType = planeType.XZ;
    }
    else if (buVector5.isPlaneZX(plane))
    {
      workPlane.PlaneName = planeNames.Back;
      workPlane.PlaneType = planeType.ZX;
    }
    else if (buVector5.isPlaneYZ(plane))
    {
      workPlane.PlaneName = planeNames.Right;
      workPlane.PlaneType = planeType.YZ;
    }
    else if (buVector5.isPlaneZY(plane))
    {
      workPlane.PlaneName = planeNames.Left;
      workPlane.PlaneType = planeType.ZY;
    }
    else
    {
      workPlane.PlaneName = planeNames.Free;
      workPlane.PlaneType = planeType.Angle;
    }
    return workPlane;
  }

