  public void PlaneNameToPlane(planeBoxNames planeName, ref Plane refPlane)
  {
    if (planeName == planeBoxNames.Top)
      refPlane = Plane.XY;
    if (planeName == planeBoxNames.Bottom)
      refPlane = Plane.XY;
    if (planeName == planeBoxNames.Front)
      refPlane = Plane.XZ;
    if (planeName == planeBoxNames.Back)
      refPlane = Plane.XZ;
    if (planeName == planeBoxNames.Left)
      refPlane = Plane.YZ;
    if (planeName != planeBoxNames.Right)
      return;
    refPlane = Plane.YZ;
  }

