    ((ShapeUpdateArg) ((ShapeArray) Settings).Option).NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
    for (int index = 0; index <= refEntities.Count - 1; ++index)
    {
      List<buEntity> SortedEntities = new List<buEntity>();
      this.SortEntitiesByRefPoint(((CustomData) refEntities[index]).StartPoint, ref refEntities, Settings, ref SortedEntities);
      List<List<buEntity>> SplitedEntitites = new List<List<buEntity>>();
      this.EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
      if (SplitedEntitites.Count == 1)
      {
        buRadialDim.Copy(SortedEntities, ref sortedEntities);
        index = refEntities.Count;
      }
    }
    if (sortedEntities.Count != 0)
      return;
    for (int index = 0; index <= refEntities.Count - 1; ++index)
    {
      List<buEntity> SortedEntities = new List<buEntity>();
      this.SortEntitiesByRefPoint(((CustomData) refEntities[index]).EndPoint, ref refEntities, Settings, ref SortedEntities);
