  public void SortDeltaX(
    Point3D RefPoint,
    SortDirectionType Direction,
    ref List<Point3D> SortingPoints)
  {
    try
    {
      for (int index1 = 0; index1 < SortingPoints.Count - 1; ++index1)
      {
        for (int index2 = 1; index2 < SortingPoints.Count - index1; ++index2)
        {
          if (this.DeltaX(RefPoint, SortingPoints[index2]) < this.DeltaX(RefPoint, SortingPoints[index2 - 1]))
          {
            Point3D point3D = F_NotchEdit.ToPoint3D(SortingPoints[index2 - 1]);
            SortingPoints[index2 - 1] = F_NotchEdit.ToPoint3D(SortingPoints[index2]);
            SortingPoints[index2] = F_NotchEdit.ToPoint3D(point3D);
