  public List<Point3D> SortByDistance(Point3D refPoint, List<Point3D> lst)
  {
    List<Point3D> point3DList = new List<Point3D>();
    point3DList.Add(lst[this.NearestPoint(refPoint, lst)]);
    lst.Remove(point3DList[0]);
    int num = 0;
    for (int index = 0; index < lst.Count + num; ++index)
    {
      point3DList.Add(lst[this.NearestPoint(point3DList[point3DList.Count - 1], lst)]);
      lst.Remove(point3DList[point3DList.Count - 1]);
      ++num;
    }
    return point3DList;
  }

