  public void FindInternalEntitiesAtClosedContour(
    List<Point3D> ClosedContour,
    List<Entity> Entities,
    Plane refPlane,
    ref List<List<Entity>> ClosedEntities,
    ref List<List<Entity>> NotClosedEntities)
  {
    List<List<Point3D>> ClosedPoints = new List<List<Point3D>>();
    this.FindInternalEntitiesAtClosedContour(ClosedContour, Entities, refPlane, ref ClosedEntities, ref ClosedPoints, ref NotClosedEntities);
  }

  public void FindInternalEntitiesAtClosedContour(
    List<Point3D> ClosedContour,
    List<Entity> Entities,
    Plane refPlane,
    ref List<List<Entity>> ClosedEntities,
    ref List<List<Point3D>> ClosedPoints,
    ref List<List<Entity>> NotClosedEntities)
  {
    try
    {
      List<Entity> BaseRefEntities = new List<Entity>();
      List<Entity> SortedEntities = new List<Entity>();
      List<List<Entity>> SplitedEntitites = new List<List<Entity>>();
      SortSettings Settings = (SortSettings) new ShapeRuntimeData();
      Point3D MinPoint = new Point3D();
      Point3D MidPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      this.BoxSizeCalculate(ClosedContour, ref MinPoint, ref MidPoint, ref MaxPoint);
      ((SortbuOptions) ((SortbuFilter) Settings).Option).NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
      ((SortbuOptions) ((SortbuFilter) Settings).Option).IntersectionRules = SortingIntersectionRulesType.LowerIndex;
      for (int index1 = 0; index1 <= Entities.Count - 1; ++index1)
      {
        if (Entities[index1].BoxMax == (Point3D) null)
          Entities[index1].Regen(buSystem.RegenDeviation);
        if (Entities[index1].Visible)
        {
          bool flag1 = this.IsPointInsideWindow(MinPoint, MaxPoint, Entities[index1].BoxMin, refPlane, false);
          bool flag2 = this.IsPointInsideWindow(MinPoint, MaxPoint, Entities[index1].BoxMax, refPlane, false);
          bool flag3 = flag1 & flag2;
          if (flag1 & flag2)
          {
            for (int index2 = 0; index2 <= Entities[index1].Vertices.Length - 1; ++index2)
            {
              bool flag4 = ((F_EntitiesProps) this).IsPointInsidePolygon(ClosedContour, Entities[index1].Vertices[index2]);
              flag3 &= flag4;
            }
          }
          if (flag3)
          {
            bool flag5 = true;
            if (Entities[index1] is devDept.Eyeshot.Entities.Point)
              flag5 = false;
            if (flag5)
              BaseRefEntities.Add(buVector5.CopyEntities(Entities[index1]));
          }
        }
      }
      if (BaseRefEntities.Count > 0)
      {
        SortResult Result = (SortResult) new CurveToSurfaceSettingsType();
        this.SortEntitiesByRefPoint(BaseRefEntities[0].Vertices[0], ref BaseRefEntities, Settings, ref SortedEntities, ref Result);
      }
      this.EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
      for (int index = 0; index <= SplitedEntitites.Count - 1; ++index)
      {
        if (((F_DeleteType) this).IsEntitiesClosedPath(SplitedEntitites[index]))
        {
          List<Entity> copiedEnt = new List<Entity>();
          buVector5.CopyEntities(SplitedEntitites[index], ref copiedEnt);
          ClosedEntities.Add(copiedEnt);
          List<Point3D> Points = new List<Point3D>();
          this.EntitiesToPointsWithCamDirection(SplitedEntitites[index], buSystem.RegenDeviation, ref Points);
          ((F_CutterMachineSettings) this).CheckDuplicatedPointsWithPrevious(0.01, ref Points);
          ClosedPoints.Add(Points);
        }
        else
        {
          List<Entity> copiedEnt = new List<Entity>();
          buVector5.CopyEntities(SplitedEntitites[index], ref copiedEnt);
          NotClosedEntities.Add(copiedEnt);
        }
      }
    }
    catch (Exception ex)
    {
      string[] strArray = new string[6];
      strArray[0] = "ClosedContour: ";
