  public void FindInternalEntitiesAtClosedContour(
    List<Point3D> ClosedContour,
    List<buEntity> Entities,
    Plane refPlane,
    ref List<List<buEntity>> ClosedEntities,
    ref List<List<Point3D>> ClosedPoints,
    ref List<List<buEntity>> NotClosedEntities)
  {
    try
    {
      List<buEntity> BaseRefEntities = new List<buEntity>();
      List<buEntity> SortedEntities = new List<buEntity>();
      List<List<buEntity>> SplitedEntitites = new List<List<buEntity>>();
      SortbuSettings Settings = (SortbuSettings) new MeasureItem();
      Point3D MinPoint = new Point3D();
      Point3D MidPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      this.BoxSizeCalculate(ClosedContour, ref MinPoint, ref MidPoint, ref MaxPoint);
      ((ShapeUpdateArg) ((ShapeArray) Settings).Option).NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
      ((ShapeUpdateArg) ((ShapeArray) Settings).Option).IntersectionRules = SortingIntersectionRulesType.LowerIndex;
      for (int index1 = 0; index1 <= Entities.Count - 1; ++index1)
      {
        buEntity entity = Entities[index1];
        bool flag1 = this.IsPointInsideWindow(MinPoint, MaxPoint, ((CustomData) Entities[index1]).BoxMin, refPlane, false);
        bool flag2 = this.IsPointInsideWindow(MinPoint, MaxPoint, ((CustomData) Entities[index1]).BoxMax, refPlane, false);
        bool flag3 = flag1 & flag2;
        if (flag1 & flag2)
        {
          for (int index2 = 0; index2 <= ((CustomDataSurrogate) Entities[index1]).Vertices.Count - 1; ++index2)
          {
            bool flag4 = ((F_EntitiesProps) this).IsPointInsidePolygon(ClosedContour, ((CustomDataSurrogate) Entities[index1]).Vertices[index2]);
            flag3 &= flag4;
          }
        }
        if (flag3)
        {
          bool flag5 = true;
          if (Entities[index1] is buPoint)
            flag5 = false;
          if (flag5)
            BaseRefEntities.Add(buAngularDim.Copy(Entities[index1]));
        }
      }
      if (BaseRefEntities.Count > 0)
      {
        SortbuResult Result = (SortbuResult) new MachineConfigSettings();
        this.SortEntitiesByRefPoint(((CustomDataSurrogate) BaseRefEntities[0]).Vertices[0], ref BaseRefEntities, Settings, ref SortedEntities, ref Result);
      }
      this.EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
      for (int index = 0; index <= SplitedEntitites.Count - 1; ++index)
      {
        if (((F_DeleteType) this).IsEntitiesClosedPath(SplitedEntitites[index]))
        {
          List<buEntity> copiedEntities = new List<buEntity>();
          buRadialDim.Copy(SplitedEntitites[index], ref copiedEntities);
          ClosedEntities.Add(copiedEntities);
          List<Point3D> Points = new List<Point3D>();
          this.EntitiesToPointsWithCamDirection(SplitedEntitites[index], buSystem.RegenDeviation, ref Points);
          ((F_CutterMachineSettings) this).CheckDuplicatedPointsWithPrevious(0.01, ref Points);
          ClosedPoints.Add(Points);
        }
        else
        {
          List<buEntity> copiedEntities = new List<buEntity>();
          buRadialDim.Copy(SplitedEntitites[index], ref copiedEntities);
          NotClosedEntities.Add(copiedEntities);
        }
      }
    }
    catch (Exception ex)
    {
      string[] strArray = new string[6];
      strArray[0] = "ClosedContour: ";
      int count = ClosedContour.Count;
      strArray[1] = count.ToString();
      strArray[2] = " - Entities: ";
      count = Entities.Count;
      strArray[3] = count.ToString();
      strArray[4] = " - Plane: ";
      strArray[5] = refPlane.ToString();
      string str = string.Concat(strArray);
      buLog.addLog(str, "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, false, str);
    }
  }

  public void FindInternalEntitiesFromEntitiesMethodBoxBounding(
    List<buEntity> OutsidesEntities,
    List<buEntity> InsideEntities,
    Plane refPlane,
    ref List<buEntity> FoundInsideEntities,
    double SortResolution = 0.05)
  {
    try
    {
      List<buEntity> copiedEntities = new List<buEntity>();
      buRadialDim.Copy(InsideEntities, ref copiedEntities);
      Point3D MinPoint1 = new Point3D();
      Point3D MidPoint1 = new Point3D();
      Point3D MaxPoint1 = new Point3D();
      this.BoxSizeCalculate(OutsidesEntities, ref MinPoint1, ref MidPoint1, ref MaxPoint1);
      for (int index = copiedEntities.Count - 1; index >= 0; --index)
      {
        Point3D MinPoint2 = new Point3D();
        Point3D MidPoint2 = new Point3D();
        Point3D MaxPoint2 = new Point3D();
        this.BoxSizeCalculate(copiedEntities[index], ref MinPoint2, ref MidPoint2, ref MaxPoint2);
        if (this.isBoxSizeInsideBoxSize(MinPoint1, MaxPoint1, MinPoint2, MaxPoint2, refPlane))
        {
          buEntity copiedEntity = (buEntity) null;
          buDiametricDim.Copy(copiedEntities[index], ref copiedEntity);
          if (copiedEntity != null)
            FoundInsideEntities.Add(copiedEntity);
          copiedEntities.RemoveAt(index);
        }
      }
    }
    catch (Exception ex)
    {
    }
  }

