  public void FindOutsideAndInsidentitiesFromEntities(
    Point3D RefPoint,
    List<Entity> AllEntities,
    Plane refPlane,
    ref List<Entity> OutsideEntities,
    ref List<List<Entity>> InsideEntities,
    ref List<List<Entity>> NotInsideEntities)
  {
    double num1 = double.MinValue;
    double num2 = double.MinValue;
    int index1 = -1;
    SortSettings Settings = (SortSettings) new ShapeRuntimeData();
    SortResult Result = (SortResult) new CurveToSurfaceSettingsType();
    ((SortbuOptions) ((SortbuFilter) Settings).Option).IntersectionRules = SortingIntersectionRulesType.LowerIndex;
    ((SortbuOptions) ((SortbuFilter) Settings).Option).NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
    List<Entity> SortedEntities = new List<Entity>();
    List<List<Entity>> SplitedEntitites = new List<List<Entity>>();
    this.SortEntitiesByRefPoint(RefPoint, ref AllEntities, Settings, ref SortedEntities, ref Result);
    this.EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
    for (int index2 = 0; index2 <= SplitedEntitites.Count - 1; ++index2)
    {
      Point3D MinPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      this.BoxSizeCalculate(SplitedEntitites[index2], ref MinPoint, ref MaxPoint);
      double num3 = MaxPoint.X - MinPoint.X;
      double num4 = MaxPoint.Y - MinPoint.Y;
      if (num3 > num1 & num4 > num2)
      {
        num1 = num3;
        num2 = num4;
        index1 = index2;
      }
    }
    if (index1 < 0)
      return;
    buVector5.CopyEntities(SplitedEntitites[index1], ref OutsideEntities);
    SplitedEntitites.RemoveAt(index1);
    this.isVerticesNull(buSystem.RegenDeviation, ref OutsideEntities);
    Point3D MinPoint1 = new Point3D();
    Point3D MaxPoint1 = new Point3D();
    this.BoxSizeCalculate(OutsideEntities, ref MinPoint1, ref MaxPoint1);
    List<Point3D> Points = new List<Point3D>();
    this.EntitiesToPointsWithCamDirection(OutsideEntities, buSystem.RegenDeviation, ref Points);
    for (int index3 = 0; index3 <= SplitedEntitites.Count - 1; ++index3)
    {
      Point3D MinPoint2 = new Point3D();
      Point3D MaxPoint2 = new Point3D();
      this.BoxSizeCalculate(SplitedEntitites[index3], ref MinPoint2, ref MaxPoint2);
      if (this.isBoxSizeInsideBoxSize(MinPoint1, MaxPoint1, MinPoint2, MaxPoint2, refPlane))
      {
        bool flag = true;
        for (int index4 = 0; index4 <= SplitedEntitites[index3].Count - 1; ++index4)
        {
          Entity entity = SplitedEntitites[index3][index4];
          if (entity.Vertices == null)
            entity.Regen(new RegenParams(buSystem.RegenDeviation));
          for (int index5 = 0; index5 <= entity.Vertices.Length - 1; ++index5)
          {
            if (!((F_EntitiesProps) this).IsPointInsidePolygon(Points, entity.Vertices[index5]))
            {
              flag = false;
              index5 = entity.Vertices.Length;
            }
          }
        }
        if (flag)
        {
          List<Entity> copiedEnt = new List<Entity>();
          buVector5.CopyEntities(SplitedEntitites[index3], ref copiedEnt);
          InsideEntities.Add(copiedEnt);
        }
        else
        {
          List<Entity> copiedEnt = new List<Entity>();
          buVector5.CopyEntities(SplitedEntitites[index3], ref copiedEnt);
          NotInsideEntities.Add(copiedEnt);
        }
      }
      else
      {
        List<Entity> copiedEnt = new List<Entity>();
        buVector5.CopyEntities(SplitedEntitites[index3], ref copiedEnt);
        NotInsideEntities.Add(copiedEnt);
      }
    }
  }

  public void FindEntitiesGroupFromEntities(
    Point3D RefPoint,
    List<Entity> AllEntities,
    Plane refPlane,
    ref List<EntitiesGroup> Groups,
    double SortResolution = 0.05)
  {
    SortSettings Settings = (SortSettings) new ShapeRuntimeData();
    SortResult Result = (SortResult) new CurveToSurfaceSettingsType();
    ((SortbuOptions) ((SortbuFilter) Settings).Option).IntersectionRules = SortingIntersectionRulesType.LowerIndex;
    ((SortbuOptions) ((SortbuFilter) Settings).Option).NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
    ((SortbuOptions) ((SortbuFilter) Settings).Option).Resolution = SortResolution;
    List<Entity> SortedEntities = new List<Entity>();
    List<List<Entity>> SplitedEntitites = new List<List<Entity>>();
    List<List<Entity>> entityListList1 = new List<List<Entity>>();
    List<List<Entity>> entityListList2 = new List<List<Entity>>();
    if (Groups == null)
      Groups = new List<EntitiesGroup>();
    Groups.Clear();
    Groups = new List<EntitiesGroup>();
    this.SortEntitiesByRefPoint(RefPoint, ref AllEntities, Settings, ref SortedEntities, ref Result);
    this.EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
    F_ProgressCalculation progressCalculation = new F_ProgressCalculation();
    progressCalculation.TopMost = true;
    progressCalculation.Show();
    for (int index = 0; index <= SplitedEntitites.Count - 1; ++index)
    {
      if (((F_AnalyseResult) this).isEntitiesClosed(SplitedEntitites[index]))
        entityListList1.Add(buVector5.CopyEntities(SplitedEntitites[index]));
      else
        entityListList2.Add(buVector5.CopyEntities(SplitedEntitites[index]));
    }
    SplitedEntitites.Clear();
    if (entityListList1.Count > 0)
    {
      List<bool> boolList = new List<bool>();
      List<List<Entity>> entityListList3 = new List<List<Entity>>();
      List<List<Entity>> entityListList4 = new List<List<Entity>>();
      for (int index1 = 0; index1 <= entityListList1.Count - 1; ++index1)
      {
        List<Point3D> Points1 = new List<Point3D>();
        this.EntitiesToPointsWithCamDirection(entityListList1[index1], 0.05, ref Points1);
        bool flag = false;
        for (int index2 = 0; index2 <= entityListList1.Count - 1; ++index2)
        {
          if (index1 != index2)
          {
            for (int index3 = 0; index3 <= entityListList1[index2].Count - 1; ++index3)
            {
              List<Point3D> Points2 = new List<Point3D>();
              this.EntitiesToPointsWithCamDirection(entityListList1[index2], 0.05, ref Points2);
              for (int index4 = 0; index4 <= Points1.Count - 1; ++index4)
              {
                if (((F_EntitiesProps) this).IsPointInsidePolygon(Points2, Points1[index4], Plane.XY, false))
                {
                  index4 = Points1.Count;
                  flag = true;
                }
              }
              if (flag)
                index3 = entityListList1[index2].Count;
            }
          }
        }
        if (!flag)
        {
          List<Point3D> Points3 = new List<Point3D>();
          this.EntitiesToPointsWithCamDirection(entityListList1[index1], 0.05, ref Points3);
          if (Points3.Count >= 3)
            entityListList3.Add(entityListList1[index1]);
        }
        else
        {
          List<Point3D> Points4 = new List<Point3D>();
          this.EntitiesToPointsWithCamDirection(entityListList1[index1], 0.05, ref Points4);
          if (Points4.Count >= 3)
            entityListList4.Add(entityListList1[index1]);
        }
        progressCalculation.Init((double) index1 / (double) (entityListList1.Count - 1) * 100.0, 25.0, "Analyse Outside");
        progressCalculation.Refresh();
      }
      for (int index5 = 0; index5 <= entityListList3.Count - 1; ++index5)
      {
        EntitiesGroup entitiesGroup = (EntitiesGroup) new buEntitiesGroup();
        buRadialDim.Copy(entityListList3[index5], ref ((buEntitiesGroup) entitiesGroup).Outside);
        List<Point3D> Points5 = new List<Point3D>();
        this.EntitiesToPointsWithCamDirection(entityListList3[index5], 0.05, ref Points5);
        Point3D MinPoint1 = new Point3D();
        Point3D MidPoint1 = new Point3D();
        Point3D MaxPoint1 = new Point3D();
        this.BoxSizeCalculate(entityListList3[index5], ref MinPoint1, ref MidPoint1, ref MaxPoint1);
        for (int index6 = entityListList4.Count - 1; index6 >= 0; --index6)
        {
          Point3D MinPoint2 = new Point3D();
          Point3D MidPoint2 = new Point3D();
          Point3D MaxPoint2 = new Point3D();
          this.BoxSizeCalculate(entityListList4[index6], ref MinPoint2, ref MidPoint2, ref MaxPoint2);
          bool flag = this.isBoxSizeInsideBoxSize(MinPoint1, MaxPoint1, MinPoint2, MaxPoint2, refPlane);
          List<Point3D> Points6 = new List<Point3D>();
          this.EntitiesToPointsWithCamDirection(entityListList4[index6], 0.05, ref Points6);
          for (int index7 = 0; index7 <= Points6.Count - 1; ++index7)
          {
            if (flag = ((F_EntitiesProps) this).IsPointInsidePolygon(Points5, Points6[index7], Plane.XY, false))
              index7 = Points6.Count;
          }
          if (flag)
          {
            List<Entity> copiedEntity = new List<Entity>();
            buRadialDim.Copy(entityListList4[index6], ref copiedEntity);
            ((buEntitiesGroup) entitiesGroup).Inside.Add(copiedEntity);
            entityListList4.RemoveAt(index6);
          }
        }
        for (int index8 = entityListList2.Count - 1; index8 >= 0; --index8)
        {
          Point3D MinPoint3 = new Point3D();
          Point3D MidPoint3 = new Point3D();
          Point3D MaxPoint3 = new Point3D();
          this.BoxSizeCalculate(entityListList2[index8], ref MinPoint3, ref MidPoint3, ref MaxPoint3);
          if (this.isBoxSizeInsideBoxSize(MinPoint1, MaxPoint1, MinPoint3, MaxPoint3, refPlane))
          {
            List<Entity> copiedEntity = new List<Entity>();
            buRadialDim.Copy(entityListList2[index8], ref copiedEntity);
            ((buEntitiesGroup) entitiesGroup).Inside.Add(copiedEntity);
            entityListList2.RemoveAt(index8);
          }
        }
        Groups.Add(entitiesGroup);
        progressCalculation.Init((double) index5 / (double) (entityListList1.Count - 1) * 100.0, 50.0, "Set Entities");
        progressCalculation.Refresh();
      }
      progressCalculation.Dispose();
    }
    else
    {
      EntitiesGroup entitiesGroup = (EntitiesGroup) new buEntitiesGroup();
      for (int index = 0; index <= entityListList2.Count - 1; ++index)
      {
        List<Entity> copiedEntity = new List<Entity>();
        buRadialDim.Copy(entityListList2[index], ref copiedEntity);
        ((buEntitiesGroup) entitiesGroup).Inside.Add(copiedEntity);
      }
      Groups.Add(entitiesGroup);
      progressCalculation.Dispose();
    }
  }

  public void FindEntitiesGroupFromEntities1(
    Point3D RefPoint,
    List<Entity> AllEntities,
    Plane refPlane,
    ref List<EntitiesGroup> Groups)
  {
    SortSettings Settings = (SortSettings) new ShapeRuntimeData();
    SortResult Result = (SortResult) new CurveToSurfaceSettingsType();
    ((SortbuOptions) ((SortbuFilter) Settings).Option).IntersectionRules = SortingIntersectionRulesType.LowerIndex;
    ((SortbuOptions) ((SortbuFilter) Settings).Option).NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
    List<Entity> SortedEntities = new List<Entity>();
    List<List<Entity>> SplitedEntitites = new List<List<Entity>>();
    List<List<Entity>> entityListList1 = new List<List<Entity>>();
    List<List<Entity>> entityListList2 = new List<List<Entity>>();
    Groups.Clear();
    Groups = new List<EntitiesGroup>();
    this.SortEntitiesByRefPoint(RefPoint, ref AllEntities, Settings, ref SortedEntities, ref Result);
    this.EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
    for (int index = 0; index <= SplitedEntitites.Count - 1; ++index)
    {
      if (((F_AnalyseResult) this).isEntitiesClosed(SplitedEntitites[index]))
        entityListList1.Add(buVector5.CopyEntities(SplitedEntitites[index]));
      else
        entityListList2.Add(buVector5.CopyEntities(SplitedEntitites[index]));
    }
    SplitedEntitites.Clear();
    if (entityListList1.Count <= 0)
      return;
    List<bool> boolList = new List<bool>();
    for (int index = 0; index <= entityListList1.Count - 1; ++index)
      boolList.Add(false);
    for (int index1 = 0; index1 <= entityListList1.Count - 1; ++index1)
    {
      List<int> intList = new List<int>();
      bool flag1 = false;
      bool flag2 = false;
      for (int index2 = 0; index2 <= entityListList1.Count - 1; ++index2)
      {
        if (index1 != index2)
        {
          bool flag3 = this.isEntitiesGroupInsideEntities(entityListList1[index1], entityListList1[index2], refPlane);
          flag1 |= flag3;
        }
      }
      for (int index3 = 0; index3 <= entityListList1.Count - 1; ++index3)
      {
        if (index1 != index3)
        {
          bool flag4 = this.isEntitiesGroupInsideEntities(entityListList1[index3], entityListList1[index1], refPlane);
          flag2 |= flag4;
        }
      }
      if (flag1)
      {
        EntitiesGroup entitiesGroup = (EntitiesGroup) new buEntitiesGroup();
        buVector5.CopyEntities(entityListList1[index1], ref ((buEntitiesGroup) entitiesGroup).Outside);
        Groups.Add(entitiesGroup);
        boolList[index1] = true;
      }
      if (!flag1 & !flag2)
      {
        EntitiesGroup entitiesGroup = (EntitiesGroup) new buEntitiesGroup();
        buVector5.CopyEntities(entityListList1[index1], ref ((buEntitiesGroup) entitiesGroup).Outside);
        Groups.Add(entitiesGroup);
        boolList[index1] = true;
      }
    }
    for (int index4 = 0; index4 <= Groups.Count - 1; ++index4)
    {
      for (int index5 = 0; index5 <= entityListList1.Count - 1; ++index5)
      {
        if (!boolList[index5] && this.isEntitiesGroupInsideEntities(((buEntitiesGroup) Groups[index4]).Outside, entityListList1[index5], refPlane))
        {
          List<Entity> copiedEnt = new List<Entity>();
          buVector5.CopyEntities(entityListList1[index5], ref copiedEnt);
          ((buEntitiesGroup) Groups[index4]).Inside.Add(copiedEnt);
        }
      }
    }
  }

