  public bool GetClosestIntersectPointsFromEntities(
    List<Entity> EntityList,
    Entity entityIntersect,
    Point3D refPoint,
    double Angle,
    ref List<Point3D> pntIntersect,
    ref PointAndAngleRange pntRange,
    ref int EntityIndex,
    ref List<PointAndIndex> touchDomainPoints)
  {
    try
    {
      List<PointAndIndex> lst = new List<PointAndIndex>();
      for (int index1 = 0; index1 <= EntityList.Count - 1; ++index1)
      {
        Point3D[] point3DArray = ((ICurve) entityIntersect).IntersectWith((ICurve) EntityList[index1]);
        if (point3DArray != null && point3DArray.Length != 0)
        {
          for (int index2 = 0; index2 <= point3DArray.Length - 1; ++index2)
          {
            PointAndIndex pointAndIndex = (PointAndIndex) new ShapeCreateParameters(point3DArray[index2], index1);
            lst.Add(pointAndIndex);
          }
        }
      }
      if (lst.Count <= 0)
        return false;
      List<PointAndIndex> pointAndIndexList = this.SortByDistance(lst, (PointAndIndex) new ShapeCreateParameters(refPoint, -1));
      int index3 = 1;
      if (Point3D.Distance(((ViewportSettings) pointAndIndexList[0]).refPoint, refPoint) > 0.1)
        index3 = 0;
      if (!(index3 >= 0 & pointAndIndexList.Count > 0))
        return false;
      int index4 = ((ViewportSettings) pointAndIndexList[index3]).Index;
      double t = 0.0;
      double num1 = Angle + 180.0;
      if (num1 >= 360.0)
        num1 -= 360.0;
      ((ICurve) EntityList[index4]).ClosestPointTo(((ViewportSettings) pointAndIndexList[index3]).refPoint, out t);
      bool flag = true;
      for (int index5 = 0; index5 <= touchDomainPoints.Count - 1; ++index5)
      {
        double num2 = Math.Abs(((ViewportSettings) touchDomainPoints[index5]).DomainValue - t);
        if (((ViewportSettings) pointAndIndexList[index3]).Index == ((ViewportSettings) touchDomainPoints[index5]).Index && num2 < 5.0)
          flag = false;
      }
      if (!(t - ((ICurve) EntityList[index4]).Domain.t0 > 0.2 & ((ICurve) EntityList[index4]).Domain.t1 - t > 0.2 & flag))
        return false;
      Point3D TipPoint1 = ((ICurve) EntityList[index4]).PointAt(t - 0.2);
      Point3D TipPoint2 = ((ICurve) EntityList[index4]).PointAt(t + 0.2);
      double num3 = this.PointAngle(TipPoint1, ((ViewportSettings) pointAndIndexList[index3]).refPoint, Plane.XY);
      double num4 = this.PointAngle(TipPoint2, ((ViewportSettings) pointAndIndexList[index3]).refPoint, Plane.XY);
      if (buConversion5.EQ(num3 <= num4 ? num4 - num3 : num3 - num4, 180.0, 0.1))
      {
        if (num3 > num4)
        {
          double num5 = num3;
          num3 = num4;
          num4 = num5;
        }
        if (num1 < num3 | num1 > num4)
        {
          double num6 = num3;
          num3 = num4;
          num4 = num6 + 360.0;
          if (num3 > 360.0 & num4 > 360.0)
          {
            num3 -= 360.0;
            num4 -= 360.0;
          }
        }
        pntRange = (PointAndAngleRange) new DiameterDepthPoint();
        if (num3 < num4)
        {
          ((ViewportSettings) pntRange).AngleMin = num3;
          ((ViewportSettings) pntRange).AngleMax = num4;
        }
        else
        {
          ((ViewportSettings) pntRange).AngleMin = num4;
          ((ViewportSettings) pntRange).AngleMax = num3;
        }
        if (buConversion5.EQ(((ViewportSettings) pntRange).AngleMax, 0.0, 0.1))
          ;
        ((ViewportSettings) pntRange).refPoint = F_NotchEdit.ToPoint3D(((ViewportSettings) pointAndIndexList[index3]).refPoint);
        touchDomainPoints.Add((PointAndIndex) new SortSettings(((ViewportSettings) pointAndIndexList[index3]).refPoint, ((ViewportSettings) pointAndIndexList[index3]).Index, t));
        EntityIndex = index4;
      }
      return true;
    }
    catch (Exception ex)
    {
      return false;
    }
  }

