  public void CreateMaterialEntities(MaterialBase5 Material, ref Entity Ent)
  {
    if (((SortAskMe) Material).Shapes == MaterialShapes.Rectangle)
    {
      CompositeCurve rectangle = CompositeCurve.CreateRectangle(((SortResult) Material).Size.Width, ((SortResult) Material).Size.Height);
      Entity entSurface = (Entity) null;
      this.surfaceFromOutterInner((ICurve) rectangle, (List<ICurve>) null, ((SortResult) Material).Size.Depth, ref entSurface);
      entSurface.Color = ((SortOptions) Material).Display.SkinColor;
      entSurface.ColorMethod = colorMethodType.byEntity;
      entSurface.Rotate(buString5.DegreeToRadian(((SortAskMe) Material).Angle), Vector3D.AxisZ);
      Ent = entSurface;
    }
    else if (((SortAskMe) Material).Shapes == MaterialShapes.Circle)
    {
      Circle Outters = new Circle(new Point3D(), ((SortAskMe) Material).Diameter / 2.0);
      Outters.Translate(((SortAskMe) Material).Diameter / 2.0, ((SortAskMe) Material).Diameter / 2.0);
      Entity entSurface = (Entity) null;
      this.surfaceFromOutterInner((ICurve) Outters, (List<ICurve>) null, ((SortResult) Material).Size.Depth, ref entSurface);
      entSurface.Color = ((SortOptions) Material).Display.SkinColor;
      entSurface.ColorMethod = colorMethodType.byEntity;
      Ent = entSurface;
    }
    else if (((SortAskMe) Material).Shapes == MaterialShapes.Ellipse)
    {
      Ellipse Outters = new Ellipse(new Point3D(), ((SortAskMe) Material).MajorRadius, ((SortAskMe) Material).MinorRadius);
      Outters.Translate(((SortAskMe) Material).MajorRadius, ((SortAskMe) Material).MinorRadius);
      Entity entSurface = (Entity) null;
      this.surfaceFromOutterInner((ICurve) Outters, (List<ICurve>) null, ((SortResult) Material).Size.Depth, ref entSurface);
      entSurface.Color = ((SortOptions) Material).Display.SkinColor;
      entSurface.ColorMethod = colorMethodType.byEntity;
      entSurface.Rotate(buString5.DegreeToRadian(((SortAskMe) Material).Angle), Vector3D.AxisZ);
      Ent = entSurface;
    }
    else if (((SortAskMe) Material).Shapes == MaterialShapes.Irregular)
    {
      LinearPath Outters = new LinearPath((ICollection<Point3D>) ((SortOptions) Material).Points);
      Entity entSurface = (Entity) null;
      if (((SortOptions) Material).Points.Count < 3)
        return;
      this.surfaceFromOutterInner((ICurve) Outters, (List<ICurve>) null, ((SortResult) Material).Size.Depth, ref entSurface);
      entSurface.Color = ((SortOptions) Material).Display.SkinColor;
      entSurface.ColorMethod = colorMethodType.byEntity;
      entSurface.Rotate(buString5.DegreeToRadian(((SortAskMe) Material).Angle), Vector3D.AxisZ);
      Ent = entSurface;
    }
    else if (((SortAskMe) Material).Shapes == MaterialShapes.RectangleRound)
    {
      CompositeCurve roundedRectangle = CompositeCurve.CreateRoundedRectangle(((SortResult) Material).Size.Width, ((SortResult) Material).Size.Height, ((SortAskMe) Material).Radius);
      roundedRectangle.Regen(0.01);
      Entity entSurface = (Entity) null;
      this.surfaceFromOutterInner((ICurve) roundedRectangle, (List<ICurve>) null, ((SortResult) Material).Size.Depth, ref entSurface);
      entSurface.Color = ((SortOptions) Material).Display.SkinColor;
      entSurface.ColorMethod = colorMethodType.byEntity;
      entSurface.Rotate(buString5.DegreeToRadian(((SortAskMe) Material).Angle), Vector3D.AxisZ);
      Ent = entSurface;
    }
    else
    {
      if (((SortAskMe) Material).Shapes != MaterialShapes.RectangleChamfer)
        return;
      this.RectangleChamfer(new Point3D(), new Point3D(((SortResult) Material).Size.Width, ((SortResult) Material).Size.Height), ((SortAskMe) Material).ChamferLength, Plane.XY, ref ((SortOptions) Material).Points);
      LinearPath Outters = new LinearPath((ICollection<Point3D>) ((SortOptions) Material).Points);
      Entity entSurface = (Entity) null;
      if (((SortOptions) Material).Points.Count < 3)
        return;
      this.surfaceFromOutterInner((ICurve) Outters, (List<ICurve>) null, ((SortResult) Material).Size.Depth, ref entSurface);
      entSurface.Color = ((SortOptions) Material).Display.SkinColor;
      entSurface.ColorMethod = colorMethodType.byEntity;
